-- TYLKO ŚRODOWISKO TEST (Supabase tkbpvonxfivfzpkqvilz). Uruchomić w SQL Editor.
-- Idempotentne. Plan roku IX 2026–VII 2027 + lekcje 2.11.2026–15.01.2027 (297).
begin;
alter table public.test_lessons add column if not exists week_start date;
alter table public.test_lessons add column if not exists content jsonb;
create index if not exists test_lessons_week_idx on public.test_lessons(week_start);
create table if not exists public.test_year_plan(id text primary key, week int not null, week_start date not null, week_end date not null, month text, theme text not null, holidays text, season text);
alter table public.test_year_plan enable row level security;
revoke all on public.test_year_plan from anon, authenticated;
-- zl_sync czyta tylko tabele z tej listy (zgodne z hardening.sql + test_year_plan):
create or replace function public.zl_sync_tables() returns text[] language sql immutable set search_path = public as $$
  select array['test_staff','test_children','test_attendance','test_outdoor','test_lessons','test_endofday','test_links',
   'test_lesson_links','test_events_child','test_groups','test_lesson_group','test_settings','test_director_changes','test_events',
   'test_messages','test_destinations','test_accounts','test_daycard','test_menu','test_child_profile','test_absences',
   'test_child_media','test_parent_msgs','test_admin_inbox','test_year_plan'] $$;
delete from public.test_year_plan where week_start >= '2027-08-01';
commit;
-- Wycofanie: delete from public.test_lessons where content is not null; drop table public.test_year_plan; (i przywróć zl_sync_tables z hardening.sql)
