insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('11d0317b-b15a-5fe0-82e1-7699c2736e3b','Ruch','Rączki w górę, rączki w dół',false,false,'2026-11-02','{"id": "2026-11-02-ruch", "day": "2026-11-02", "weekday": null, "option": 1, "title": "Rączki w górę, rączki w dół", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy naśladowanie ruchu i nazywanie części ciała.", "materials": "brak", "steps": ["Stańcie swobodnie.", "Wydawaj polecenia: ręce w górę, w dół, na boki, schowaj za plecy.", "Dzieci naśladują.", "Na „wiatr” – machacie rękami i biegacie."], "easier": "Opiekunka trzyma dziecko za rączki i razem podnoszą je w górę i w dół.", "harder": "Dziecko wykonuje polecenia bez pokazywania przez opiekunkę.", "variant_1y": "Opiekunka trzyma dziecko za rączki i razem podnoszą je w górę i w dół.", "variant_2_3y": "Dziecko wykonuje polecenia bez pokazywania przez opiekunkę.", "song": "Rączki w górę – hop do słonka, / rączki w dół – do trawki z łąki. / Rączki w bok – jak skrzydła ptaka, / schowaj z tyłu – gdzie jest? Taka!", "song_author": "własna (KMK/Malachim)", "safety": "Wolna przestrzeń bez mebli z ostrymi rogami; przy „wietrze” biegamy w jedną stronę, żeby dzieci nie zderzały się.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-03-4", "reused_from": "2026-11-02-03-4", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c77ee677-c2c5-502d-822d-99f0e080c8f8','Muzyka','Bębenek ciała',false,false,'2026-11-02','{"id": "2026-11-02-muzyka", "day": "2026-11-02", "weekday": null, "option": 2, "title": "Bębenek ciała", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Rozwija poczucie rytmu i świadomość ciała.", "materials": "bębenek lub garnek i drewniana łyżka", "steps": ["Wystukaj rytm na bębenku.", "Dzieci powtarzają rytm klaskaniem.", "Potem tupią, potem klepią kolana.", "Na koniec cicho, palcami po brzuszku."], "easier": "Swobodne klaskanie na kolanach opiekunki.", "harder": "Dziecko powtarza rytm 3 uderzeń i samo gra na bębenku.", "variant_1y": "Swobodne klaskanie na kolanach opiekunki.", "variant_2_3y": "Dziecko powtarza rytm 3 uderzeń i samo gra na bębenku.", "song": "Bum, bum – bębenek gra, / klap, klap – rączka ma, / tup, tup – nóżka ma, / cichutko – brzuszek: ha, ha, ha!", "song_author": "własna (KMK/Malachim)", "safety": "Łyżka drewniana bez drzazg; dziecko nie wkłada jej głęboko do buzi; uderzamy w bębenek, nie w inne dzieci.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-02-3", "reused_from": "2026-11-02-02-3", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7be88b08-0690-5e09-9212-f6c4f63858ad','Sensoryka','Kocyk-dotyk',false,false,'2026-11-02','{"id": "2026-11-02-sensoryka", "day": "2026-11-02", "weekday": null, "option": 3, "title": "Kocyk-dotyk", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Pobudza zmysł dotyku i uczy nazywać części ciała.", "materials": "kocyk, duże piórko (ptasie zastąpić sztucznym dużym pióropuszem), gąbka, miękka szczoteczka", "steps": ["Dziecko siada lub leży na kocyku.", "Delikatnie dotykaj rąk, stóp i brzucha różnymi przedmiotami.", "Nazywaj część ciała i odczucie: „miękkie na rączce”.", "Zamień się – dziecko dotyka misia."], "easier": "Tylko gąbka i dłoń opiekunki, krótko, na leżąco.", "harder": "Dziecko z zamkniętymi oczami zgaduje, gdzie dotknięto.", "variant_1y": "Tylko gąbka i dłoń opiekunki, krótko, na leżąco.", "variant_2_3y": "Dziecko z zamkniętymi oczami zgaduje, gdzie dotknięto.", "song": "Miękko po rączce, / gładko po nóżce, / łaskotki w brzuszek – / i cmok w paluszek!", "song_author": "własna (KMK/Malachim)", "safety": "Pióro i szczoteczka zostają w ręku opiekunki; przerwij, gdy dziecko nie chce dotyku.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-02-5", "reused_from": "2026-11-02-02-5", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('1c3e05c1-72b1-5452-b0ee-432330c223b4','Emocje','Wesoła i smutna minka',false,false,'2026-11-02','{"id": "2026-11-02-emocje", "day": "2026-11-02", "weekday": null, "option": 4, "title": "Wesoła i smutna minka", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Rozpoznaje dwie podstawowe emocje na twarzy.", "materials": "duże obrazki z minkami (zalaminowane), lusterko bezpieczne (akrylowe)", "steps": ["Pokaż obrazki: wesoła i smutna.", "Zrób wesołą minę – dzieci naśladują.", "Zrób smutną – naśladują.", "Zapytaj „Kiedy jesteś wesoły?”."], "easier": "Dziecko patrzy w lusterko, opiekunka robi miny obok.", "harder": "Dziecko wskazuje obrazek do miny i mówi, kiedy jest wesołe.", "variant_1y": "Dziecko patrzy w lusterko, opiekunka robi miny obok.", "variant_2_3y": "Dziecko wskazuje obrazek do miny i mówi, kiedy jest wesołe.", "song": "Gdy się cieszę – buzia w górę, / gdy mi smutno – buzia w dół. / Gdy mi smutno, przytul mnie, / zaraz uśmiech wróci się!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko lusterko akrylowe, nietłukące.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-05-1", "reused_from": "2026-11-02-05-1", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('39b51173-b405-50b7-931a-ad39d39c9fb8','Zmysły','Węszymy nosem',false,false,'2026-11-02','{"id": "2026-11-02-zmysly", "day": "2026-11-02", "weekday": null, "option": 5, "title": "Węszymy nosem", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozwija węch i nazywanie zapachów.", "materials": "3–4 zakręcane słoiczki z dziurkami w wieczku: skórka cytryny, laska cynamonu, jabłko", "steps": ["Pokaż nos: „nosem wąchamy”.", "Dzieci wąchają po kolei słoiczek.", "Nazywaj zapach i robisz minę (lubię/nie lubię).", "Pokaż owoc, który pachniał."], "easier": "Tylko 2 zapachy, słoiczek trzyma opiekunka.", "harder": "Dziecko dopasowuje zapach do obrazka owocu.", "variant_1y": "Tylko 2 zapachy, słoiczek trzyma opiekunka.", "variant_2_3y": "Dziecko dopasowuje zapach do obrazka owocu.", "song": "Nosek wącha: niuch, niuch, niuch, / co tu pachnie? Duch czy ruch? / Jabłko, cytryna, cynamon – / nosek wie, co jest w nim schowane!", "song_author": "własna (KMK/Malachim)", "safety": "Słoiki plastikowe, zakręcone; zawartości dziecko nie dostaje do ręki; nie używaj olejków eterycznych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-04-6", "reused_from": "2026-11-02-04-6", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f06dc883-4867-5be4-90de-0e6eeb1c9751','Zwierzęta','Jak zwierzątka dbają o siebie',false,false,'2026-11-02','{"id": "2026-11-02-zwierzeta", "day": "2026-11-02", "weekday": null, "option": 6, "title": "Jak zwierzątka dbają o siebie", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Łączy dbanie o ciało z ruchami zwierząt.", "materials": "duże obrazki: kot, pies, ptak", "steps": ["Pokaż obrazek kota: kotek myje łapką buzię.", "Dzieci „myją” buzię dłonią.", "Piesek otrząsa się z wody – trzęsiemy całym ciałem.", "Ptaszek czyści piórka – głaszczemy ramiona.", "Na koniec mówimy: „my też myjemy rączki”."], "easier": "Opiekunka robi ruchy rękami dziecka, dziecko patrzy na obrazki.", "harder": "Dziecko samo pokazuje zwierzę i naśladuje jego dźwięk.", "variant_1y": "Opiekunka robi ruchy rękami dziecka, dziecko patrzy na obrazki.", "variant_2_3y": "Dziecko samo pokazuje zwierzę i naśladuje jego dźwięk.", "song": "Kotek łapką myje uszko, / piesek drapie się po brzuszku, / ptaszek dziobkiem piórka czyści – / a my? My też jesteśmy czyści!", "song_author": "własna (KMK/Malachim)", "safety": "Przy „otrząsaniu” zachowaj odstęp między dziećmi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('dee50909-052a-5e95-9127-de3f2328844d','Pogoda','Deszczyk, słonko, wiaterek na plecach',false,false,'2026-11-02','{"id": "2026-11-02-pogoda", "day": "2026-11-02", "weekday": null, "option": 7, "title": "Deszczyk, słonko, wiaterek na plecach", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Łączy zjawiska pogody z czuciem dotyku na ciele.", "materials": "brak (mata)", "steps": ["Dzieci siadają przodem, opiekunka za dzieckiem.", "„Deszcz” – stukamy palcami po plecach.", "„Słońce” – rysujemy dłonią duże koło.", "„Wiatr” – dmuchamy lekko na kark i rączki.", "Zamiana: dziecko robi „pogodę” misiowi."], "easier": "Na kolanach opiekunki, bardzo delikatnie.", "harder": "Dziecko robi masażyk koledze lub misiowi i mówi „pada / świeci / wieje”.", "variant_1y": "Na kolanach opiekunki, bardzo delikatnie.", "variant_2_3y": "Dziecko robi masażyk koledze lub misiowi i mówi „pada / świeci / wieje”.", "song": "Kap, kap – deszczyk pada, / słonko ciepło nas zagada, / wieje wiatr: fiu, fiu, fiu – / gdzie poczujesz? Tu, tu, tu!", "song_author": "własna (KMK/Malachim)", "safety": "Delikatny dotyk; nie dmuchamy w twarz; przerwij, jeśli dziecko się odsuwa.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a22cb923-1175-5c18-aa4a-8fb56f8448a5','Przyroda','Listek jak moja rączka',false,false,'2026-11-02','{"id": "2026-11-02-przyroda", "day": "2026-11-02", "weekday": null, "option": 8, "title": "Listek jak moja rączka", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Obserwuje liście i porównuje je z własną dłonią.", "materials": "duże liście klonu (zebrane, umyte), kartka", "steps": ["Pokaż duży liść klonu.", "Przyłóż go do dłoni dziecka: „Ile ma czubków? Ile masz paluszków?”.", "Dzieci głaszczą liść: gładki czy szorstki?", "Porównujcie: czyja rączka jest większa – liścia czy dziecka?", "Liście kładziemy na oknie albo w kąciku przyrody."], "easier": "Dziecko dotyka liścia i szeleści nim.", "harder": "Dziecko wybiera liść większy / mniejszy od swojej dłoni.", "variant_1y": "Dziecko dotyka liścia i szeleści nim.", "variant_2_3y": "Dziecko wybiera liść większy / mniejszy od swojej dłoni.", "song": "Moja rączka, listek klonu, / pięć paluszków, pięć ogonów. / Przyłożę rączkę do listka – / jesień jest blisko, bliziutko, bliska!", "song_author": "własna (KMK/Malachim)", "safety": "Liście bez pleśni, umyte; pilnuj, by dzieci nie brały ich do buzi; myjemy ręce po zabawie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4897f642-bf07-5a34-8f82-a4d08fb3c9b5','Eksperymenty','Mój cień',false,false,'2026-11-02','{"id": "2026-11-02-eksperymenty", "day": "2026-11-02", "weekday": null, "option": 9, "title": "Mój cień", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Odkrywa, że ciało robi cień i że cień się zmienia.", "materials": "lampka LED lub latarka, jasna ściana", "steps": ["Zaciemnij trochę salę, zapal lampkę.", "Pokaż cień swojej ręki na ścianie.", "Dziecko macha – cień też macha.", "Podejdź bliżej lampy – cień rośnie; dalej – maleje.", "Robimy cień zajączka z palców."], "easier": "Opiekunka trzyma dziecko na rękach i porusza jego rączką w świetle.", "harder": "Dziecko zgaduje: cień będzie duży czy mały?", "variant_1y": "Opiekunka trzyma dziecko na rękach i porusza jego rączką w świetle.", "variant_2_3y": "Dziecko zgaduje: cień będzie duży czy mały?", "song": "Gdzie ja idę, idzie cień, / bawi się ze mną cały dzień. / Machnę rączką – on też macha, / nikt się cienia tu nie wystrasza!", "song_author": "własna (KMK/Malachim)", "safety": "Lampka zimna (LED), kabel poza zasięgiem; nie świecimy w oczy; nie wyłączamy całego światła – część dzieci boi się ciemności.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('46c8b265-1424-52ed-ab8f-7c53295c8e12','Plastyka','Obrysuj moją dłoń',false,false,'2026-11-02','{"id": "2026-11-02-plastyka", "day": "2026-11-02", "weekday": null, "option": 10, "title": "Obrysuj moją dłoń", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Rozwija rękę i poznawanie własnej dłoni.", "materials": "kartki A4, grube kredki świecowe (jumbo), flamaster dla opiekunki", "steps": ["Obrysuj dłoń dziecka na kartce.", "Dziecko koloruje obrys grubymi kredkami.", "Nazywaj palce.", "Podpisz pracę imieniem."], "easier": "Opiekunka obrysowuje, dziecko swobodnie bazgra.", "harder": "Dziecko koloruje wnętrze obrysu i pokazuje palce.", "variant_1y": "Opiekunka obrysowuje, dziecko swobodnie bazgra.", "variant_2_3y": "Dziecko koloruje wnętrze obrysu i pokazuje palce.", "song": "Rączka leży na papierze, / kredka chodzi po niej szczerze. / Kciuk i palce – raz, dwa, trzy – / to jest moja rączka, wiesz ty?", "song_author": "własna (KMK/Malachim)", "safety": "Kredki jumbo, bez połamanych kawałków; flamaster zostaje u opiekunki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-03-1", "reused_from": "2026-11-02-03-1", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('231dfa3e-aa8a-59f4-995c-bade09fb1c21','Samoobsługa','Sam zdejmuję skarpetki',false,false,'2026-11-02','{"id": "2026-11-02-samoobsluga", "day": "2026-11-02", "weekday": null, "option": 11, "title": "Sam zdejmuję skarpetki", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy samodzielne zdejmowanie skarpet.", "materials": "własne skarpetki dziecka, mata", "steps": ["Dzieci siadają na macie.", "Pokaż: łapiemy skarpetkę za palce i ciągniemy.", "Dziecko próbuje samo, z pomocą słowną.", "Wkładamy skarpetki do butów.", "Chwalimy każdą próbę."], "easier": "Opiekunka zsuwa skarpetkę do połowy, dziecko kończy.", "harder": "Dziecko zdejmuje i próbuje założyć skarpetkę z powrotem.", "variant_1y": "Opiekunka zsuwa skarpetkę do połowy, dziecko kończy.", "variant_2_3y": "Dziecko zdejmuje i próbuje założyć skarpetkę z powrotem.", "song": "Ciągnę, ciągnę za paluszki, / już na wierzchu gołe nóżki! / Skarpetka do bucika – hop, / teraz robię: tup, tup, stop!", "song_author": "własna (KMK/Malachim)", "safety": "Podłoga ciepła i czysta lub mata; bez chodzenia w samych skarpetkach po śliskiej podłodze.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('bf2b3906-175c-5145-8acf-0aa959b379b9','Język/logorytmika','Języczek i dmuchanie',false,false,'2026-11-02','{"id": "2026-11-02-jezyk-logorytmika", "day": "2026-11-02", "weekday": null, "option": 12, "title": "Języczek i dmuchanie", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy język, wargi i oddech (przygotowanie do mowy).", "materials": "bańki mydlane, duże piórko (w ręku opiekunki)", "steps": ["Ćwiczenia: język na górę, w dół, kląskanie.", "Dmuchajcie piórko po stole.", "Opiekunka puszcza bańki – dzieci dmuchają/łapią.", "Nazywaj: usta, język, zęby."], "easier": "Tylko dmuchanie na piórko trzymane przez opiekunkę i łapanie baniek.", "harder": "Ruchy języka przed lusterkiem i kląskanie.", "variant_1y": "Tylko dmuchanie na piórko trzymane przez opiekunkę i łapanie baniek.", "variant_2_3y": "Ruchy języka przed lusterkiem i kląskanie.", "song": "Języczek w górę, języczek w dół, / dmucham piórko przez cały stół. / Kląskam jak konik: kla, kla, kla, / bańka leci – łapię ja!", "song_author": "własna (KMK/Malachim)", "safety": "Płyn do baniek trzyma opiekunka; nie dmuchamy baniek w twarz; piórko nie trafia do buzi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-04-7", "reused_from": "2026-11-02-04-7", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f0cc4af8-dc67-56e8-b916-7e614d0ed9b9','Zabawy paluszkowe i masażyki','Paluszki idą spać',false,false,'2026-11-02','{"id": "2026-11-02-zabawy-paluszkowe-i-masazyki", "day": "2026-11-02", "weekday": null, "option": 13, "title": "Paluszki idą spać", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Rozwija ruchy palców i wycisza.", "materials": "brak", "steps": ["Usiądź z dzieckiem twarzą w twarz.", "Pokazuj po kolei palce przy rymowance.", "Każdy palec „zasypia” – zginamy go.", "Na końcu cała piąstka śpi.", "Budzimy paluszki: „dzień dobry!”."], "easier": "Opiekunka zgina palce dziecka.", "harder": "Dziecko samo zgina palce i mówi „cii”.", "variant_1y": "Opiekunka zgina palce dziecka.", "variant_2_3y": "Dziecko samo zgina palce i mówi „cii”.", "song": "Ten paluszek ziewa – ach! / Ten się kładzie – bach! / Ten się kryje pod kołderką, / ten się zwija jak kółeczko, / a najmniejszy szepcze: cii… / wszystkie paluszki już śpią!", "song_author": "własna (KMK/Malachim)", "safety": "Delikatnie, bez wyginania palców na siłę.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('463e56d7-4d69-5dd3-a124-0fc47d27c173','Zabawy słowno-ruchowe i rymowanki','Tup, klap, hop!',false,false,'2026-11-02','{"id": "2026-11-02-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-11-02", "weekday": null, "option": 14, "title": "Tup, klap, hop!", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Łączy słowo z ruchem i uczy zatrzymania na sygnał.", "materials": "brak", "steps": ["Stańcie w kole.", "Mów rymowankę i pokazuj ruchy.", "Na „stop!” wszyscy zamierają.", "Powtórz szybciej i wolniej.", "Na koniec siadamy."], "easier": "Tupanie i klaskanie na kolanach opiekunki.", "harder": "Dziecko mówi rymowankę i samo daje sygnał „stop”.", "variant_1y": "Tupanie i klaskanie na kolanach opiekunki.", "variant_2_3y": "Dziecko mówi rymowankę i samo daje sygnał „stop”.", "song": "Nóżki robią tup, tup, tup, / rączki robią klap, klap, klap, / całe ciało hop, hop, hop, / a na koniec – stop!", "song_author": "własna (KMK/Malachim)", "safety": "Skaczemy w miejscu, na macie; nie na śliskiej podłodze.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('eb515bb7-3fde-5c09-ba13-ec69341ed164','Powitania i integracja','Dzień dobry, rączko!',false,false,'2026-11-02','{"id": "2026-11-02-powitania-i-integracja", "day": "2026-11-02", "weekday": null, "option": 15, "title": "Dzień dobry, rączko!", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Buduje poczucie bycia w grupie i nazywanie ciała.", "materials": "brak", "steps": ["Siadamy w kole.", "Opiekunka wita się z częścią ciała: „Dzień dobry, rączko”.", "Dzieci machają rączką.", "Potem nóżki, brzuszki, uszka.", "Na koniec witamy się imionami."], "easier": "Opiekunka macha rączką dziecka.", "harder": "Dziecko samo wybiera, z czym się witamy.", "variant_1y": "Opiekunka macha rączką dziecka.", "variant_2_3y": "Dziecko samo wybiera, z czym się witamy.", "song": "Dzień dobry, rączko, dzień dobry, nóżko, / dzień dobry, brzuszku i małe uszko! / Dzień dobry, buziu, uśmiechnij się – / (imię) jest z nami, cieszymy się!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych zagrożeń; siedzimy na dywanie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5602b27a-e514-58aa-b0e9-c9fd782d61d9','Świadomość ciała','Gdzie jest nosek?',false,false,'2026-11-02','{"id": "2026-11-02-swiadomosc-ciala", "day": "2026-11-02", "weekday": null, "option": 16, "title": "Gdzie jest nosek?", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Wskazuje i nazywa części twarzy.", "materials": "lalka lub miś", "steps": ["Usiądźcie naprzeciw siebie.", "Pytaj „Gdzie jest nosek?” i pokazuj na sobie.", "Dzieci pokazują na sobie.", "Starsze odpowiadają „Tu jest nosek”."], "easier": "Dziecko pokazuje na lalce z pomocą.", "harder": "Dziecko nazywa wskazaną część ciała.", "variant_1y": "Dziecko pokazuje na lalce z pomocą.", "variant_2_3y": "Dziecko nazywa wskazaną część ciała.", "song": "Gdzie jest nosek? Tu jest nosek! / Gdzie jest oczko? Tu jest oczko! / Gdzie są uszka? Tu i tu – / zaraz pokaż mi buzię swą!", "song_author": "własna (KMK/Malachim)", "safety": "Nie wkładamy palców do oczu i uszu – tylko delikatnie pokazujemy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-04-1", "reused_from": "2026-11-02-04-1", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0b69f765-edba-5337-8700-b545cc1d0b63','Pamięć/uwaga/naśladowanie','Misiu, rób jak ja',false,false,'2026-11-02','{"id": "2026-11-02-pamiec-uwaga-nasladowanie", "day": "2026-11-02", "weekday": null, "option": 17, "title": "Misiu, rób jak ja", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy uważne patrzenie i naśladowanie.", "materials": "pluszowy miś", "steps": ["Miś „pokazuje” ruch: skacze, kręci głową, macha nogą.", "Dzieci naśladują.", "Nazywaj część ciała w ruchu.", "Kończy się „miś śpi” – leżymy."], "easier": "Ruch z pomocą opiekunki.", "harder": "Dziecko prowadzi misia i pokazuje ruch innym.", "variant_1y": "Ruch z pomocą opiekunki.", "variant_2_3y": "Dziecko prowadzi misia i pokazuje ruch innym.", "song": "Miś podskoczy – my skaczemy, / miś się kręci – też kręcimy, / miś się kładzie – my leżymy, / cicho, cicho, wszyscy śpimy.", "song_author": "własna (KMK/Malachim)", "safety": "Kręcenie powoli, 1–2 obroty, żeby nie było zawrotów głowy i upadków.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-04-4", "reused_from": "2026-11-02-04-4", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fb07c1ae-6ed3-5dea-826e-86d06b844d24','Zabawy poznawcze','Czyj to bucik?',false,false,'2026-11-02','{"id": "2026-11-02-zabawy-poznawcze", "day": "2026-11-02", "weekday": null, "option": 18, "title": "Czyj to bucik?", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Dopasowuje pary i rozpoznaje swoje rzeczy.", "materials": "buty dzieci z grupy (3–4 pary)", "steps": ["Postaw buty w rzędzie, pomieszane.", "Pytaj: „Gdzie jest drugi bucik?”.", "Dzieci szukają pary.", "Pytaj: „Czyj to bucik?”.", "Dziecko zanosi parę na miejsce."], "easier": "Dziecko szuka tylko swojego buta.", "harder": "Dziecko łączy 3–4 pary i mówi, czyje są.", "variant_1y": "Dziecko szuka tylko swojego buta.", "variant_2_3y": "Dziecko łączy 3–4 pary i mówi, czyje są.", "song": "Lewy bucik, prawy bucik, / każdy bucik ma swój duet. / Gdzie jest drugi? Szukaj go – / już są razem: brawo, o!", "song_author": "własna (KMK/Malachim)", "safety": "Buty czyste; bez sznurówek luźno zwisających w zasięgu buzi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('91fc4468-3a3c-55e1-8de2-d37726371b2a','Zabawy na dworze','Spacer: tupu-tupu',false,false,'2026-11-02','{"id": "2026-11-02-zabawy-na-dworze", "day": "2026-11-02", "weekday": null, "option": 19, "title": "Spacer: tupu-tupu", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Ćwiczy różne sposoby chodzenia i równowagę.", "materials": "ciepłe ubranie", "steps": ["Wyjdźcie na podwórko.", "Chodźcie na palcach, potem tupiąc, potem na piętach.", "Skaczcie do kałuży lub liści.", "Nazywajcie: nogi, stopy, kolana."], "easier": "Chodzenie za rękę, tupanie w miejscu.", "harder": "Skoki obunóż, zatrzymanie na sygnał.", "variant_1y": "Chodzenie za rękę, tupanie w miejscu.", "variant_2_3y": "Skoki obunóż, zatrzymanie na sygnał.", "song": "Na paluszkach – cicho, cicho, / na piętach – tupu, tupu, / skok do liści – szu, szu, szu – / wracamy już, pa, pa, tu!", "song_author": "własna (KMK/Malachim)", "safety": "Sprawdź teren: szkło, psie odchody, kamienie; skoki tylko na płaskim.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-02-7", "reused_from": "2026-11-02-02-7", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('69aadede-3de6-5834-8dd7-d7429d524c02','Higiena','Myjemy rączki – szu, szu',false,false,'2026-11-02','{"id": "2026-11-02-higiena", "day": "2026-11-02", "weekday": null, "option": 20, "title": "Myjemy rączki – szu, szu", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Utrwala mycie rąk krok po kroku.", "materials": "umywalka, mydło w płynie, ręczniki papierowe", "steps": ["Podwijamy rękawy.", "Moczymy ręce i bierzemy mydło.", "Trzemy dłonie, paluszki i między paluszkami przy rymowance.", "Spłukujemy i wycieramy.", "Pokazujemy czyste rączki."], "easier": "Opiekunka myje razem z dzieckiem, ręce w rękach.", "harder": "Dziecko samo myje się przez całą rymowankę.", "variant_1y": "Opiekunka myje razem z dzieckiem, ręce w rękach.", "variant_2_3y": "Dziecko samo myje się przez całą rymowankę.", "song": "Woda szumi: szu, szu, szu, / mydło pieni: plum, plum, plum. / Trę rączki – raz i dwa, / czyste ręce każdy ma!", "song_author": "własna (KMK/Malachim)", "safety": "Letnia woda – sprawdź temperaturę; mokra podłoga = ryzyko poślizgu; mydło poza buzią i oczami.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e003e3c9-f4ec-5af2-93f6-99e7a7493df3','Czytanie dziecku','Książeczka o ciele',false,false,'2026-11-02','{"id": "2026-11-02-czytanie-dziecku", "day": "2026-11-02", "weekday": null, "option": 21, "title": "Książeczka o ciele", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Rozwija słuchanie i rozumienie słów o ciele.", "materials": "kartonowa książeczka z obrazkami dzieci", "steps": ["Usiądźcie razem na dywanie.", "Oglądajcie obrazki.", "Przy każdym pytaj „gdzie masz…?”.", "Dzieci pokazują na sobie."], "easier": "Tylko oglądanie i wskazywanie.", "harder": "Dziecko nazywa, co robi postać na obrazku.", "variant_1y": "Tylko oglądanie i wskazywanie.", "variant_2_3y": "Dziecko nazywa, co robi postać na obrazku.", "song": "Książka otwiera się: szur, szur, / co tam jest? Patrz, nos i brzuch! / Pokaż na sobie, pokaż mi – / czytamy razem: ja i ty.", "song_author": "własna (KMK/Malachim)", "safety": "Książeczki kartonowe, bez odklejających się elementów.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-02-8", "reused_from": "2026-11-02-02-8", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('9e5e2feb-fcca-5122-8362-576df83715bb','Klocki/budowanie','Wieża wysoka jak ja',false,false,'2026-11-02','{"id": "2026-11-02-klocki-budowanie", "day": "2026-11-02", "weekday": null, "option": 22, "title": "Wieża wysoka jak ja", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje wieżę i porównuje ją z ciałem.", "materials": "duże klocki piankowe lub kartonowe", "steps": ["Siadamy na dywanie przy klockach.", "Budujemy wieżę razem.", "Sprawdzamy: wieża już do kolana? do brzuszka?", "Dziecko burzy wieżę – „bęc!”.", "Budujemy znowu."], "easier": "Dziecko kładzie 2–3 klocki i burzy.", "harder": "Dziecko buduje wieżę do brzucha i liczy klocki z opiekunką.", "variant_1y": "Dziecko kładzie 2–3 klocki i burzy.", "variant_2_3y": "Dziecko buduje wieżę do brzucha i liczy klocki z opiekunką.", "song": "Klocek, klocek, raz i dwa, / wieża rośnie – ojej ha! / Do kolanka, do brzuszka… / bęc! I wieża leży – co za uciecha!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko duże, lekkie klocki; wieża nie wyżej niż do pasa; burzymy w stronę wolną od dzieci.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c2dab6db-191b-5a6c-b1d8-df2a69878c15','Wyciszenie','Brzuszek jak balonik',false,false,'2026-11-02','{"id": "2026-11-02-wyciszenie", "day": "2026-11-02", "weekday": null, "option": 23, "title": "Brzuszek jak balonik", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Uczy spokojnego oddechu i wyciszenia.", "materials": "mały miś dla każdego dziecka, mata", "steps": ["Dzieci kładą się na plecach.", "Na brzuszek kładziemy misia.", "Wdech nosem – brzuszek rośnie, miś jedzie w górę.", "Wydech – miś zjeżdża w dół.", "Kilka oddechów i leżymy cicho."], "easier": "Dziecko leży obok opiekunki, która kładzie rękę na jego brzuszku.", "harder": "Dziecko liczy z opiekunką do 3 przy wydechu.", "variant_1y": "Dziecko leży obok opiekunki, która kładzie rękę na jego brzuszku.", "variant_2_3y": "Dziecko liczy z opiekunką do 3 przy wydechu.", "song": "Wdech – balonik rośnie, / wydech – miś zjeżdża radośnie. / Cicho, cicho, raz i dwa – / spokój w brzuszku mam i ja.", "song_author": "własna (KMK/Malachim)", "safety": "Nie wymuszamy leżenia; misie bez oczu na guziki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('deba0483-0e98-539b-8622-de2eaa243fc5','Empatia','Zabawa w przytulanie',false,false,'2026-11-02','{"id": "2026-11-02-empatia", "day": "2026-11-02", "weekday": null, "option": 24, "title": "Zabawa w przytulanie", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy pocieszania i okazywania czułości.", "materials": "miś, kocyk", "steps": ["Miś jest smutny – co robimy?", "Dzieci przytulają, głaszczą misia.", "Miś jest wesoły – pokazujemy uśmiech.", "Rozmowa: co nas cieszy."], "easier": "Dziecko przytula misia razem z opiekunką.", "harder": "Dziecko mówi jedno słowo, co pociesza („przytul”, „kocyk”).", "variant_1y": "Dziecko przytula misia razem z opiekunką.", "variant_2_3y": "Dziecko mówi jedno słowo, co pociesza („przytul”, „kocyk”).", "song": "Miś jest smutny, łezka spada, / kto go przytuli? – cała gromada! / Pogłaszczemy, damy kocyk – / miś się śmieje: hop, podskoczy!", "song_author": "własna (KMK/Malachim)", "safety": "Przytulamy misia, a innych dzieci tylko wtedy, gdy chcą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "reuse:2026-11-02-05-6", "reused_from": "2026-11-02-05-6", "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d0befd70-cc91-59fb-9354-08fb1d2a05ac','Rodzina i dom','Duże ręce, małe ręce',false,false,'2026-11-02','{"id": "2026-11-02-rodzina-i-dom", "day": "2026-11-02", "weekday": null, "option": 25, "title": "Duże ręce, małe ręce", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Poznaje członków rodziny i porównuje ciało dużych i małych.", "materials": "zdjęcia rodzin (przyniesione z domu, za zgodą rodziców)", "steps": ["Oglądamy zdjęcie rodziny dziecka.", "Pytamy: „Kto ma duże ręce? Kto ma małe?”.", "Przykładamy dłoń dziecka do dłoni opiekunki.", "Mówimy, co robią ręce w domu: tata gotuje, mama przytula, ja się bawię.", "Zdjęcie trafia na tablicę."], "easier": "Dziecko pokazuje palcem mamę/tatę na zdjęciu.", "harder": "Dziecko mówi, kto jest na zdjęciu i co robi.", "variant_1y": "Dziecko pokazuje palcem mamę/tatę na zdjęciu.", "variant_2_3y": "Dziecko mówi, kto jest na zdjęciu i co robi.", "song": "Mama ma duże ręce, / tata ma duże ręce, / a ja mam malutkie – / ale je kocham najwięcej!", "song_author": "własna (KMK/Malachim)", "safety": "Zdjęcia w koszulkach foliowych; szanujemy różne modele rodziny – nie zakładamy, że każde dziecko ma mamę i tatę.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f522a549-b529-5b82-aca2-54c2f5059809','Pory roku i święta','Jesienne ubranko dla lalki',false,false,'2026-11-02','{"id": "2026-11-02-pory-roku-i-swieta", "day": "2026-11-02", "weekday": null, "option": 26, "title": "Jesienne ubranko dla lalki", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Łączy jesień z ochroną ciała przed zimnem.", "materials": "lalka, czapka, szalik, rękawiczki (dla lalki lub dziecięce)", "steps": ["Patrzymy za okno: jest zimno, wieje.", "Lalka idzie na spacer – co założy?", "Dzieci po kolei zakładają lalce czapkę (głowa), szalik (szyja), rękawiczki (rączki).", "Nazywamy części ciała.", "Lalka „idzie” na spacer po sali."], "easier": "Dziecko zakłada lalce czapkę z pomocą.", "harder": "Dziecko ubiera całą lalkę i mówi, co gdzie zakłada.", "variant_1y": "Dziecko zakłada lalce czapkę z pomocą.", "variant_2_3y": "Dziecko ubiera całą lalkę i mówi, co gdzie zakłada.", "song": "Na główkę czapka, na szyję szal, / jesienny wiatr nie zrobi nam żal. / Rękawiczki na rączki – / ciepło jest w każdej kosteczce!", "song_author": "własna (KMK/Malachim)", "safety": "Szalik nie zakładamy dzieciom na szyję w zabawie – tylko lalce.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ba5d60b4-993a-514e-8b1d-251b60b10c05','Kolory/kształty/wielkości','Duża dłoń, mała dłoń',false,false,'2026-11-02','{"id": "2026-11-02-kolory-ksztalty-wielkosci", "day": "2026-11-02", "weekday": null, "option": 27, "title": "Duża dłoń, mała dłoń", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Poznaje pojęcia duży – mały.", "materials": "kartki, kredki jumbo, rękawiczki dorosłe i dziecięce", "steps": ["Przykładamy dłoń dziecka do dłoni opiekunki: „duża – mała”.", "Pokazujemy dwie rękawiczki: dużą i małą.", "Dziecko wkłada rączkę do dużej – za luźna!", "Potem do małej – pasuje.", "Sortujemy: duże do kosza, małe do pudełka."], "easier": "Dziecko tylko porównuje dłonie z opiekunką.", "harder": "Dziecko sortuje 6 rzeczy na duże i małe.", "variant_1y": "Dziecko tylko porównuje dłonie z opiekunką.", "variant_2_3y": "Dziecko sortuje 6 rzeczy na duże i małe.", "song": "Duża rączka – to mama ma, / mała rączka – to rączka ma. / Duża, mała, mała, duża – / każda rączka się przyda w podróży!", "song_author": "własna (KMK/Malachim)", "safety": "Rękawiczki bez ozdóbek, które da się oderwać.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ja i moje ciało – dbam o siebie", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4c76d819-26ac-5c8d-8fbf-c129069afc69','Ruch','Orzeł leci nad Polską',false,false,'2026-11-09','{"id": "2026-11-09-ruch", "day": "2026-11-09", "weekday": null, "option": 1, "title": "Orzeł leci nad Polską", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy duże ruchy rąk i bieg w różnym tempie.", "materials": "mata lub koc jako „gniazdo”", "steps": ["Pokaż, jak orzeł rozkłada duże skrzydła.", "Dzieci „lecą” po sali, machając rękami.", "„Wysoko!” – na palcach; „nisko!” – w przysiadzie.", "„Do gniazda!” – wszyscy siadają na kocu.", "Powtórz 3–4 razy."], "easier": "Dziecko „leci” na rękach opiekunki.", "harder": "Dziecko zmienia ruch na hasło bez podpowiedzi.", "variant_1y": "Dziecko „leci” na rękach opiekunki.", "variant_2_3y": "Dziecko zmienia ruch na hasło bez podpowiedzi.", "song": "Leci orzeł, skrzydła duże, / wysoko jak góry, nisko jak kałuże. / Szu, szu, szu – nad polem, nad lasem – / ląduje w gnieździe raz za razem!", "song_author": "własna (KMK/Malachim)", "safety": "Biegamy w jednym kierunku; usuń przeszkody z sali.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fe23cd26-e5af-52b1-850d-17e2702c8c11','Muzyka','Marsz z biało-czerwoną chustą',false,false,'2026-11-09','{"id": "2026-11-09-muzyka", "day": "2026-11-09", "weekday": null, "option": 2, "title": "Marsz z biało-czerwoną chustą", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Rozwija rytm marszu i radość ze święta.", "materials": "chusty lub szarfy białe i czerwone, bębenek", "steps": ["Każde dziecko dostaje chustę białą lub czerwoną.", "Opiekunka gra na bębenku równy rytm.", "Maszerujemy i machamy chustą.", "Gdy bębenek milknie – stoimy i chowamy chustę za plecy.", "Na koniec składamy chusty do kosza."], "easier": "Marsz za rękę z opiekunką, machanie chustą.", "harder": "Dziecko zatrzymuje się na ciszę i zmienia tempo.", "variant_1y": "Marsz za rękę z opiekunką, machanie chustą.", "variant_2_3y": "Dziecko zatrzymuje się na ciszę i zmienia tempo.", "song": "Maszerują nasze nóżki, / biała chusta, czerwone wstążki. / Raz i dwa, raz i dwa – / pięknie dziś nasz marsz gra!", "song_author": "własna (KMK/Malachim)", "safety": "Chusty krótkie (do 50 cm), nie wiążemy ich na szyi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('484efad2-96fe-5441-912a-07ada1f06dd6','Sensoryka','Białe miękkie, czerwone twarde',false,false,'2026-11-09','{"id": "2026-11-09-sensoryka", "day": "2026-11-09", "weekday": null, "option": 3, "title": "Białe miękkie, czerwone twarde", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Rozróżnia faktury i łączy je z kolorami.", "materials": "pudełko: biały polar, biała gąbka, czerwona piłka gumowa (duża), czerwony drewniany klocek (duży)", "steps": ["Pokaż pudełko z rzeczami.", "Dzieci po kolei wyjmują jedną rzecz.", "Mówimy: miękkie czy twarde? białe czy czerwone?", "Kładziemy na białą lub czerwoną kartkę.", "Na koniec głaszczemy wszystko jeszcze raz."], "easier": "Dziecko dotyka 2 rzeczy: miękkiej i twardej.", "harder": "Dziecko samo sortuje według koloru i faktury.", "variant_1y": "Dziecko dotyka 2 rzeczy: miękkiej i twardej.", "variant_2_3y": "Dziecko samo sortuje według koloru i faktury.", "song": "Białe miękkie – mi, mi, mi, / czerwone twarde – stuk, stuk, stuk. / Dotknij rączką, powiedz mi, / co jest w pudle – puk, puk, puk!", "song_author": "własna (KMK/Malachim)", "safety": "Wszystkie przedmioty większe niż rolka po papierze (test „rolki”) – brak drobnych elementów.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6dc20a5c-7b51-5729-afe1-26ae89559e1a','Emocje','Jestem dumny – brawo!',false,false,'2026-11-09','{"id": "2026-11-09-emocje", "day": "2026-11-09", "weekday": null, "option": 4, "title": "Jestem dumny – brawo!", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Wzmacnia poczucie własnej wartości.", "materials": "brak", "steps": ["Siadamy w kole.", "Każde dziecko pokazuje, co umie: skok, klaśnięcie, obrót.", "Grupa bije brawo.", "Opiekunka mówi: „Jesteś dumny, bo umiesz!”.", "Na koniec wszyscy przybijamy „piątkę”."], "easier": "Opiekunka pomaga zrobić ruch, grupa klaszcze.", "harder": "Dziecko samo wybiera, co pokaże.", "variant_1y": "Opiekunka pomaga zrobić ruch, grupa klaszcze.", "variant_2_3y": "Dziecko samo wybiera, co pokaże.", "song": "Brawo, brawo, (imię) umie, / każdy z nas to dobrze rozumie! / Klaszczmy głośno: klap, klap, klap – / jesteś super, jesteś chwat!", "song_author": "własna (KMK/Malachim)", "safety": "Nie zmuszamy nieśmiałych – mogą pokazać z miejsca.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ba4ad8f8-09dd-5c46-8720-9e5377ed684c','Zmysły','Co słychać w mieście?',false,false,'2026-11-09','{"id": "2026-11-09-zmysly", "day": "2026-11-09", "weekday": null, "option": 5, "title": "Co słychać w mieście?", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozwija słuch i rozpoznawanie dźwięków.", "materials": "nagrania: tramwaj, dzwony, pies, samochód, ptaki; obrazki tych rzeczy", "steps": ["Siadamy cicho.", "Odtwórz jeden dźwięk.", "Pytaj: „Co to?”.", "Dzieci wskazują obrazek.", "Naśladujemy dźwięk głosem."], "easier": "2 dźwięki i 2 obrazki.", "harder": "4–5 dźwięków bez podpowiedzi.", "variant_1y": "2 dźwięki i 2 obrazki.", "variant_2_3y": "4–5 dźwięków bez podpowiedzi.", "song": "Uszka słuchają: co to za dźwięk? / Dzyń – to tramwaj, bim-bam – to dzwonek. / Hau – to piesek, brum – samochód, / uszka wiedzą, to jest ich zawód!", "song_author": "własna (KMK/Malachim)", "safety": "Ciche nagrania – nie głośniej niż rozmowa.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('1809623f-224d-57ed-9f81-7137a232786f','Zwierzęta','Orzeł, bocian i żubr',false,false,'2026-11-09','{"id": "2026-11-09-zwierzeta", "day": "2026-11-09", "weekday": null, "option": 6, "title": "Orzeł, bocian i żubr", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje zwierzęta kojarzone z Polską i ich ruch.", "materials": "duże obrazki: orzeł, bocian, żubr", "steps": ["Pokaż obrazek orła – latamy.", "Bocian – stoimy na jednej nodze i klekoczemy „kle, kle”.", "Żubr – chodzimy ciężko na czworakach i mruczymy „mmm”.", "Opiekunka pokazuje obrazek – dzieci robią ruch.", "Kończymy jako orły w gnieździe."], "easier": "Dziecko naśladuje 1 zwierzę z opiekunką.", "harder": "Dziecko rozpoznaje zwierzę po dźwięku.", "variant_1y": "Dziecko naśladuje 1 zwierzę z opiekunką.", "variant_2_3y": "Dziecko rozpoznaje zwierzę po dźwięku.", "song": "Orzeł lata – szu, szu, szu, / bocian stoi – kle, kle, kle, / żubr tup, tup – idzie przez las – / wszystkie zwierzęta witają nas!", "song_author": "własna (KMK/Malachim)", "safety": "Stanie na jednej nodze przy ścianie lub za rękę opiekunki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('af2033ef-21be-5abe-b071-5c5c4ac77e0a','Pogoda','Listopadowa mgła',false,false,'2026-11-09','{"id": "2026-11-09-pogoda", "day": "2026-11-09", "weekday": null, "option": 7, "title": "Listopadowa mgła", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Poznaje zjawisko mgły przez zabawę w chowanie.", "materials": "duża, cienka biała chusta (np. firanka)", "steps": ["Opowiedz: rano była mgła – wszystko białe.", "Delikatnie przykryj dziecko białą chustą.", "Pytaj: „Gdzie jest (imię)?”.", "Dziecko zdejmuje chustę – „Tu jestem!”.", "Na koniec chusta „mgła” faluje nad całą grupą."], "easier": "Chowa się opiekunka, dziecko odkrywa.", "harder": "Dziecko samo się chowa i woła „tu jestem”.", "variant_1y": "Chowa się opiekunka, dziecko odkrywa.", "variant_2_3y": "Dziecko samo się chowa i woła „tu jestem”.", "song": "Mgła, mgła, biała mgła, / nic nie widać – gdzie ja? / Raz, dwa, trzy – chusta w dół, / (imię) jest z nami – witaj, ty!", "song_author": "własna (KMK/Malachim)", "safety": "Chusta przewiewna, tylko na chwilę, nigdy na twarzy dziecka, które się boi; nie zawijamy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ad91fafc-1ca9-5b9b-bd1a-0235252e9147','Przyroda','Przytulamy drzewo',false,false,'2026-11-09','{"id": "2026-11-09-przyroda", "day": "2026-11-09", "weekday": null, "option": 8, "title": "Przytulamy drzewo", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Obserwuje drzewa w listopadzie.", "materials": "ciepłe ubranie", "steps": ["Idziemy do drzewa przy żłobku.", "Dotykamy kory: szorstka.", "Patrzymy w górę: są jeszcze liście?", "Przytulamy drzewo całą grupą.", "Mówimy drzewu „do widzenia”."], "easier": "Dziecko dotyka kory na rękach opiekunki.", "harder": "Dziecko porównuje korę z liściem: szorstkie – gładkie.", "variant_1y": "Dziecko dotyka kory na rękach opiekunki.", "variant_2_3y": "Dziecko porównuje korę z liściem: szorstkie – gładkie.", "song": "Drzewo stoi, nie ucieka, / na wiosnę liście znów doczeka. / Przytul, przytul, raz i dwa – / dobre drzewo nasze ma!", "song_author": "własna (KMK/Malachim)", "safety": "Sprawdź, czy przy drzewie nie ma szkła, grzybów, odchodów; nie jemy niczego z ziemi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7af91973-4126-546c-bc21-546d08c6ca75','Eksperymenty','Czerwona kropla w wodzie',false,false,'2026-11-09','{"id": "2026-11-09-eksperymenty", "day": "2026-11-09", "weekday": null, "option": 9, "title": "Czerwona kropla w wodzie", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje mieszanie się barwnika z wodą.", "materials": "przezroczysta butelka plastikowa z wodą, barwnik spożywczy czerwony, taśma", "steps": ["Pokaż przezroczystą wodę.", "Wpuść kroplę czerwonego barwnika.", "Obserwujemy „czerwone dymki”.", "Zakręć i zaklej korek taśmą – dzieci potrząsają.", "Woda jest cała czerwona!"], "easier": "Dziecko patrzy i turla zaklejoną butelkę.", "harder": "Dziecko mówi, jaki był kolor przed i po.", "variant_1y": "Dziecko patrzy i turla zaklejoną butelkę.", "variant_2_3y": "Dziecko mówi, jaki był kolor przed i po.", "song": "Kap – kropelka do wody wpada, / czerwony dymek się rozkłada. / Potrząśnij butlą – szur, szur, szur – / czerwona woda – co za cud!", "song_author": "własna (KMK/Malachim)", "safety": "Barwnik u opiekunki; korek zaklejony mocno taśmą; butelka plastikowa.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('eeedc224-e5cb-56dd-ad4d-3eba0dc5cc79','Plastyka','Biało-czerwona flaga z dłoni',false,false,'2026-11-09','{"id": "2026-11-09-plastyka", "day": "2026-11-09", "weekday": null, "option": 10, "title": "Biało-czerwona flaga z dłoni", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Wykonuje pracę świąteczną, ćwiczy odbijanie dłoni.", "materials": "kartka A4 biała, czerwona farba do malowania palcami (dla dzieci), pędzel, chusteczki nawilżane", "steps": ["Pokaż flagę: biały na górze, czerwony na dole.", "Pomaluj dziecku dłoń czerwoną farbą.", "Dziecko odbija dłoń na dolnej części kartki – kilka razy.", "Myjemy ręce.", "Podpisujemy flagę i wieszamy."], "easier": "Jedno odbicie dłoni z pomocą.", "harder": "Dziecko samo maluje dłoń pędzlem i wypełnia pasek.", "variant_1y": "Jedno odbicie dłoni z pomocą.", "variant_2_3y": "Dziecko samo maluje dłoń pędzlem i wypełnia pasek.", "song": "Biały u góry jak śnieżek, / czerwony na dole jak serduszek. / Odbij rączkę – plask, plask, plask – / flaga gotowa w sam raz!", "song_author": "własna (KMK/Malachim)", "safety": "Farby z atestem dla dzieci; nie pozwalamy oblizywać rąk.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('26f9e225-102e-5dfe-8739-f3e40fda7798','Samoobsługa','Moje rzeczy do mojej szafki',false,false,'2026-11-09','{"id": "2026-11-09-samoobsluga", "day": "2026-11-09", "weekday": null, "option": 11, "title": "Moje rzeczy do mojej szafki", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Uczy odkładania rzeczy na swoje miejsce.", "materials": "szafki z obrazkiem-znaczkiem dziecka", "steps": ["Po spacerze każde dziecko trzyma swoją czapkę.", "Szuka swojego znaczka na szafce.", "Wkłada czapkę i buty do szafki.", "Zamyka szafkę.", "Chwalimy porządek."], "easier": "Opiekunka prowadzi za rękę do szafki, dziecko wkłada czapkę.", "harder": "Dziecko samo odkłada wszystkie rzeczy i pomaga koledze.", "variant_1y": "Opiekunka prowadzi za rękę do szafki, dziecko wkłada czapkę.", "variant_2_3y": "Dziecko samo odkłada wszystkie rzeczy i pomaga koledze.", "song": "Mój znaczek, moja szafka, / tu mieszka moja czapka. / Buciki stają w rządku – / i wszystko jest w porządku!", "song_author": "własna (KMK/Malachim)", "safety": "Uważaj na palce przy drzwiczkach szafki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e7348171-2597-5e89-856a-72eda1fb1b95','Język/logorytmika','Kle, kle, kraaa, mmm',false,false,'2026-11-09','{"id": "2026-11-09-jezyk-logorytmika", "day": "2026-11-09", "weekday": null, "option": 12, "title": "Kle, kle, kraaa, mmm", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy wargi i język przez dźwięki zwierząt.", "materials": "obrazki: bocian, orzeł, żubr", "steps": ["Pokaż bociana: „kle, kle” – kląskamy językiem.", "Orzeł: „kraaa” – szeroko otwarta buzia.", "Żubr: „mmm” – zamknięte wargi.", "Opiekunka pokazuje obrazek, dzieci mówią dźwięk.", "Mówimy sylaby do rytmu bębenka."], "easier": "Dziecko słucha i powtarza 1 dźwięk.", "harder": "Dziecko mówi dźwięk do rytmu.", "variant_1y": "Dziecko słucha i powtarza 1 dźwięk.", "variant_2_3y": "Dziecko mówi dźwięk do rytmu.", "song": "Bocian mówi: kle, kle, kle, / orzeł woła: kraaa, kra-a, / żubr mruczy: mmm, mmm, mmm – / a my razem: ha, ha, ha!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych zagrożeń.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2e95a547-94a0-53c7-96e0-de330c06b31d','Zabawy paluszkowe i masażyki','Chmurka i słonko na rączce',false,false,'2026-11-09','{"id": "2026-11-09-zabawy-paluszkowe-i-masazyki", "day": "2026-11-09", "weekday": null, "option": 13, "title": "Chmurka i słonko na rączce", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Rozwija czucie dłoni i bliskość.", "materials": "brak", "steps": ["Bierzemy dłoń dziecka.", "„Biała chmurka” – głaszczemy całą dłoń.", "„Czerwone słonko” – kręcimy kółko na środku.", "„Deszczyk” – stukamy w paluszki.", "Na koniec całujemy (lub przytulamy) dłoń."], "easier": "Spokojnie na kolanach opiekunki.", "harder": "Dziecko robi masażyk na dłoni opiekunki.", "variant_1y": "Spokojnie na kolanach opiekunki.", "variant_2_3y": "Dziecko robi masażyk na dłoni opiekunki.", "song": "Biała chmurka po rączce płynie, / czerwone słonko w kółeczku ginie. / Kap, kap, kap – po paluszkach / i przytulam się do brzuszka!", "song_author": "własna (KMK/Malachim)", "safety": "Delikatny dotyk; zgoda dziecka.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('1c3b5d1e-5ade-548b-9bc5-6863e6d8d0ab','Zabawy słowno-ruchowe i rymowanki','Pociąg przez Polskę',false,false,'2026-11-09','{"id": "2026-11-09-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-11-09", "weekday": null, "option": 14, "title": "Pociąg przez Polskę", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Łączy słowa z ruchem i poznaje góry, las, morze.", "materials": "brak", "steps": ["Ustawiamy się w pociąg.", "Jedziemy przez „góry” – na palcach.", "Przez „las” – ręce w górze jak drzewa.", "Nad „morze” – falujemy rękami.", "Stacja – siadamy."], "easier": "Dziecko jedzie na rękach opiekunki.", "harder": "Dziecko jest lokomotywą i woła, gdzie jedziemy.", "variant_1y": "Dziecko jedzie na rękach opiekunki.", "variant_2_3y": "Dziecko jest lokomotywą i woła, gdzie jedziemy.", "song": "Jedzie pociąg przez pola, / przez góry – hop do góry, / przez las – szu, szu, szu, / nad morze – plusk! – i już!", "song_author": "własna (KMK/Malachim)", "safety": "Pociąg wolno; bez ciągnięcia za ubranie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f34384de-b683-5f24-9cdd-03226866af85','Powitania i integracja','Witamy się na trzy sposoby',false,false,'2026-11-09','{"id": "2026-11-09-powitania-i-integracja", "day": "2026-11-09", "weekday": null, "option": 15, "title": "Witamy się na trzy sposoby", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Poznaje sposoby witania i buduje relacje.", "materials": "brak", "steps": ["Siadamy w kole.", "Witamy się podaniem ręki.", "Potem „piątką”.", "Potem ukłonem.", "Dziecko wybiera, jak się przywita z sąsiadem."], "easier": "Opiekunka wita się z dzieckiem, dziecko macha.", "harder": "Dziecko samo wybiera sposób powitania.", "variant_1y": "Opiekunka wita się z dzieckiem, dziecko macha.", "variant_2_3y": "Dziecko samo wybiera sposób powitania.", "song": "Dzień dobry – rączka, / dzień dobry – piątka, / dzień dobry – ukłon / od początku do końca!", "song_author": "własna (KMK/Malachim)", "safety": "Szanujemy dziecko, które nie chce dotyku – może pomachać.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2b2b1227-2faa-5173-9169-27a3a9bf8b12','Świadomość ciała','Stoję prosto jak maszt',false,false,'2026-11-09','{"id": "2026-11-09-swiadomosc-ciala", "day": "2026-11-09", "weekday": null, "option": 16, "title": "Stoję prosto jak maszt", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Ćwiczy postawę i napinanie – rozluźnianie.", "materials": "brak", "steps": ["Pokaż maszt z flagą (obrazek).", "Stajemy prosto jak maszt.", "Wiatr wieje – kołyszemy się jak flaga.", "Wiatr stop – znowu prosto.", "Na koniec kładziemy się jak flaga złożona."], "easier": "Dziecko stoi przy opiekunce i kołysze się w jej ramionach.", "harder": "Dziecko utrzymuje „maszt” do 5.", "variant_1y": "Dziecko stoi przy opiekunce i kołysze się w jej ramionach.", "variant_2_3y": "Dziecko utrzymuje „maszt” do 5.", "song": "Stoję prosto, jak maszt wysoki, / wiatr zawieje – kołyszę boki. / Wiatr ucichnie – prosto znów, / i złożona flaga – śpi bez słów.", "song_author": "własna (KMK/Malachim)", "safety": "Kołyszemy się w miejscu, bez przewracania.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4e0edcd2-de8e-5ecd-9f2b-14e2fde21ef4','Pamięć/uwaga/naśladowanie','Gdzie schowała się flaga?',false,false,'2026-11-09','{"id": "2026-11-09-pamiec-uwaga-nasladowanie", "day": "2026-11-09", "weekday": null, "option": 17, "title": "Gdzie schowała się flaga?", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy pamięć i uwagę.", "materials": "3 duże plastikowe miski, duża papierowa flaga (A5)", "steps": ["Pokaż flagę.", "Schowaj ją pod jedną miską.", "Przesuń miski powoli.", "Dziecko podnosi miskę: tu?", "Zamiana – dziecko chowa."], "easier": "2 miski, bez przesuwania.", "harder": "3 miski z przesuwaniem.", "variant_1y": "2 miski, bez przesuwania.", "variant_2_3y": "3 miski z przesuwaniem.", "song": "Flaga, flaga, gdzie się skryła? / Pod miseczką może była? / Raz, dwa, trzy – podnieś ją – / jest! Brawo! Hop, hop, hop!", "song_author": "własna (KMK/Malachim)", "safety": "Miski plastikowe, lekkie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('18ca51cb-0f66-5e70-9a29-dcd249d00b24','Zabawy poznawcze','Flaga z dwóch części',false,false,'2026-11-09','{"id": "2026-11-09-zabawy-poznawcze", "day": "2026-11-09", "weekday": null, "option": 18, "title": "Flaga z dwóch części", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Składa prostą układankę z 2 elementów.", "materials": "duże układanki z tektury: flaga z 2 pasków, dom z 2 części", "steps": ["Pokaż całą flagę.", "Rozdziel na 2 paski.", "Dziecko składa: biały u góry, czerwony na dole.", "Potem domek: dach i ściana.", "Chwalimy."], "easier": "Dziecko kładzie jeden pasek na wzorze.", "harder": "Dziecko składa 2 układanki samo.", "variant_1y": "Dziecko kładzie jeden pasek na wzorze.", "variant_2_3y": "Dziecko składa 2 układanki samo.", "song": "Biały do góry, czerwony na dół, / flaga jest cała – brawo, mój ty! / Dach na domek – hop i już – / układanka gotowa – tusz!", "song_author": "własna (KMK/Malachim)", "safety": "Tektura gruba, bez ostrych rogów (zaokrąglone).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('11991aa0-596a-5ee8-a4f4-66e78ed064a7','Zabawy na dworze','Szukamy flag',false,false,'2026-11-09','{"id": "2026-11-09-zabawy-na-dworze", "day": "2026-11-09", "weekday": null, "option": 19, "title": "Szukamy flag", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Obserwuje okolicę przed świętem.", "materials": "ciepłe ubranie", "steps": ["Wychodzimy na spacer wokół żłobka.", "Szukamy flag na domach i w oknach.", "Gdy ktoś zobaczy – woła „flaga!”.", "Liczymy razem znalezione flagi.", "Machamy flagom „pa, pa”."], "easier": "Dziecko w wózku/na rękach wskazuje palcem.", "harder": "Dziecko liczy flagi z opiekunką.", "variant_1y": "Dziecko w wózku/na rękach wskazuje palcem.", "variant_2_3y": "Dziecko liczy flagi z opiekunką.", "song": "Idę, idę, patrzę w górę, / tu jest flaga na murze! / Biało-czerwona – hej! – / pomachaj rączką do niej!", "song_author": "własna (KMK/Malachim)", "safety": "Trzymamy się za ręce przy ulicy; trasa bez przejść przez ruchliwą ulicę.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5e954206-b2db-5c49-81ef-127b8d3a3109','Higiena','Kichamy w łokieć',false,false,'2026-11-09','{"id": "2026-11-09-higiena", "day": "2026-11-09", "weekday": null, "option": 20, "title": "Kichamy w łokieć", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Uczy zasłaniania się przy kichaniu i kaszlu.", "materials": "chusteczki higieniczne, kosz", "steps": ["Pokaż, jak kichamy w łokieć: „a-psik!”.", "Dzieci udają kichanie w łokieć.", "Pokazujemy wydmuchanie noska w chusteczkę.", "Chusteczka do kosza.", "Myjemy ręce."], "easier": "Opiekunka prowadzi rękę dziecka do łokcia.", "harder": "Dziecko samo zasłania się i wyrzuca chusteczkę.", "variant_1y": "Opiekunka prowadzi rękę dziecka do łokcia.", "variant_2_3y": "Dziecko samo zasłania się i wyrzuca chusteczkę.", "song": "A-a-psik! – w łokieć, nie w rączkę, / chusteczka na nosek, potem do koszyczka. / Rączki umyjemy – szu, szu, szu – / zdrowi jesteśmy znów!", "song_author": "własna (KMK/Malachim)", "safety": "Chusteczki jednorazowe od razu do kosza z pokrywą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('005cce0e-c1c0-518b-aee0-ae07d5889164','Czytanie dziecku','Mały orzeł szuka domu (opowiadanie)',false,false,'2026-11-09','{"id": "2026-11-09-czytanie-dziecku", "day": "2026-11-09", "weekday": null, "option": 21, "title": "Mały orzeł szuka domu (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha krótkiej historii z pacynką i obrazkami.", "materials": "pacynka lub obrazek orła, obrazki: góry, las, gniazdo", "steps": ["Usiądźcie wygodnie.", "Opowiadaj: „Mały orzeł leciał nad górami – za zimno. Nad lasem – za ciemno. Nad łąką zobaczył drzewo z gniazdem – tu jest dom!”.", "Przy każdym miejscu pokazuj obrazek.", "Dzieci mówią „za zimno”, „za ciemno”.", "Pytaj: „Gdzie jest twój dom?”."], "easier": "Dziecko patrzy na pacynkę i dotyka jej.", "harder": "Dziecko powtarza zwroty i opowiada o swoim domu.", "variant_1y": "Dziecko patrzy na pacynkę i dotyka jej.", "variant_2_3y": "Dziecko powtarza zwroty i opowiada o swoim domu.", "song": "Leci orzeł, szuka domu, / nie powiedział nic nikomu. / Gdzie jest ciepło, miło, blisko? / W gnieździe – tam ma wszystko!", "song_author": "własna (KMK/Malachim)", "safety": "Pacynka bez guzików i doszywanych drobnych oczek.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('1e365608-50dc-572a-809f-e026f5945265','Klocki/budowanie','Zamek dla orła',false,false,'2026-11-09','{"id": "2026-11-09-klocki-budowanie", "day": "2026-11-09", "weekday": null, "option": 22, "title": "Zamek dla orła", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje budowlę z dużych klocków.", "materials": "duże klocki piankowe, papierowa flaga (A5)", "steps": ["Oglądamy obrazek zamku.", "Budujemy mury z klocków.", "Dziecko stawia wieżę.", "Na wieży kładziemy flagę.", "Orzeł (pacynka) ląduje na zamku."], "easier": "Dziecko podaje klocki opiekunce i burzy.", "harder": "Dziecko buduje mur i wieżę samodzielnie.", "variant_1y": "Dziecko podaje klocki opiekunce i burzy.", "variant_2_3y": "Dziecko buduje mur i wieżę samodzielnie.", "song": "Klocek na klocku, mur coraz wyższy, / zamek dla orła – kto jest najbliżej? / Flaga na wieżę, orzeł przyleci – / zbudowały zamek dzieci!", "song_author": "własna (KMK/Malachim)", "safety": "Klocki lekkie; budowla nie wyżej niż pas dziecka.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4b534560-e4e5-55ec-8641-4328d9d87ea2','Wyciszenie','Kołysanka biała chmurka',false,false,'2026-11-09','{"id": "2026-11-09-wyciszenie", "day": "2026-11-09", "weekday": null, "option": 23, "title": "Kołysanka biała chmurka", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza po zabawie ruchowej.", "materials": "biała i czerwona chusta, spokojna muzyka", "steps": ["Dzieci leżą na kocu.", "Opiekunka powoli faluje białą chustą nad dziećmi („chmurka”).", "Potem czerwoną („słonko zachodzi”).", "Śpiewa cicho kołysankę.", "Dzieci leżą chwilę w ciszy."], "easier": "Dziecko leży przy opiekunce.", "harder": "Dziecko leży samo i oddycha spokojnie.", "variant_1y": "Dziecko leży przy opiekunce.", "variant_2_3y": "Dziecko leży samo i oddycha spokojnie.", "song": "Płynie chmurka biała, cicha, / słonko czerwone już zasypia. / Lulu, lulu, oczka zmruż, / dobranoc, Polsko, śpimy już.", "song_author": "własna (KMK/Malachim)", "safety": "Chusta nad dziećmi, nie na twarzy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c4af0e2c-cfce-54e0-ab9b-9e5c02dc39b9','Empatia','Czekam na swoją kolej',false,false,'2026-11-09','{"id": "2026-11-09-empatia", "day": "2026-11-09", "weekday": null, "option": 24, "title": "Czekam na swoją kolej", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy dzielenia się i czekania.", "materials": "jedna chorągiewka papierowa lub chusta", "steps": ["Siadamy w kole.", "Chusta wędruje od dziecka do dziecka.", "Każdy macha 3 razy i podaje dalej.", "Mówimy „proszę” i „dziękuję”.", "Chwalimy czekanie."], "easier": "Opiekunka podaje chustę za dziecko.", "harder": "Dziecko samo podaje i mówi „proszę”.", "variant_1y": "Opiekunka podaje chustę za dziecko.", "variant_2_3y": "Dziecko samo podaje i mówi „proszę”.", "song": "Machnę raz, machnę dwa, / machnę trzy – i dla ciebie mam! / Proszę, weź – dziękuję ci, / razem bawić się chcemy my!", "song_author": "własna (KMK/Malachim)", "safety": "Bez patyków – chusta zamiast chorągiewki na kiju.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7ecc59ca-0fa7-5d1e-ae2c-735880336744','Rodzina i dom','Domek mojej rodziny',false,false,'2026-11-09','{"id": "2026-11-09-rodzina-i-dom", "day": "2026-11-09", "weekday": null, "option": 25, "title": "Domek mojej rodziny", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Poznaje słowo „dom” i bliskich.", "materials": "pudełko-domek z kartonu z okienkami, zdjęcia rodzin dzieci", "steps": ["Pokaż kartonowy domek.", "W okienkach są zdjęcia rodzin.", "Dziecko szuka swojego okienka.", "Mówi, kto mieszka z nim.", "Zamykamy okienka: „dobranoc, rodzinko”."], "easier": "Dziecko znajduje swoje zdjęcie z pomocą.", "harder": "Dziecko nazywa osoby na zdjęciu.", "variant_1y": "Dziecko znajduje swoje zdjęcie z pomocą.", "variant_2_3y": "Dziecko nazywa osoby na zdjęciu.", "song": "W moim domku jest okienko, / a w okienku – moja rodzinka. / Puk, puk, puk – kto tam jest? / Moja mama, tata, ja – i pies!", "song_author": "własna (KMK/Malachim)", "safety": "Zdjęcia za zgodą rodziców, w folii; szanujemy różne rodziny.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f50ef947-9baf-57c3-9e8b-b64cad984464','Pory roku i święta','Świętujemy 11 listopada',false,false,'2026-11-09','{"id": "2026-11-09-pory-roku-i-swieta", "day": "2026-11-09", "weekday": null, "option": 26, "title": "Świętujemy 11 listopada", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Poznaje święto przez flagę, marsz i śpiew.", "materials": "flaga, chusty, bębenek", "steps": ["Pokaż flagę: „To nasza flaga – dziś święto Polski”.", "Wieszamy flagę w sali.", "Maszerujemy z chustami.", "Śpiewamy naszą rymowankę.", "Kończymy brawami."], "easier": "Machanie chustą na rękach opiekunki.", "harder": "Dziecko mówi „flaga”, „święto”, „Polska”.", "variant_1y": "Machanie chustą na rękach opiekunki.", "variant_2_3y": "Dziecko mówi „flaga”, „święto”, „Polska”.", "song": "Biało-czerwona flaga wisi, / dziś jest święto – cieszą się wszyscy! / Marsz, marsz, raz i dwa – / Polska to ziemia ma.", "song_author": "własna (KMK/Malachim)", "safety": "Flaga na wysokości poza zasięgiem dzieci, drzewce bez ostrych końców.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('573d121f-04e4-50c6-a1c2-045f1b1a24a5','Kolory/kształty/wielkości','Biały i czerwony – sortujemy',false,false,'2026-11-09','{"id": "2026-11-09-kolory-ksztalty-wielkosci", "day": "2026-11-09", "weekday": null, "option": 27, "title": "Biały i czerwony – sortujemy", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Rozpoznaje i sortuje 2 kolory.", "materials": "2 kosze (biały i czerwony), duże przedmioty białe i czerwone (piłki, klocki, chusty)", "steps": ["Pokaż dwa kosze.", "Dziecko bierze przedmiot.", "Pytamy: jaki kolor?", "Wkłada do kosza w tym kolorze.", "Na koniec liczymy rzeczy w koszach."], "easier": "Opiekunka podaje 1 przedmiot i pokazuje kosz.", "harder": "Dziecko sortuje samo i nazywa kolory.", "variant_1y": "Opiekunka podaje 1 przedmiot i pokazuje kosz.", "variant_2_3y": "Dziecko sortuje samo i nazywa kolory.", "song": "Biały do białego – hop, / czerwony do czerwonego – stop! / Każdy kolor ma swój dom, / sprzątamy razem: bim-bom!", "song_author": "własna (KMK/Malachim)", "safety": "Wszystkie przedmioty duże (test rolki).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Biało-czerwone – moja Polska", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ba40a65d-d267-51ca-9d4d-bb02ce828339','Ruch','Hop przez kałużę',false,false,'2026-11-16','{"id": "2026-11-16-ruch", "day": "2026-11-16", "weekday": null, "option": 1, "title": "Hop przez kałużę", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy przekraczanie i skoki obunóż.", "materials": "niebieskie maty lub koła z kartonu przyklejone taśmą do podłogi", "steps": ["Rozłóż na podłodze „kałuże”.", "Dzieci chodzą wokół kałuż.", "Na hasło „kalosze!” – wchodzimy do kałuży i tupiemy.", "Na hasło „buciki!” – przeskakujemy lub przekraczamy kałużę.", "Kończymy w „domu” na dywanie."], "easier": "Przekraczanie kałuży za rękę.", "harder": "Skoki obunóż przez kałużę.", "variant_1y": "Przekraczanie kałuży za rękę.", "variant_2_3y": "Skoki obunóż przez kałużę.", "song": "Kałuża mała, kałuża duża, / kto się boi? Nikt się nie wzrusza! / W kaloszach – tup, plusk, tup, / w bucikach – hop i już!", "song_author": "własna (KMK/Malachim)", "safety": "Kałuże przyklejone na płasko – bez poślizgu; nie używamy prawdziwej wody w sali.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e8bd80ed-e06e-56e6-8e45-0d0360bf11cf','Muzyka','Deszczowa orkiestra',false,false,'2026-11-16','{"id": "2026-11-16-muzyka", "day": "2026-11-16", "weekday": null, "option": 2, "title": "Deszczowa orkiestra", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Rozwija rytm i słuch: cicho – głośno.", "materials": "zakręcone i zaklejone butelki z kaszą (grzechotki), garnek, drewniane łyżki", "steps": ["Każde dziecko dostaje grzechotkę-butelkę.", "„Kapuśniaczek” – gramy cichutko.", "„Ulewa” – gramy głośno.", "„Słońce” – cisza, chowamy instrumenty.", "Zmieniamy kilka razy."], "easier": "Grzechotka w ręku, opiekunka prowadzi rączkę.", "harder": "Dziecko zmienia głośność samo na hasło.", "variant_1y": "Grzechotka w ręku, opiekunka prowadzi rączkę.", "variant_2_3y": "Dziecko zmienia głośność samo na hasło.", "song": "Kapie deszczyk: kap, kap, kap – / cichuteńko, nie ma strat. / Leje ulewa: szszsz, bum, bum! / Słonko wyszło – cisza, szum…", "song_author": "własna (KMK/Malachim)", "safety": "Butelki plastikowe, korek zaklejony mocno taśmą – sprawdzaj przed zajęciami.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('af129a01-6236-5a34-8609-e56c3de679d3','Sensoryka','Worek ciepłych ubranek',false,false,'2026-11-16','{"id": "2026-11-16-sensoryka", "day": "2026-11-16", "weekday": null, "option": 3, "title": "Worek ciepłych ubranek", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Rozróżnia faktury tkanin.", "materials": "worek: czapka z wełny, polarowy szalik, gumowy kalosz, rękawiczka z polaru", "steps": ["Dziecko wkłada rękę do worka.", "Wyjmuje jedną rzecz.", "Dotykamy: drapie? miękkie? gładkie?", "Nazywamy rzecz.", "Ubieramy w nią misia."], "easier": "Opiekunka podaje rzeczy, dziecko dotyka.", "harder": "Dziecko zgaduje rzecz bez patrzenia.", "variant_1y": "Opiekunka podaje rzeczy, dziecko dotyka.", "variant_2_3y": "Dziecko zgaduje rzecz bez patrzenia.", "song": "Co jest w worku? Hop, wyciągam! / Czapka drapie – ała, ała! / Szalik miękki jak kotek, / a kalosz gładki, wygląda jak smok!", "song_author": "własna (KMK/Malachim)", "safety": "Ubrania bez pomponów na nitkach, bez guzików do oderwania.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('066f8494-5006-591b-911f-0506775ae25d','Emocje','Brr, zimno! Ach, ciepło!',false,false,'2026-11-16','{"id": "2026-11-16-emocje", "day": "2026-11-16", "weekday": null, "option": 4, "title": "Brr, zimno! Ach, ciepło!", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Nazywa odczucia i pokazuje je miną.", "materials": "duży koc", "steps": ["Opowiadaj: jesteśmy na dworze, wieje.", "Trzęsiemy się: „brr, zimno!” – smutna mina.", "Wchodzimy pod koc: „ach, ciepło!” – uśmiech.", "Pytaj: co lubisz, gdy jest zimno?", "Przytulamy się pod kocem."], "easier": "Dziecko pod kocem z opiekunką.", "harder": "Dziecko mówi „zimno” i „ciepło” z miną.", "variant_1y": "Dziecko pod kocem z opiekunką.", "variant_2_3y": "Dziecko mówi „zimno” i „ciepło” z miną.", "song": "Brr, brr – zimno mi, / trzęsę się jak liść na wietrze ty! / Pod kocykiem – ach, jak miło, / ciepło nam się zrobiło!", "song_author": "własna (KMK/Malachim)", "safety": "Koc lekki; dzieci nie zawijają się z głową.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b6bcc91d-0b64-57c1-b2fa-f67cbc454db4','Zmysły','Co tak szura?',false,false,'2026-11-16','{"id": "2026-11-16-zmysly", "day": "2026-11-16", "weekday": null, "option": 5, "title": "Co tak szura?", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozwija słuch: dźwięki ubrań.", "materials": "kurtka z zamkiem, but na rzepy, szeleszcząca kurtka przeciwdeszczowa", "steps": ["Dzieci zamykają oczy (lub opiekunka chowa rzeczy za parawanem).", "Robisz dźwięk: zamek, rzep, szelest.", "Dzieci zgadują.", "Pokazujesz rzecz.", "Dzieci same robią dźwięk."], "easier": "Dziecko słucha i patrzy, jak robisz dźwięk.", "harder": "Dziecko zgaduje bez patrzenia.", "variant_1y": "Dziecko słucha i patrzy, jak robisz dźwięk.", "variant_2_3y": "Dziecko zgaduje bez patrzenia.", "song": "Zzzip – to zamek jedzie w górę, / rrrsz – to rzepy, jak pazurek, / szszsz – kurteczka na deszczyk, / uszka słyszą, kto tu jest?", "song_author": "własna (KMK/Malachim)", "safety": "Uwaga na palce przy zamku błyskawicznym.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7ed03ce2-c5e5-5ab6-9e3c-2abcff454bcc','Zwierzęta','Kto ma ciepłe futerko?',false,false,'2026-11-16','{"id": "2026-11-16-zwierzeta", "day": "2026-11-16", "weekday": null, "option": 6, "title": "Kto ma ciepłe futerko?", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje, jak zwierzęta chronią się przed zimnem.", "materials": "obrazki: owca, niedźwiedź, kot, ryba; kawałki sztucznego futra i gładkiej folii", "steps": ["Pokaż owcę – dotykamy „wełny” (futerko).", "Niedźwiedź – grube futro.", "Kot – miękkie futerko.", "Ryba – gładka, bez futra (folia).", "Pytamy: a co my zakładamy, gdy zimno?"], "easier": "Dotykanie futra i naśladowanie dźwięków.", "harder": "Dziecko łączy zwierzę z „ubrankiem”.", "variant_1y": "Dotykanie futra i naśladowanie dźwięków.", "variant_2_3y": "Dziecko łączy zwierzę z „ubrankiem”.", "song": "Owca ma wełnę, miś ma futro, / kotek się grzeje w kąciku z rana. / A ja? A ja mam kurtkę i czapkę – / zimno mi niestraszne, mam dobrą łapkę!", "song_author": "własna (KMK/Malachim)", "safety": "Futro bez luźnego włosia; dzieci z alergią – tylko syntetyki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5a52e414-7940-545c-adcf-9ad3a8a65d52','Pogoda','Parasol na deszcz',false,false,'2026-11-16','{"id": "2026-11-16-pogoda", "day": "2026-11-16", "weekday": null, "option": 7, "title": "Parasol na deszcz", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Poznaje deszcz i reaguje na sygnał.", "materials": "duży parasol (trzyma opiekunka) lub chusta animacyjna", "steps": ["Dzieci spacerują po sali.", "Opiekunka mówi „pada deszcz!” i otwiera parasol.", "Dzieci biegną pod parasol.", "„Słonko!” – wychodzą i tańczą.", "Powtórz kilka razy."], "easier": "Dziecko idzie pod parasol z opiekunką.", "harder": "Dziecko samo reaguje na hasło.", "variant_1y": "Dziecko idzie pod parasol z opiekunką.", "variant_2_3y": "Dziecko samo reaguje na hasło.", "song": "Kap, kap, deszczyk leci, / pod parasol, małe dzieci! / Słonko świeci – wyjść już można, / tańczy każda nóżka!", "song_author": "własna (KMK/Malachim)", "safety": "Parasol otwiera i trzyma tylko dorosły, końcówki szprych zabezpieczone; lepiej chusta.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a578fdd1-a3fa-5769-b6ed-e58020e7b808','Przyroda','Mokry liść, suchy liść',false,false,'2026-11-16','{"id": "2026-11-16-przyroda", "day": "2026-11-16", "weekday": null, "option": 8, "title": "Mokry liść, suchy liść", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Porównuje liście z dworu i z sali.", "materials": "liście z dworu (mokre) i ususzone (suche), 2 tace", "steps": ["Na jednej tacy mokre liście, na drugiej suche.", "Dotykamy: mokre – zimne, miękkie.", "Suche – szeleszczą, kruszą się.", "Zgniatamy suchy liść w dłoni – szur!", "Myjemy ręce."], "easier": "Dziecko dotyka liści na tacy.", "harder": "Dziecko mówi „mokry/suchy” i sortuje.", "variant_1y": "Dziecko dotyka liści na tacy.", "variant_2_3y": "Dziecko mówi „mokry/suchy” i sortuje.", "song": "Mokry liść – klap, klap, klap, / suchy liść – chrup i szur! / Jeden z deszczu, drugi z domu – / nie powiemy o tym nikomu!", "song_author": "własna (KMK/Malachim)", "safety": "Liście bez pleśni; pilnuj, by nie trafiły do buzi; mycie rąk.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0bc64c93-6015-5eeb-89a3-47d16151ac3e','Eksperymenty','Co przemaka?',false,false,'2026-11-16','{"id": "2026-11-16-eksperymenty", "day": "2026-11-16", "weekday": null, "option": 9, "title": "Co przemaka?", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Sprawdza, które rzeczy chronią przed wodą.", "materials": "miska, kubek wody, kalosz, skarpetka, kawałek kurtki przeciwdeszczowej, chusteczka papierowa", "steps": ["Pokaż rzeczy.", "Lejemy trochę wody na skarpetkę – mokra!", "Na kalosz – woda spływa.", "Na kurtkę przeciwdeszczową – spływa.", "Pytamy: co założymy na deszcz?"], "easier": "Dziecko dotyka mokrej i suchej rzeczy.", "harder": "Dziecko przewiduje: przemoknie czy nie?", "variant_1y": "Dziecko dotyka mokrej i suchej rzeczy.", "variant_2_3y": "Dziecko przewiduje: przemoknie czy nie?", "song": "Lej, lej, wodo – kto przemoknie? / Skarpetka mokra – ojej, smutnie! / Kalosz suchy – woda w dół – / w kaloszach idę w deszcz i już!", "song_author": "własna (KMK/Malachim)", "safety": "Woda na tacy; wycieraj podłogę od razu; miska z małą ilością wody, pod nadzorem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('631f6616-4150-5a6a-bc30-d3dcae2ba5df','Plastyka','Deszcz na parasolu',false,false,'2026-11-16','{"id": "2026-11-16-plastyka", "day": "2026-11-16", "weekday": null, "option": 10, "title": "Deszcz na parasolu", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Ćwiczy stemplowanie palcem.", "materials": "duży wycięty parasol z papieru, niebieska farba do palców", "steps": ["Pokaż papierowy parasol.", "Dziecko macza palec w farbie.", "Stawia kropki – „kap, kap” – nad parasolem.", "Mówimy: deszcz pada na parasol.", "Myjemy ręce."], "easier": "Dziecko stawia kilka kropek całą dłonią.", "harder": "Dziecko stawia kropki tylko nad parasolem.", "variant_1y": "Dziecko stawia kilka kropek całą dłonią.", "variant_2_3y": "Dziecko stawia kropki tylko nad parasolem.", "song": "Kap, kap – paluszek skacze, / deszczyk pada, nikt nie płacze. / Parasolka nas osłoni, / kropka, kropka – po tej stronie!", "song_author": "własna (KMK/Malachim)", "safety": "Farba z atestem; fartuszek; nie oblizujemy palców.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a1a98784-e9c4-54cc-be38-d9c3474f8250','Samoobsługa','Sam zakładam czapkę',false,false,'2026-11-16','{"id": "2026-11-16-samoobsluga", "day": "2026-11-16", "weekday": null, "option": 11, "title": "Sam zakładam czapkę", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy samodzielne zakładanie czapki.", "materials": "czapki dzieci, lusterko akrylowe", "steps": ["Każde dziecko bierze swoją czapkę.", "Pokaż: łapiemy brzegi dwiema rączkami.", "Naciągamy na głowę.", "Patrzymy w lusterko – zakryte uszy?", "Zdejmujemy i odkładamy."], "easier": "Opiekunka nakłada, dziecko dociąga.", "harder": "Dziecko zakłada czapkę samo i poprawia uszy.", "variant_1y": "Opiekunka nakłada, dziecko dociąga.", "variant_2_3y": "Dziecko zakłada czapkę samo i poprawia uszy.", "song": "Czapka na główkę – raz i dwa, / uszka schowane – nie widać ich ha! / Ciągnę, ciągnę w dół – / w lusterku widzę: to ja, to ja!", "song_author": "własna (KMK/Malachim)", "safety": "Czapki bez sznurków wiązanych pod brodą (ryzyko zadzierzgnięcia) – lepiej kominiarki/czapki wiązane rzepem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3f51bd20-f805-54b5-a49d-e20ba35e9837','Język/logorytmika','Plum, kap, szszsz',false,false,'2026-11-16','{"id": "2026-11-16-jezyk-logorytmika", "day": "2026-11-16", "weekday": null, "option": 12, "title": "Plum, kap, szszsz", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy głoski i oddech przez dźwięki deszczu.", "materials": "brak", "steps": ["„Kap” – krótkie, z kląśnięciem palcami.", "„Plum” – usta jak rybka.", "„Szszsz” – długi szum ulewy na wydechu.", "„Fiu” – wiatr, dmuchamy.", "Łączymy w deszczową piosenkę."], "easier": "Dziecko powtarza „kap” i „plum”.", "harder": "Dziecko utrzymuje „szszsz” długo.", "variant_1y": "Dziecko powtarza „kap” i „plum”.", "variant_2_3y": "Dziecko utrzymuje „szszsz” długo.", "song": "Kap, kap, kap – deszczyk kapie, / plum – do kałuży żaba skacze, / szszsz – ulewa szumi długo, / fiu – i wiatr przegonił chmurę długą!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych zagrożeń.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('777e824a-f9cf-5172-9e5a-b2328cee9c6e','Zabawy paluszkowe i masażyki','Domek dla paluszków',false,false,'2026-11-16','{"id": "2026-11-16-zabawy-paluszkowe-i-masazyki", "day": "2026-11-16", "weekday": null, "option": 13, "title": "Domek dla paluszków", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Rozwija palce i przygotowuje do zakładania rękawiczek.", "materials": "rękawiczka z jednym palcem i pięciopalczasta (do pokazania)", "steps": ["Pokazuj dłoń: to pięć paluszków.", "Kciuk ma swój pokoik – zginamy go osobno.", "Reszta śpi razem – zaciskamy cztery palce.", "Wkładamy rączkę do rękawiczki-jednopalczatki.", "Machamy „pa, pa”."], "easier": "Opiekunka zgina paluszki dziecka.", "harder": "Dziecko samo pokazuje „pokoik kciuka”.", "variant_1y": "Opiekunka zgina paluszki dziecka.", "variant_2_3y": "Dziecko samo pokazuje „pokoik kciuka”.", "song": "Kciuk ma pokoik sam dla siebie, / a czterej bracia śpią razem w niebie. / Rękawiczka – ciepły domek – / paluszki śpią jak kotek!", "song_author": "własna (KMK/Malachim)", "safety": "Rękawiczki bez ozdób.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('9ebf498c-8b5b-5595-bdb3-b517cf29138c','Zabawy słowno-ruchowe i rymowanki','Ubieramy się na spacer',false,false,'2026-11-16','{"id": "2026-11-16-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-11-16", "weekday": null, "option": 14, "title": "Ubieramy się na spacer", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Uczy kolejności ubierania przez zabawę.", "materials": "brak", "steps": ["Stajemy w kole.", "Mówimy rymowankę i „na niby” zakładamy rzeczy.", "Spodnie – skok w nogawki.", "Kurtka – ręce w rękawy.", "Czapka, szalik, buty – i „idziemy” w miejscu."], "easier": "Dziecko naśladuje ruchy opiekunki.", "harder": "Dziecko mówi, co zakładamy dalej.", "variant_1y": "Dziecko naśladuje ruchy opiekunki.", "variant_2_3y": "Dziecko mówi, co zakładamy dalej.", "song": "Najpierw spodnie – hop, hop, hop, / kurtka – rączki w rękaw: stop! / Czapka, szalik, buty – raz, / na spacerek idzie każdy z nas!", "song_author": "własna (KMK/Malachim)", "safety": "Skok „w nogawki” w miejscu.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4991e980-5c12-58d9-a819-7bec6582e9a0','Powitania i integracja','Kto dziś w czerwonej czapce?',false,false,'2026-11-16','{"id": "2026-11-16-powitania-i-integracja", "day": "2026-11-16", "weekday": null, "option": 15, "title": "Kto dziś w czerwonej czapce?", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Witamy się i zauważamy siebie nawzajem.", "materials": "czapki dzieci", "steps": ["Siadamy w kole z czapkami.", "Śpiewamy: „Kto ma czapkę czerwoną?”.", "Te dzieci wstają i machają.", "Wszyscy wołamy: „Dzień dobry!”.", "Zmieniamy kolor."], "easier": "Opiekunka pomaga wstać i pomachać.", "harder": "Dziecko rozpoznaje kolor swojej czapki.", "variant_1y": "Opiekunka pomaga wstać i pomachać.", "variant_2_3y": "Dziecko rozpoznaje kolor swojej czapki.", "song": "Kto ma czapkę czerwoną? / Niech wstanie i pomacha nią! / Dzień dobry, dzień dobry – / jak miło, że jesteś tu z nami, ty!", "song_author": "własna (KMK/Malachim)", "safety": "Czapki bez sznurków.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f830f05f-ddbf-5fbd-a1b1-c235836895c1','Świadomość ciała','Czapka na głowę, nie na nogę!',false,false,'2026-11-16','{"id": "2026-11-16-swiadomosc-ciala", "day": "2026-11-16", "weekday": null, "option": 16, "title": "Czapka na głowę, nie na nogę!", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Łączy ubrania z częściami ciała, z humorem.", "materials": "czapka, szalik, rękawiczki, skarpetka", "steps": ["Opiekunka „myli się”: zakłada czapkę na kolano.", "Dzieci wołają: „Nie! Na głowę!”.", "Rękawiczka na stopę – „Nie! Na rączkę!”.", "Dziecko pokazuje dobre miejsce.", "Śmiejemy się razem."], "easier": "Dziecko pokazuje część ciała na sobie.", "harder": "Dziecko samo „myli się” dla innych.", "variant_1y": "Dziecko pokazuje część ciała na sobie.", "variant_2_3y": "Dziecko samo „myli się” dla innych.", "song": "Czapka na nogę? Ojej, nie tak! / Na głowę czapka – to jest znak. / Rękawiczka na nos? Ha, ha, ha! / Na rączkę – to wie każdy z nas!", "song_author": "własna (KMK/Malachim)", "safety": "Szalik nie na szyję dziecka – tylko pokazujemy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('023480c0-72c4-5602-afad-ffef20f744bb','Pamięć/uwaga/naśladowanie','Czego brakuje na wieszaku?',false,false,'2026-11-16','{"id": "2026-11-16-pamiec-uwaga-nasladowanie", "day": "2026-11-16", "weekday": null, "option": 17, "title": "Czego brakuje na wieszaku?", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy pamięć wzrokową.", "materials": "wieszak lub sznurek nisko, czapka, szalik, rękawiczka", "steps": ["Wieszamy 3 rzeczy.", "Nazywamy je razem.", "Dzieci zasłaniają oczy.", "Zabieramy jedną.", "Pytamy: „Czego brakuje?”."], "easier": "2 rzeczy, dziecko szuka schowanej obok.", "harder": "3–4 rzeczy, dziecko nazywa brakującą.", "variant_1y": "2 rzeczy, dziecko szuka schowanej obok.", "variant_2_3y": "3–4 rzeczy, dziecko nazywa brakującą.", "song": "Czapka, szalik, rękawiczka – / ktoś tu schował jedną rzecz! / Otwórz oczka, popatrz, liczka – / czego brak? Powiedz: hej!", "song_author": "własna (KMK/Malachim)", "safety": "Sznurek na wysokości dorosłego, nie dla dzieci – zdejmuje opiekunka.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('724ba594-07e3-5eea-b870-b9cd12809311','Zabawy poznawcze','Pary rękawiczek',false,false,'2026-11-16','{"id": "2026-11-16-zabawy-poznawcze", "day": "2026-11-16", "weekday": null, "option": 18, "title": "Pary rękawiczek", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Dopasowuje pary według wyglądu.", "materials": "4–5 par dużych rękawiczek w różne wzory", "steps": ["Rozłóż pomieszane rękawiczki.", "Weź jedną: „Gdzie jej siostra?”.", "Dziecko szuka takiej samej.", "Kładziemy parę razem.", "Ubieramy pary misiom."], "easier": "2 pary bardzo różne.", "harder": "5 par podobnych.", "variant_1y": "2 pary bardzo różne.", "variant_2_3y": "5 par podobnych.", "song": "Rękawiczka szuka siostry, / taka sama – kropka w kropkę! / Znalazłam! Są już razem – / pięknie, kto parę odnalazł?", "song_author": "własna (KMK/Malachim)", "safety": "Rękawiczki bez ozdób.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('dae5457a-b637-5837-a7c8-f4dbefb54ce9','Zabawy na dworze','Plusk w kaloszach',false,false,'2026-11-16','{"id": "2026-11-16-zabawy-na-dworze", "day": "2026-11-16", "weekday": null, "option": 19, "title": "Plusk w kaloszach", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Doświadcza deszczu i kałuż bezpiecznie.", "materials": "kalosze, kurtki przeciwdeszczowe", "steps": ["Ubieramy się na deszcz.", "Szukamy płytkiej kałuży.", "Wchodzimy i tupiemy: plusk!", "Patrzymy na fale i odbicie.", "Wracamy i przebieramy się."], "easier": "Dziecko stoi w kałuży trzymane za rękę.", "harder": "Dziecko skacze obunóż i szuka odbicia.", "variant_1y": "Dziecko stoi w kałuży trzymane za rękę.", "variant_2_3y": "Dziecko skacze obunóż i szuka odbicia.", "song": "Plusk, plusk, w kałuży, / kalosze są od tej podróży! / Tup, tup, fala płynie, / i odbicie w wodzie zginie!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko płytkie kałuże (do kostki); nie przy ulicy; przebranie w suche rzeczy po powrocie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6dc1025a-3e1f-5149-bd6f-e4c031d576a9','Higiena','Czysty nosek',false,false,'2026-11-16','{"id": "2026-11-16-higiena", "day": "2026-11-16", "weekday": null, "option": 20, "title": "Czysty nosek", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Uczy wydmuchiwania nosa.", "materials": "chusteczki, lusterko, kosz z pokrywą", "steps": ["Ćwiczymy dmuchanie przez nos: zamykamy buzię, dmuchamy na piórko trzymane przez opiekunkę.", "Bierzemy chusteczkę.", "Zatykamy jedną dziurkę, dmuchamy.", "Chusteczka do kosza.", "Myjemy ręce."], "easier": "Opiekunka wyciera nosek, mówiąc, co robi.", "harder": "Dziecko samo próbuje wydmuchać.", "variant_1y": "Opiekunka wyciera nosek, mówiąc, co robi.", "variant_2_3y": "Dziecko samo próbuje wydmuchać.", "song": "Nosek dmucha: fff, fff, fff, / w chusteczkę, a nie w świat! / Do koszyka – hop – chusteczka, / myję rączki – czysta sprawa, czysta ręka!", "song_author": "własna (KMK/Malachim)", "safety": "Jedna chusteczka – jeden raz; kosz z pokrywą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e5a8e0f3-fe98-5f91-b89a-5815054e1786','Czytanie dziecku','Zgubiona rękawiczka Tosi (opowiadanie)',false,false,'2026-11-16','{"id": "2026-11-16-czytanie-dziecku", "day": "2026-11-16", "weekday": null, "option": 21, "title": "Zgubiona rękawiczka Tosi (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii i szuka przedmiotu wg wskazówek.", "materials": "rękawiczka czerwona schowana w sali, 3 obrazki: ławka, krzak, kałuża", "steps": ["Opowiadaj: „Tosia była na spacerze i zgubiła czerwoną rękawiczkę. Szukała na ławce – nie ma. Pod krzakiem – nie ma. A przy kałuży? Jest!”.", "Przy każdym miejscu pokazuj obrazek.", "Dzieci mówią „nie ma!”.", "Teraz szukamy rękawiczki w sali.", "Kto znajdzie, oddaje Tosi (lalce)."], "easier": "Dziecko patrzy na obrazki, szuka z opiekunką.", "harder": "Dziecko opowiada, gdzie Tosia szukała.", "variant_1y": "Dziecko patrzy na obrazki, szuka z opiekunką.", "variant_2_3y": "Dziecko opowiada, gdzie Tosia szukała.", "song": "Gdzie jest moja rękawiczka? / Nie ma jej, ojej, dziewczynka! / Ławka? Nie. Krzak? Też nie. / Jest przy kałuży – hej, hej, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Rękawiczkę chowamy na niskiej, bezpiecznej półce.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a1b76b12-ab0a-5cc8-a9b4-fb630a21e39e','Klocki/budowanie','Garaż przed deszczem',false,false,'2026-11-16','{"id": "2026-11-16-klocki-budowanie", "day": "2026-11-16", "weekday": null, "option": 22, "title": "Garaż przed deszczem", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje zadaszenie z klocków.", "materials": "duże klocki, płaska tektura jako dach, autka duże", "steps": ["Mówimy: pada deszcz, autka mokną!", "Budujemy 2 ściany z klocków.", "Kładziemy tekturę – dach.", "Wjeżdżamy autkami do garażu.", "Sprawdzamy: autka suche!"], "easier": "Dziecko wjeżdża autkiem do gotowego garażu.", "harder": "Dziecko buduje ściany samo.", "variant_1y": "Dziecko wjeżdża autkiem do gotowego garażu.", "variant_2_3y": "Dziecko buduje ściany samo.", "song": "Pada, pada, autko moknie – / zbudujemy garaż mocny! / Ściana, ściana, dach na górę – / autko w środku, schowane w chmurę!", "song_author": "własna (KMK/Malachim)", "safety": "Autka bez małych kółek do wyjęcia.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('74d2cf77-f62f-598e-bbd3-39b4968f473b','Wyciszenie','Deszczyk za oknem',false,false,'2026-11-16','{"id": "2026-11-16-wyciszenie", "day": "2026-11-16", "weekday": null, "option": 23, "title": "Deszczyk za oknem", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Uspokaja oddech przy dźwiękach deszczu.", "materials": "nagranie deszczu (cicho), koc", "steps": ["Dzieci leżą pod kocem.", "Słuchamy deszczu.", "Opiekunka stuka cicho palcami po plecach – „kap, kap”.", "Oddychamy wolno.", "Leżymy chwilę w ciszy."], "easier": "Dziecko na kolanach opiekunki.", "harder": "Dziecko leży samo i słucha.", "variant_1y": "Dziecko na kolanach opiekunki.", "variant_2_3y": "Dziecko leży samo i słucha.", "song": "Kapie deszczyk za okienkiem, / a mnie ciepło pod kocykiem. / Kap, kap, cicho, wolno, wolno – / oczka zamknąć mi wolno.", "song_author": "własna (KMK/Malachim)", "safety": "Nie zakrywamy głowy kocem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('58e634ad-c43c-585e-bd4e-b18036a2838b','Empatia','Miś zmarzł',false,false,'2026-11-16','{"id": "2026-11-16-empatia", "day": "2026-11-16", "weekday": null, "option": 24, "title": "Miś zmarzł", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy dbania o innych.", "materials": "miś, czapka, szalik, kocyk", "steps": ["Miś trzęsie się: „brr, zimno mi”.", "Pytamy: jak pomóc misiowi?", "Dzieci zakładają mu czapkę i szalik.", "Przykrywamy kocykiem.", "Miś dziękuje każdemu."], "easier": "Dziecko przykrywa misia kocykiem.", "harder": "Dziecko mówi, co misiowi dać.", "variant_1y": "Dziecko przykrywa misia kocykiem.", "variant_2_3y": "Dziecko mówi, co misiowi dać.", "song": "Misiu, misiu, czemu drżysz? / Czapki nie masz – teraz wiesz! / Damy szalik, damy koc – / ciepło misiu, dobranoc!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2e01c6ee-7277-59c3-ad87-f8b7cfe8ade1','Rodzina i dom','Czyja to czapka?',false,false,'2026-11-16','{"id": "2026-11-16-rodzina-i-dom", "day": "2026-11-16", "weekday": null, "option": 25, "title": "Czyja to czapka?", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Porównuje ubrania członków rodziny.", "materials": "czapka dorosła, dziecięca, niemowlęca (lub obrazki)", "steps": ["Pokaż 3 czapki.", "Pytamy: czyja duża? – taty/mamy.", "Średnia? – moja.", "Malutka? – dzidziusia.", "Przymierzamy: która pasuje?"], "easier": "Dziecko przymierza swoją czapkę.", "harder": "Dziecko układa czapki od największej.", "variant_1y": "Dziecko przymierza swoją czapkę.", "variant_2_3y": "Dziecko układa czapki od największej.", "song": "Duża czapka – tata ma, / średnia czapka – to ja, ja! / Malutka czapka – dla dzidziusia, / każdy w domu ma swój ciuszek!", "song_author": "własna (KMK/Malachim)", "safety": "Czapki czyste, bez sznurków.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('47d84c44-4009-5c80-99a7-3bfd9ff6ebc7','Pory roku i święta','Listopadowa słota',false,false,'2026-11-16','{"id": "2026-11-16-pory-roku-i-swieta", "day": "2026-11-16", "weekday": null, "option": 26, "title": "Listopadowa słota", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Obserwuje pogodę późnej jesieni.", "materials": "okno, obrazki: deszcz, wiatr, ciemno", "steps": ["Patrzymy przez okno.", "Pytamy: pada? wieje? jasno czy ciemno?", "Pokazujemy obrazek pogody dnia.", "Mówimy: w listopadzie szybko robi się ciemno.", "Naśladujemy wiatr i deszcz."], "easier": "Dziecko patrzy i wskazuje.", "harder": "Dziecko wybiera obrazek pogody.", "variant_1y": "Dziecko patrzy i wskazuje.", "variant_2_3y": "Dziecko wybiera obrazek pogody.", "song": "Listopad pada, listopad wieje, / szybko ciemno, nikt się nie śmieje? / A my ciepło się ubierzemy / i na spacer wyjdziemy!", "song_author": "własna (KMK/Malachim)", "safety": "Przy oknie – zamknięte okno, bez wspinania na parapet.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('cf7c2f30-08b3-58e7-963c-3fd35076b7e7','Kolory/kształty/wielkości','Kalosze duże i małe',false,false,'2026-11-16','{"id": "2026-11-16-kolory-ksztalty-wielkosci", "day": "2026-11-16", "weekday": null, "option": 27, "title": "Kalosze duże i małe", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Porównuje wielkości i kolory.", "materials": "kalosze w różnych rozmiarach i kolorach (lub wycięte z kartonu)", "steps": ["Rozkładamy kalosze.", "Szukamy dużych i małych.", "Sortujemy: duże tu, małe tam.", "Potem według koloru.", "Dziecko przykłada swoją stopę."], "easier": "Dziecko porównuje 2 kalosze.", "harder": "Dziecko sortuje wg 2 cech.", "variant_1y": "Dziecko porównuje 2 kalosze.", "variant_2_3y": "Dziecko sortuje wg 2 cech.", "song": "Duży kalosz – tup, tup, tup, / mały kalosz – tip, tip, tip! / Czerwony, żółty, niebieski – / ustawimy je jak pieski!", "song_author": "własna (KMK/Malachim)", "safety": "Kalosze czyste.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ciepło się ubieramy – czapka, szalik, kalosze", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('af9eb739-d3ac-56b3-96d4-b7c87c2ef2c2','Ruch','Misie idą do gawry',false,false,'2026-11-23','{"id": "2026-11-23-ruch", "day": "2026-11-23", "weekday": null, "option": 1, "title": "Misie idą do gawry", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy chodzenie na czworakach i czołganie.", "materials": "stół przykryty kocem (gawra), mata", "steps": ["Opowiedz: misie idą spać na zimę.", "Chodzimy ciężko jak misie: tup, tup.", "Na czworakach przechodzimy do gawry.", "W gawrze kulimy się i „śpimy”.", "„Wiosna!” – wychodzimy i przeciągamy się."], "easier": "Dziecko raczkuje do gawry za opiekunką.", "harder": "Dziecko przechodzi tor: krok misia, czworaki, przeciąganie.", "variant_1y": "Dziecko raczkuje do gawry za opiekunką.", "variant_2_3y": "Dziecko przechodzi tor: krok misia, czworaki, przeciąganie.", "song": "Idzie miś przez gęsty las, / tup, tup, tup – już spać czas. / Do gawry wchodzi na czworakach – / śpi do wiosny, aż zaśpiewa ptak!", "song_author": "własna (KMK/Malachim)", "safety": "Stół stabilny, krawędzie zabezpieczone; koc nie zwisa do ziemi z obu stron (dziecko widzi wyjście).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5c741dba-feee-5ef5-8457-456882706dd0','Muzyka','Misiowy taniec',false,false,'2026-11-23','{"id": "2026-11-23-muzyka", "day": "2026-11-23", "weekday": null, "option": 2, "title": "Misiowy taniec", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Reaguje ruchem na tempo muzyki.", "materials": "pluszowy miś dla każdego, muzyka szybka i wolna", "steps": ["Każde dziecko bierze misia.", "Muzyka szybka – tańczymy z misiem.", "Muzyka wolna – kołyszemy misia.", "Cisza – miś śpi, kładziemy go.", "Powtarzamy."], "easier": "Taniec na rękach opiekunki z misiem.", "harder": "Dziecko samo zmienia ruch wg tempa.", "variant_1y": "Taniec na rękach opiekunki z misiem.", "variant_2_3y": "Dziecko samo zmienia ruch wg tempa.", "song": "Tańczy miś: raz, dwa, trzy, / tańczę z misiem ja i ty! / Wolno, wolno – kołysanka, / cicho – miś śpi do poranka.", "song_author": "własna (KMK/Malachim)", "safety": "Misie bez guzików i plastikowych oczek do oderwania.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e26a7628-95e2-5a9b-86eb-aea5dacdaca1','Sensoryka','Miękki, twardy, puchaty',false,false,'2026-11-23','{"id": "2026-11-23-sensoryka", "day": "2026-11-23", "weekday": null, "option": 3, "title": "Miękki, twardy, puchaty", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Rozróżnia cechy dotykowe.", "materials": "miś pluszowy, duży drewniany klocek, gąbka, szczotka do ubrań (miękka)", "steps": ["Rozkładamy rzeczy na kocu.", "Dotykamy misia: miękki, puchaty.", "Klocek: twardy.", "Gąbka: ugina się.", "Szukamy w sali innych miękkich rzeczy."], "easier": "Dziecko dotyka i ściska z opiekunką.", "harder": "Dziecko sortuje: miękkie – twarde.", "variant_1y": "Dziecko dotyka i ściska z opiekunką.", "variant_2_3y": "Dziecko sortuje: miękkie – twarde.", "song": "Miś jest miękki jak chmurka, / klocek twardy jak górka, / gąbka – ściśnij: psss, / co jest miękkie? Powiedz mi!", "song_author": "własna (KMK/Malachim)", "safety": "Przedmioty duże, czyste.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('dbcc064d-ece8-58b4-91b6-7187bf012516','Emocje','Miś boi się ciemności',false,false,'2026-11-23','{"id": "2026-11-23-emocje", "day": "2026-11-23", "weekday": null, "option": 4, "title": "Miś boi się ciemności", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Nazywa strach i uczy się pocieszać.", "materials": "miś, latarka LED, kocyk", "steps": ["Miś mówi: „Boję się, ciemno”.", "Pytamy dzieci: czego się boją?", "Zapalamy latarkę – miś widzi, że nic nie ma.", "Przytulamy misia, przykrywamy kocykiem.", "Mówimy: „Strach mija, gdy ktoś jest blisko”."], "easier": "Dziecko przytula misia.", "harder": "Dziecko mówi, co pomaga, gdy się boi.", "variant_1y": "Dziecko przytula misia.", "variant_2_3y": "Dziecko mówi, co pomaga, gdy się boi.", "song": "Ciemno, ciemno – misiu drży, / nie bój się, jesteśmy my! / Zapal światło – pstryk – i już, / misiu śpi, nie boi się już.", "song_author": "własna (KMK/Malachim)", "safety": "Nie gasimy światła w sali; latarka nie w oczy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('8f903edf-c823-502e-a493-357a8999db1d','Zmysły','Gdzie zadzwonił miś?',false,false,'2026-11-23','{"id": "2026-11-23-zmysly", "day": "2026-11-23", "weekday": null, "option": 5, "title": "Gdzie zadzwonił miś?", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Ćwiczy lokalizację dźwięku.", "materials": "miś, pozytywka lub telefon z cichą melodią", "steps": ["Pokaż pozytywkę.", "Chowamy ją z misiem w sali.", "Dzieci słuchają, skąd gra.", "Idą w stronę dźwięku.", "Kto znajdzie – bije brawo."], "easier": "Dziecko szuka z opiekunką za rękę.", "harder": "Dziecko szuka samo i wskazuje kierunek.", "variant_1y": "Dziecko szuka z opiekunką za rękę.", "variant_2_3y": "Dziecko szuka samo i wskazuje kierunek.", "song": "Gra, gra muzyczka, / gdzie się schował miś? Ciszka! / Uszko słucha – tam, tam, tam – / znalazłam misia sam!", "song_author": "własna (KMK/Malachim)", "safety": "Pozytywka bez dostępnych drobnych części; chowamy nisko, bez wspinania.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e27e67ad-8b98-55c6-9bd5-8fd57d5490c6','Zwierzęta','Miś brunatny i miś polarny',false,false,'2026-11-23','{"id": "2026-11-23-zwierzeta", "day": "2026-11-23", "weekday": null, "option": 6, "title": "Miś brunatny i miś polarny", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje dwa gatunki niedźwiedzi.", "materials": "duże zdjęcia: niedźwiedź brunatny i polarny", "steps": ["Pokaż oba zdjęcia.", "Brunatny: brązowy, w lesie, lubi miód.", "Polarny: biały, na lodzie, pływa.", "Naśladujemy: brunatny wącha miód, polarny pływa.", "Pytamy: który jest biały?"], "easier": "Dziecko wskazuje misia na obrazku.", "harder": "Dziecko mówi kolor i gdzie mieszka miś.", "variant_1y": "Dziecko wskazuje misia na obrazku.", "variant_2_3y": "Dziecko mówi kolor i gdzie mieszka miś.", "song": "Brązowy miś w lesie mieszka, / miodek zjada, łapą łaska. / Biały miś na lodzie śpi, / pływa w morzu – brr, brr, brr!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('8d96f534-8b3a-502b-bc02-9baac049f626','Pogoda','Miś zasypia, bo idzie zima',false,false,'2026-11-23','{"id": "2026-11-23-pogoda", "day": "2026-11-23", "weekday": null, "option": 7, "title": "Miś zasypia, bo idzie zima", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Łączy zimno z zasypianiem niedźwiedzi.", "materials": "miś, kocyk, białe chusty (śnieg)", "steps": ["Mówimy: robi się zimno.", "Miś ziewa – idzie spać.", "Przykrywamy misia kocykiem.", "Sypiemy „śnieg” – białe chusty na kocyk.", "Szepczemy: „Śpij do wiosny”."], "easier": "Dziecko przykrywa misia.", "harder": "Dziecko mówi, kiedy miś się obudzi.", "variant_1y": "Dziecko przykrywa misia.", "variant_2_3y": "Dziecko mówi, kiedy miś się obudzi.", "song": "Zimny wiatr i biały śnieg, / miś zasypia – cicho, hej! / Śpij do wiosny, misiu mój, / śnieżek kocyk będzie twój.", "song_author": "własna (KMK/Malachim)", "safety": "Chusty nie na twarz dzieci.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2d0cdf25-815d-5ca2-a265-738f45a54573','Przyroda','Co je miś?',false,false,'2026-11-23','{"id": "2026-11-23-przyroda", "day": "2026-11-23", "weekday": null, "option": 8, "title": "Co je miś?", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Poznaje, czym żywią się niedźwiedzie.", "materials": "obrazki: miód, maliny, ryba, grzyby, samochód (na żart)", "steps": ["Pokaż obrazki.", "Pytamy: czy miś je miód? – tak!", "Maliny? – tak. Ryba? – tak.", "Samochód? – nie! Śmiejemy się.", "Karmimy misia obrazkami."], "easier": "Dziecko podaje obrazek misiowi.", "harder": "Dziecko odrzuca rzecz niejadalną.", "variant_1y": "Dziecko podaje obrazek misiowi.", "variant_2_3y": "Dziecko odrzuca rzecz niejadalną.", "song": "Miś je miodek, mniam, mniam, mniam, / malinki i rybkę tam, / a samochód? Nie, nie, nie – / samochodu miś nie je!", "song_author": "własna (KMK/Malachim)", "safety": "Obrazki zalaminowane, duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('60b315ee-1973-5c65-b6d7-fc7772302562','Eksperymenty','Pływa czy tonie?',false,false,'2026-11-23','{"id": "2026-11-23-eksperymenty", "day": "2026-11-23", "weekday": null, "option": 9, "title": "Pływa czy tonie?", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje przedmioty w wodzie.", "materials": "miska z wodą na tacy, gumowy miś (kąpielowy), drewniany klocek duży, metalowa łyżka duża, gąbka", "steps": ["Pokaż miskę z wodą.", "Wkładamy gumowego misia – pływa!", "Łyżkę – tonie.", "Klocek – pływa. Gąbka – pływa, potem nasiąka.", "Pytamy dzieci przed każdą rzeczą: pływa?"], "easier": "Dziecko wrzuca i patrzy.", "harder": "Dziecko przewiduje i sortuje.", "variant_1y": "Dziecko wrzuca i patrzy.", "variant_2_3y": "Dziecko przewiduje i sortuje.", "song": "Plum do wody – co się stanie? / Pływa miś jak na dywanie! / Łyżka – bul, bul – idzie w dół, / pływa, tonie – zgadnij, ktoś!", "song_author": "własna (KMK/Malachim)", "safety": "Mała ilość wody, stały nadzór; wycieramy podłogę; nigdy nie zostawiamy dziecka przy wodzie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b84f0b15-8e64-5150-acc9-d4bdf5964394','Plastyka','Brązowy miś z gąbki',false,false,'2026-11-23','{"id": "2026-11-23-plastyka", "day": "2026-11-23", "weekday": null, "option": 10, "title": "Brązowy miś z gąbki", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Stempluje gąbką.", "materials": "kontur misia na kartce, brązowa farba, duże gąbki do stemplowania", "steps": ["Pokaż kontur misia.", "Maczamy gąbkę w farbie.", "Stemplujemy brzuszek i łapki.", "Opiekunka dorysowuje uśmiech.", "Suszymy pracę."], "easier": "Stemplowanie z pomocą, swobodnie.", "harder": "Stemplowanie w konturze.", "variant_1y": "Stemplowanie z pomocą, swobodnie.", "variant_2_3y": "Stemplowanie w konturze.", "song": "Stuk, stuk – gąbka skacze, / miś brązowy się zobaczy! / Brzuszek, łapki, uszka dwa – / misia z gąbki każdy ma!", "song_author": "własna (KMK/Malachim)", "safety": "Gąbki duże, bez odrywania kawałków; farba z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('198a42c5-33a9-5c63-855c-35bb9bd53db0','Samoobsługa','Usypiam misia',false,false,'2026-11-23','{"id": "2026-11-23-samoobsluga", "day": "2026-11-23", "weekday": null, "option": 11, "title": "Usypiam misia", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy czynności: kładzenie, przykrywanie, odkładanie.", "materials": "misie, kocyki, koszyk-łóżko", "steps": ["Każde dziecko ma misia.", "Kładziemy misia do łóżka-koszyka.", "Przykrywamy kocykiem.", "Mówimy „dobranoc”.", "Rano – składamy kocyk i odkładamy na półkę."], "easier": "Dziecko kładzie misia, opiekunka pomaga przykryć.", "harder": "Dziecko składa kocyk samo.", "variant_1y": "Dziecko kładzie misia, opiekunka pomaga przykryć.", "variant_2_3y": "Dziecko składa kocyk samo.", "song": "Do łóżeczka, misiu mój, / kocyk ciepły jest już twój. / Rano wstajesz, kocyk złóż – / na półeczkę, dobrze już!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('aace638d-c982-505e-ab43-e923b5aa0435','Język/logorytmika','Miś mruczy: mmm',false,false,'2026-11-23','{"id": "2026-11-23-jezyk-logorytmika", "day": "2026-11-23", "weekday": null, "option": 12, "title": "Miś mruczy: mmm", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy wargi i głoski m, b, p.", "materials": "miś", "steps": ["Miś mruczy: mmm – zamknięte usta.", "Miś je: mniam, mniam.", "Miś pęka bańka: pa, pa, pa.", "Miś bębni: bum, bum.", "Powtarzamy w rytmie."], "easier": "Dziecko mruczy z opiekunką.", "harder": "Dziecko powtarza sekwencję 3 dźwięków.", "variant_1y": "Dziecko mruczy z opiekunką.", "variant_2_3y": "Dziecko powtarza sekwencję 3 dźwięków.", "song": "Mmm – mruczy miś, / mniam – miodek dziś, / bum, bum – w brzuszek bije, / pa, pa – miś już chrapie: chrrr!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('77f3803f-e2f7-5e54-9293-1d873a15195a','Zabawy paluszkowe i masażyki','Miś po plecach chodzi',false,false,'2026-11-23','{"id": "2026-11-23-zabawy-paluszkowe-i-masazyki", "day": "2026-11-23", "weekday": null, "option": 13, "title": "Miś po plecach chodzi", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Masażyk wyciszający i budujący bliskość.", "materials": "brak", "steps": ["Dzieci siadają przodem.", "„Miś idzie” – stąpamy dłońmi po plecach.", "„Zbiera maliny” – szczypiemy lekko.", "„Zjada miód” – kółka dłonią.", "„Idzie spać” – głaszczemy w dół."], "easier": "Na kolanach opiekunki, bardzo lekko.", "harder": "Dziecko robi masażyk misiowi lub koledze.", "variant_1y": "Na kolanach opiekunki, bardzo lekko.", "variant_2_3y": "Dziecko robi masażyk misiowi lub koledze.", "song": "Idzie miś po ścieżce – tup, tup, / zbiera maliny – szczyp, szczyp, / zjada miodek – kółko, kółko, / i idzie spać – cichutko, cichutko.", "song_author": "własna (KMK/Malachim)", "safety": "Delikatnie; przerwij przy niechęci.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('582a296c-4272-50ca-b6be-2cfc32f70757','Zabawy słowno-ruchowe i rymowanki','Miś na spacerze',false,false,'2026-11-23','{"id": "2026-11-23-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-11-23", "weekday": null, "option": 14, "title": "Miś na spacerze", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Wykonuje ruchy do rymowanki.", "materials": "brak", "steps": ["Stajemy.", "Mówimy rymowankę i pokazujemy.", "Miś idzie – maszerujemy.", "Miś się drapie, ziewa, przeciąga.", "Miś siada – siadamy."], "easier": "Dziecko naśladuje 2–3 ruchy.", "harder": "Dziecko mówi rymowankę z opiekunką.", "variant_1y": "Dziecko naśladuje 2–3 ruchy.", "variant_2_3y": "Dziecko mówi rymowankę z opiekunką.", "song": "Miś na spacer idzie – tup, / drapie się po plecach – drap, / ziewa szeroko – aaa, / przeciąga się – ha! / i siada – bach!", "song_author": "własna (KMK/Malachim)", "safety": "Siadamy na matę.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e86036c9-7325-55a5-8946-fd5a8fd57a48','Powitania i integracja','Miś wita każde dziecko',false,false,'2026-11-23','{"id": "2026-11-23-powitania-i-integracja", "day": "2026-11-23", "weekday": null, "option": 15, "title": "Miś wita każde dziecko", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Buduje więź i poczucie bycia zauważonym.", "materials": "duży pluszowy miś", "steps": ["Siadamy w kole.", "Miś podchodzi do dziecka.", "Miś mówi „Dzień dobry, (imię)!”.", "Dziecko daje misiowi rączkę lub przytula.", "Miś idzie dalej."], "easier": "Opiekunka z misiem podchodzi blisko.", "harder": "Dziecko samo prowadzi misia do kolegi.", "variant_1y": "Opiekunka z misiem podchodzi blisko.", "variant_2_3y": "Dziecko samo prowadzi misia do kolegi.", "song": "Miś wędruje dookoła, / kogo dzisiaj miś zawoła? / Dzień dobry, (imię), jak się masz? / Przytul misia – to twój czas!", "song_author": "własna (KMK/Malachim)", "safety": "Szanujemy dziecko, które nie chce przytulać.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a84faeeb-5b31-5198-978b-bd0019003fba','Świadomość ciała','Miś ma, ja mam',false,false,'2026-11-23','{"id": "2026-11-23-swiadomosc-ciala", "day": "2026-11-23", "weekday": null, "option": 16, "title": "Miś ma, ja mam", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Nazywa części ciała na misiu i na sobie.", "materials": "miś", "steps": ["Pokaż uszy misia.", "Dzieci pokazują swoje uszy.", "Łapki misia – nasze rączki.", "Brzuszek, nosek, oczy.", "Miś nie ma butów – a ja?"], "easier": "Opiekunka prowadzi rękę dziecka.", "harder": "Dziecko samo nazywa części.", "variant_1y": "Opiekunka prowadzi rękę dziecka.", "variant_2_3y": "Dziecko samo nazywa części.", "song": "Miś ma uszka – ja też mam! / Miś ma nosek – pokaż sam! / Miś ma brzuszek, łapki dwie, / a ja rączki – patrz, o, te!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2d8428b2-7740-52c4-a8bc-9563a2131e95','Pamięć/uwaga/naśladowanie','Który miś się schował?',false,false,'2026-11-23','{"id": "2026-11-23-pamiec-uwaga-nasladowanie", "day": "2026-11-23", "weekday": null, "option": 17, "title": "Który miś się schował?", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy pamięć wzrokową.", "materials": "3 różne misie, kocyk", "steps": ["Ustawiamy 3 misie.", "Nazywamy je (duży, biały, mały).", "Zasłaniamy oczy.", "Chowamy jednego pod kocyk.", "Pytamy: kogo brakuje?"], "easier": "2 misie, dziecko odkrywa kocyk.", "harder": "3–4 misie, dziecko nazywa brakującego.", "variant_1y": "2 misie, dziecko odkrywa kocyk.", "variant_2_3y": "3–4 misie, dziecko nazywa brakującego.", "song": "Trzy misie siedziały w rządku, / jeden się schował – w kątku? / Otwórz oczy – raz, dwa, trzy – / którego misia nie ma? Ty!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('801210fa-e6e0-58d4-811c-1485a5995986','Zabawy poznawcze','Miś na, pod, w',false,false,'2026-11-23','{"id": "2026-11-23-zabawy-poznawcze", "day": "2026-11-23", "weekday": null, "option": 18, "title": "Miś na, pod, w", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Rozumie słowa: na, pod, w.", "materials": "miś, pudełko, krzesełko", "steps": ["Kładziemy misia na krzesełku: „miś jest na”.", "Pod krzesełkiem.", "W pudełku.", "Prosimy dziecko: „Połóż misia pod”.", "Chwalimy."], "easier": "Dziecko wykonuje 1 polecenie z gestem.", "harder": "Dziecko wykonuje 3 polecenia bez gestu.", "variant_1y": "Dziecko wykonuje 1 polecenie z gestem.", "variant_2_3y": "Dziecko wykonuje 3 polecenia bez gestu.", "song": "Miś na krześle – hop, hop, hop, / miś pod krzesłem – bęc i stop, / miś w pudełku – cicho śpi – / gdzie jest miś? Powiedz mi!", "song_author": "własna (KMK/Malachim)", "safety": "Krzesełko stabilne.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f2454f9f-62fc-57b1-a21b-d19ae46dfc56','Zabawy na dworze','Tropy misia',false,false,'2026-11-23','{"id": "2026-11-23-zabawy-na-dworze", "day": "2026-11-23", "weekday": null, "option": 19, "title": "Tropy misia", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Idzie po śladach i obserwuje.", "materials": "kreda lub wycięte z kartonu ślady łap", "steps": ["Rysujemy na chodniku ślady łap.", "Dzieci idą po śladach.", "Na końcu czeka miś.", "Dzieci stawiają swoje ślady obok (tupią).", "Wracamy z misiem."], "easier": "Dziecko idzie za rękę.", "harder": "Dziecko skacze ze śladu na ślad.", "variant_1y": "Dziecko idzie za rękę.", "variant_2_3y": "Dziecko skacze ze śladu na ślad.", "song": "Tu był miś, tu stawiał łapy, / pójdziemy za nim do chałupy! / Krok i krok, i jeszcze krok – / jest nasz miś – hop!", "song_author": "własna (KMK/Malachim)", "safety": "Trasa w ogrodzie żłobka, bez ruchu ulicznego.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('425fc3dd-138c-5b4e-ac19-682add023718','Higiena','Myjemy łapki – miś i ja',false,false,'2026-11-23','{"id": "2026-11-23-higiena", "day": "2026-11-23", "weekday": null, "option": 20, "title": "Myjemy łapki – miś i ja", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Utrwala mycie rąk przed posiłkiem.", "materials": "gumowe zwierzątko-miś, umywalka, mydło", "steps": ["Miś idzie na obiad – ale ma brudne łapki!", "Myjemy misia gumowego w wodzie.", "Teraz my myjemy ręce.", "Wycieramy.", "Miś i my – czyste łapki!"], "easier": "Opiekunka myje z dzieckiem.", "harder": "Dziecko myje samo misia i siebie.", "variant_1y": "Opiekunka myje z dzieckiem.", "variant_2_3y": "Dziecko myje samo misia i siebie.", "song": "Miś ma łapki brudne – fe! / Myjemy, myjemy – szu, szu, hej! / Teraz ja, rączki dwie – / czyste łapki – mniam, jem!", "song_author": "własna (KMK/Malachim)", "safety": "Letnia woda; mokra podłoga.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('8193718e-db12-5447-ab92-8ab1629dfd72','Czytanie dziecku','Miś Bruno nie może zasnąć (opowiadanie)',false,false,'2026-11-23','{"id": "2026-11-23-czytanie-dziecku", "day": "2026-11-23", "weekday": null, "option": 21, "title": "Miś Bruno nie może zasnąć (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii o wieczornym rytuale.", "materials": "miś, kocyk, książeczka-obrazki: kąpiel, piżama, kołysanka", "steps": ["Opowiadaj: „Bruno nie mógł zasnąć. Wykąpał się – dalej nie śpi. Założył piżamę – nie śpi. Mama zaśpiewała kołysankę – i Bruno zasnął”.", "Pokazuj obrazki.", "Dzieci mówią „nie śpi!”.", "Na końcu szepczemy „śpi”.", "Pytamy: co robisz przed snem?"], "easier": "Dziecko słucha i przytula misia.", "harder": "Dziecko opowiada swój wieczór.", "variant_1y": "Dziecko słucha i przytula misia.", "variant_2_3y": "Dziecko opowiada swój wieczór.", "song": "Bruno, Bruno, czemu nie śpisz? / Kąpiel, piżamka – jeszcze nie! / Mama śpiewa: lulu, lu – / i już Bruno śpi: chrr, chrr!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ef0e80d6-8263-5327-829d-f5bc6460dd9b','Klocki/budowanie','Łóżko dla misia',false,false,'2026-11-23','{"id": "2026-11-23-klocki-budowanie", "day": "2026-11-23", "weekday": null, "option": 22, "title": "Łóżko dla misia", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje płaską budowlę z klocków.", "materials": "duże klocki, misie", "steps": ["Mówimy: miś chce spać, nie ma łóżka.", "Układamy klocki płasko w prostokąt.", "Kładziemy misia.", "Dobudowujemy poduszkę.", "Przykrywamy chustką."], "easier": "Dziecko kładzie klocki obok siebie.", "harder": "Dziecko buduje łóżko z oparciem.", "variant_1y": "Dziecko kładzie klocki obok siebie.", "variant_2_3y": "Dziecko buduje łóżko z oparciem.", "song": "Klocek, klocek, obok klocek – / łóżko dla misia – hop, skok! / Poduszeczka, kocyk – już, / śpi nasz misio, ani rusz!", "song_author": "własna (KMK/Malachim)", "safety": "Duże klocki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4fd59898-9d2a-5b24-99a5-51fc51e426e5','Wyciszenie','Kołysanka dla misia',false,false,'2026-11-23','{"id": "2026-11-23-wyciszenie", "day": "2026-11-23", "weekday": null, "option": 23, "title": "Kołysanka dla misia", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza, uczy kołysania i ciszy.", "materials": "misie, przyciemnione światło (nie ciemno)", "steps": ["Dzieci siadają z misiami.", "Kołyszemy misie w ramionach.", "Śpiewamy cicho kołysankę.", "Kładziemy się z misiem.", "Chwila ciszy."], "easier": "Opiekunka kołysze dziecko z misiem.", "harder": "Dziecko kołysze misia samo i śpiewa.", "variant_1y": "Opiekunka kołysze dziecko z misiem.", "variant_2_3y": "Dziecko kołysze misia samo i śpiewa.", "song": "Lulaj, misiu, lulaj, lu, / gwiazdka świeci, śpij już tu. / Kołysz, kołysz, ciepło tak – / śpi już misiu, śpi i ja.", "song_author": "własna (KMK/Malachim)", "safety": "Nie zasypiamy dzieci z misiem bez nadzoru.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7dd461bc-1da2-5386-a917-8861f6136a32','Empatia','Misiowi coś się stało',false,false,'2026-11-23','{"id": "2026-11-23-empatia", "day": "2026-11-23", "weekday": null, "option": 24, "title": "Misiowi coś się stało", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy troski i pomocy.", "materials": "miś, bandaż elastyczny (szeroki), kocyk", "steps": ["Miś się przewrócił – boli łapka.", "Pytamy: co zrobimy?", "Dmuchamy na łapkę.", "Owijamy bandażem.", "Przytulamy i kładziemy misia na kocyk."], "easier": "Dziecko dmucha i głaszcze.", "harder": "Dziecko owija bandaż i mówi „nie płacz”.", "variant_1y": "Dziecko dmucha i głaszcze.", "variant_2_3y": "Dziecko owija bandaż i mówi „nie płacz”.", "song": "Misiu upadł – ała, ała, / łapka boli, łapka mała! / Dmuchu, dmuchu, bandaż – raz, / misiu zdrowy jest za czas!", "song_author": "własna (KMK/Malachim)", "safety": "Bandaż tylko na misiu, nie owijamy dzieci; bez agrafek i plastrów.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('608dcf57-d061-555d-8d68-d104449d9f58','Rodzina i dom','Mój miś z domu',false,false,'2026-11-23','{"id": "2026-11-23-rodzina-i-dom", "day": "2026-11-23", "weekday": null, "option": 25, "title": "Mój miś z domu", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Opowiada o ulubionej zabawce i bliskich.", "materials": "misie przyniesione z domu (podpisane)", "steps": ["Dzieci siadają z misiami z domu.", "Każde pokazuje swojego misia.", "Opiekunka pyta: jak się nazywa? kto go dał?", "Misie poznają się (witają łapkami).", "Odkładamy misie na półkę gości."], "easier": "Dziecko pokazuje misia.", "harder": "Dziecko mówi imię misia i kto go dał.", "variant_1y": "Dziecko pokazuje misia.", "variant_2_3y": "Dziecko mówi imię misia i kto go dał.", "song": "Mój misiu przyszedł z domu, / nie oddam go nikomu! / Mama dała, babcia dała – / misia kocha rodzina cała!", "song_author": "własna (KMK/Malachim)", "safety": "Sprawdź zabawki z domu: guziki, oczka, kokardy – zdejmij lub odłóż wyżej.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7399f4f3-a33b-5a39-b012-264725dcd964','Pory roku i święta','Urodziny misia',false,false,'2026-11-23','{"id": "2026-11-23-pory-roku-i-swieta", "day": "2026-11-23", "weekday": null, "option": 26, "title": "Urodziny misia", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Świętuje Dzień Pluszowego Misia (25 XI).", "materials": "misie, kartonowy tort z „świeczkami” z papieru", "steps": ["Mówimy: dziś święto misiów!", "Misie siadają przy stole.", "Śpiewamy nasze „Sto misiów”.", "Dmuchamy papierowe świeczki.", "Tańczymy z misiami."], "easier": "Dziecko dmucha i klaszcze.", "harder": "Dziecko śpiewa i składa życzenia misiowi.", "variant_1y": "Dziecko dmucha i klaszcze.", "variant_2_3y": "Dziecko śpiewa i składa życzenia misiowi.", "song": "Sto misiów, sto misiów, / niech żyje nam misio! / Dmuchnij świeczki: fuu, fuu, fuu – / wszystkiego dobrego, misiu mój!", "song_author": "własna (KMK/Malachim)", "safety": "Bez prawdziwych świeczek i ognia; bez słodyczy (alergie).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d1439294-1366-52f2-a676-f0acb1ab1ae8','Kolory/kształty/wielkości','Duży, średni, mały miś',false,false,'2026-11-23','{"id": "2026-11-23-kolory-ksztalty-wielkosci", "day": "2026-11-23", "weekday": null, "option": 27, "title": "Duży, średni, mały miś", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Porządkuje według wielkości.", "materials": "3 misie różnej wielkości, 3 miski, 3 kocyki", "steps": ["Pokaż 3 misie.", "Kto największy? kto najmniejszy?", "Dajemy miski: dużą dużemu…", "Kocyki – tak samo.", "Ustawiamy misie od największego."], "easier": "Dziecko wskazuje dużego i małego.", "harder": "Dziecko układa 3 w kolejności.", "variant_1y": "Dziecko wskazuje dużego i małego.", "variant_2_3y": "Dziecko układa 3 w kolejności.", "song": "Duży miś – duża miska, / średni miś – średnia, blisko, / mały miś – malutka miseczka – / każdy ma swoje, nie ma sprzeczka!", "song_author": "własna (KMK/Malachim)", "safety": "Miski plastikowe.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mój pluszowy miś", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('694ff456-5ba4-5774-b79b-71d4ef276ad4','Ruch','Renifery biegną',false,false,'2026-11-30','{"id": "2026-11-30-ruch", "day": "2026-11-30", "weekday": null, "option": 1, "title": "Renifery biegną", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy bieg, galop i zatrzymanie.", "materials": "opaska z dużym dzwonkiem przyszytym na stałe (dla opiekunki)", "steps": ["Pokaż rogi reniferów – dłonie na głowie.", "Biegniemy lekko jak renifery.", "Opiekunka dzwoni – biegniemy; cisza – stop.", "Skaczemy przez „zaspę” (poduszkę).", "Odpoczywamy w „stajni”."], "easier": "Bieg za rękę opiekunki.", "harder": "Galop i zatrzymanie na sygnał.", "variant_1y": "Bieg za rękę opiekunki.", "variant_2_3y": "Galop i zatrzymanie na sygnał.", "song": "Biegną, biegną renifery, / rogi w górze, kopytka cztery! / Dzyń, dzyń – biegniemy w dal, / cisza – stop! Mikołaj stał.", "song_author": "własna (KMK/Malachim)", "safety": "Dzwonek tylko u opiekunki; przestrzeń bez przeszkód.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b64e3f67-529b-5817-8075-fe2d63701c13','Muzyka','Dzwoneczki Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-muzyka", "day": "2026-11-30", "weekday": null, "option": 2, "title": "Dzwoneczki Mikołaja", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Gra na instrumencie zgodnie z sygnałem.", "materials": "bransoletki z dzwonkami na rzep z atestem (dzwonki zabezpieczone) lub tamburyn", "steps": ["Zakładamy bransoletki na rączki.", "Sanie jadą – dzwonimy.", "Sanie stoją – cisza.", "Gramy głośno i cichutko.", "Zdejmujemy i liczymy bransoletki."], "easier": "Opiekunka potrząsa rączką dziecka.", "harder": "Dziecko reaguje na sygnał samo.", "variant_1y": "Opiekunka potrząsa rączką dziecka.", "variant_2_3y": "Dziecko reaguje na sygnał samo.", "song": "Dzyń, dzyń, dzyń – sanie jadą, / Mikołaj wiezie paczek gromadę. / Cicho – sanie stoją w śniegu, / dzyń, dzyń – znowu są w biegu!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko instrumenty z atestem 0–3, dzwonki wszyte/zamknięte; sprawdź przed i po zajęciach.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('366239bc-b61e-5be9-ac71-ce8639142712','Sensoryka','Broda Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-sensoryka", "day": "2026-11-30", "weekday": null, "option": 3, "title": "Broda Mikołaja", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Doświadcza miękkich i szorstkich faktur.", "materials": "karton z przyklejoną watoliną (broda), kawałek filcu czerwonego, szczotka miękka", "steps": ["Pokaż obrazek Mikołaja z brodą.", "Dotykamy brody z watoliny – miękka.", "Filc – czapka Mikołaja – trochę szorstki.", "Głaszczemy policzek brodą.", "Nazywamy: miękkie, szorstkie."], "easier": "Dotyk z opiekunką.", "harder": "Dziecko porównuje 3 faktury.", "variant_1y": "Dotyk z opiekunką.", "variant_2_3y": "Dziecko porównuje 3 faktury.", "song": "Broda biała, miękka jak śnieg, / czapka czerwona – ho, ho, hej! / Pogłaszcz brodę, pogłaszcz policzek – / Mikołaj idzie, już blisko jego wózek!", "song_author": "własna (KMK/Malachim)", "safety": "Watolina przyklejona na stałe, bez luźnych kłaczków (ryzyko wdychania/połknięcia).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('103e8962-a88a-56f2-a20c-65d7d6f49ce4','Emocje','Niespodzianka!',false,false,'2026-11-30','{"id": "2026-11-30-emocje", "day": "2026-11-30", "weekday": null, "option": 4, "title": "Niespodzianka!", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Nazywa radość i zaskoczenie.", "materials": "pudełko owinięte papierem, w środku pluszak", "steps": ["Pokaż zapakowane pudełko.", "Pytamy: co tam jest?", "Rozpakowujemy razem.", "Robimy minę „och!” – zaskoczenie.", "Potem uśmiech – radość."], "easier": "Dziecko zrywa papier z opiekunką.", "harder": "Dziecko nazywa uczucie: „cieszę się”.", "variant_1y": "Dziecko zrywa papier z opiekunką.", "variant_2_3y": "Dziecko nazywa uczucie: „cieszę się”.", "song": "Co w pudełku? Szur, szur, szur, / rozpakowuję – papier w górę! / Och! – zdziwienie, ach! – radość, / niespodzianka to jest słodkość!", "song_author": "własna (KMK/Malachim)", "safety": "Papier zbieramy od razu (nie do buzi); bez wstążek i taśmy klejącej w zasięgu.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('401d5c1a-b26b-549b-ada0-0401571bf5d1','Zmysły','Co jest w worku Mikołaja?',false,false,'2026-11-30','{"id": "2026-11-30-zmysly", "day": "2026-11-30", "weekday": null, "option": 5, "title": "Co jest w worku Mikołaja?", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozpoznaje przedmioty dotykiem.", "materials": "czerwony worek, duże przedmioty: piłka, miś, kubek, klocek", "steps": ["Pokaż worek.", "Dziecko wkłada rękę.", "Dotyka i zgaduje.", "Wyciąga – sprawdzamy.", "Następne dziecko."], "easier": "Dziecko wyciąga i nazywamy razem.", "harder": "Dziecko zgaduje przed wyciągnięciem.", "variant_1y": "Dziecko wyciąga i nazywamy razem.", "variant_2_3y": "Dziecko zgaduje przed wyciągnięciem.", "song": "Worek Mikołaja – co tam jest? / Okrągłe? Miękkie? Zgadnij, hej! / Wyciągnij rączką – raz, dwa, trzy – / to piłka! Zgadłeś ty!", "song_author": "własna (KMK/Malachim)", "safety": "Przedmioty duże; worek bez sznurka ściągającego.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d360f805-6688-516a-814e-8870ed958291','Zwierzęta','Renifer i jego rogi',false,false,'2026-11-30','{"id": "2026-11-30-zwierzeta", "day": "2026-11-30", "weekday": null, "option": 6, "title": "Renifer i jego rogi", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje renifera i porównuje z innymi zwierzętami.", "materials": "zdjęcie renifera, jelenia, konia", "steps": ["Pokaż renifera – ma rogi.", "Robimy rogi z dłoni.", "Pokaż konia – nie ma rogów.", "Renifer ciągnie sanie – idziemy w parach.", "Renifer je mech – „mniam”."], "easier": "Dziecko pokazuje rogi z pomocą.", "harder": "Dziecko odróżnia renifera od konia.", "variant_1y": "Dziecko pokazuje rogi z pomocą.", "variant_2_3y": "Dziecko odróżnia renifera od konia.", "song": "Renifer ma rogi jak gałązki, / ciągnie sanie przez śnieg gładki. / Tup, tup, kopytka stukają – / do dzieci prezenty pędzą!", "song_author": "własna (KMK/Malachim)", "safety": "Chodzenie w parach powoli.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('9c6acccb-2221-55d1-b57d-3c620274d1b7','Pogoda','Mróz maluje szyby',false,false,'2026-11-30','{"id": "2026-11-30-pogoda", "day": "2026-11-30", "weekday": null, "option": 7, "title": "Mróz maluje szyby", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Obserwuje zimno, parę z ust i szron.", "materials": "okno lub lusterko akrylowe", "steps": ["Chuchamy na zimną szybę lub lusterko.", "Patrzymy: zaparowało!", "Rysujemy palcem kółko.", "Mówimy: mróz to zimno.", "Na dworze patrzymy na parę z ust."], "easier": "Dziecko chucha razem z opiekunką.", "harder": "Dziecko rysuje kształt i mówi „zimno”.", "variant_1y": "Dziecko chucha razem z opiekunką.", "variant_2_3y": "Dziecko rysuje kształt i mówi „zimno”.", "song": "Chuchu, chuchu – na szybę chuch, / biała mgiełka – to mrozu duch! / Palcem kółko narysuję – / mróz to zimno – ja to czuję!", "song_author": "własna (KMK/Malachim)", "safety": "Zamknięte okno; bez wspinania na parapet; lusterko nietłukące.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4a5c149c-a154-5e8a-b884-d11e18181752','Przyroda','Gałązka świerku pachnie',false,false,'2026-11-30','{"id": "2026-11-30-przyroda", "day": "2026-11-30", "weekday": null, "option": 8, "title": "Gałązka świerku pachnie", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Poznaje drzewo iglaste węchem i dotykiem.", "materials": "gałązka świerku lub jodły (umyta)", "steps": ["Pokaż gałązkę.", "Wąchamy – pachnie lasem.", "Dotykamy delikatnie – kłuje!", "Porównujemy z liściem: liść gładki, igły kłują.", "Wkładamy gałązkę do wazonu (wysoko)."], "easier": "Dziecko wącha, gałązkę trzyma opiekunka.", "harder": "Dziecko porównuje igłę i liść.", "variant_1y": "Dziecko wącha, gałązkę trzyma opiekunka.", "variant_2_3y": "Dziecko porównuje igłę i liść.", "song": "Gałązka pachnie lasem, / igiełki kłują czasem. / Dotknij lekko – kłu, kłu, kłu – / zielona choinka już tu!", "song_author": "własna (KMK/Malachim)", "safety": "Gałązkę trzyma dorosły; igły opadają – sprzątamy, by nie trafiły do buzi; nie zostawiamy w zasięgu.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0d35bbbc-bd8b-5070-896b-402df67d93b6','Eksperymenty','Lodowe skarby',false,false,'2026-11-30','{"id": "2026-11-30-eksperymenty", "day": "2026-11-30", "weekday": null, "option": 9, "title": "Lodowe skarby", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje topnienie lodu.", "materials": "duży blok lodu (zamrożona woda w misce) z zamrożoną w środku dużą zabawką, taca, ciepła woda w kubku", "steps": ["Pokaż lodowy blok – zimny!", "Dotykamy krótko.", "Polewamy ciepłą wodą – lód topnieje.", "Zabawka wychodzi na wolność.", "Mówimy: ciepło topi lód."], "easier": "Dziecko dotyka i patrzy.", "harder": "Dziecko samo polewa ciepłą wodą (letnią).", "variant_1y": "Dziecko dotyka i patrzy.", "variant_2_3y": "Dziecko samo polewa ciepłą wodą (letnią).", "song": "Zimny lód – brr, brr, brr, / ciepła woda – kap, kap, kap! / Topi się lód, topi się – / zabawka wychodzi: hej!", "song_author": "własna (KMK/Malachim)", "safety": "Woda letnia, nie gorąca; lód tylko w dużym bloku – żadnych kostek do ust; krótki dotyk.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ed9845ba-2ed4-5a2c-bbc2-dddc3a0825e0','Plastyka','Czapka Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-plastyka", "day": "2026-11-30", "weekday": null, "option": 10, "title": "Czapka Mikołaja", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Wykonuje pracę z farbą i klejeniem.", "materials": "wycięty trójkąt z kartonu, czerwona farba, gąbka, wata/watolina w dużym kawałku, klej (u opiekunki)", "steps": ["Dziecko maluje trójkąt gąbką na czerwono.", "Opiekunka smaruje klejem dół i czubek.", "Dziecko przykłada pas watoliny.", "Na czubek – pompon z watoliny.", "Wieszamy czapki w sali."], "easier": "Dziecko maluje, opiekunka przykleja.", "harder": "Dziecko przykleja samo.", "variant_1y": "Dziecko maluje, opiekunka przykleja.", "variant_2_3y": "Dziecko przykleja samo.", "song": "Czerwona czapka, biały pompon, / Mikołaj nosi ją na co dzień tam. / Maluję, kleję – raz i dwa – / czapkę Mikołaja każdy ma!", "song_author": "własna (KMK/Malachim)", "safety": "Watolina duża, przyklejona; klej u opiekunki; farba z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('280bc3c5-26b3-5953-8b5e-277403340fba','Samoobsługa','Buciki dla Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-samoobsluga", "day": "2026-11-30", "weekday": null, "option": 11, "title": "Buciki dla Mikołaja", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy zdejmowanie butów i odkładanie.", "materials": "buty dzieci, miękka szmatka", "steps": ["Mówimy: Mikołaj zostawia prezenty w bucikach.", "Dziecko zdejmuje but.", "Przeciera go szmatką.", "Stawia na wyznaczonym miejscu.", "Zakłada kapcie."], "easier": "Opiekunka odpina rzep, dziecko zsuwa but.", "harder": "Dziecko samo zdejmuje i zakłada kapcie.", "variant_1y": "Opiekunka odpina rzep, dziecko zsuwa but.", "variant_2_3y": "Dziecko samo zdejmuje i zakłada kapcie.", "song": "Bucik zdejmę – raz i dwa, / czyściutki bucik – Mikołaj zna! / Postawię go w rządku, / i czekam na prezent – w porządku!", "song_author": "własna (KMK/Malachim)", "safety": "Szmatka sucha, bez środków czyszczących.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a14743d9-97c8-5971-ba26-d95cda0fe220','Język/logorytmika','Ho, ho, ho!',false,false,'2026-11-30','{"id": "2026-11-30-jezyk-logorytmika", "day": "2026-11-30", "weekday": null, "option": 12, "title": "Ho, ho, ho!", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy głoski h, dz i oddech.", "materials": "czapka Mikołaja dla opiekunki", "steps": ["Opiekunka-Mikołaj mówi głęboko: ho, ho, ho.", "Dzieci powtarzają.", "Dzwonki: dzyń, dzyń.", "Renifer: kląskanie.", "Mówimy w rytmie marszu."], "easier": "Dziecko powtarza „ho”.", "harder": "Dziecko łączy 3 dźwięki w rytmie.", "variant_1y": "Dziecko powtarza „ho”.", "variant_2_3y": "Dziecko łączy 3 dźwięki w rytmie.", "song": "Ho, ho, ho – Mikołaj woła, / dzyń, dzyń, dzyń – dzwoni sanie wkoła, / kla, kla, kla – renifer biegnie, / a my śpiewamy pięknie!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a7a69484-5459-5701-9c66-e70abea21238','Zabawy paluszkowe i masażyki','Pięć skrzatów Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-zabawy-paluszkowe-i-masazyki", "day": "2026-11-30", "weekday": null, "option": 13, "title": "Pięć skrzatów Mikołaja", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Rozwija palce i liczenie do 5.", "materials": "brak", "steps": ["Pokaż dłoń: 5 skrzatów.", "Każdy palec robi coś innego.", "Dotykamy palców po kolei.", "Na koniec skrzaty „jadą” po ręce.", "Zaciskamy piąstkę – „worek”."], "easier": "Opiekunka dotyka palców dziecka.", "harder": "Dziecko pokazuje i liczy palce.", "variant_1y": "Opiekunka dotyka palców dziecka.", "variant_2_3y": "Dziecko pokazuje i liczy palce.", "song": "Ten skrzat pakuje, ten skrzat klei, / ten wiąże kokardy, ten paczki ma swojej, / a ten najmniejszy – hop do sań, / i jadą do dzieci – tam, tam!", "song_author": "własna (KMK/Malachim)", "safety": "Delikatnie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5be1549a-40c4-5db3-9bf8-dd3c63e20355','Zabawy słowno-ruchowe i rymowanki','Mikołaj schodzi przez komin',false,false,'2026-11-30','{"id": "2026-11-30-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-11-30", "weekday": null, "option": 14, "title": "Mikołaj schodzi przez komin", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Wykonuje ruchy w górę i w dół.", "materials": "brak", "steps": ["Stajemy.", "Mikołaj na dachu – stajemy na palcach.", "Schodzi kominem – kucamy powoli.", "Kładzie prezent – kładziemy dłonie na podłodze.", "Wraca – wstajemy i machamy."], "easier": "Kucanie z pomocą.", "harder": "Dziecko mówi z opiekunką.", "variant_1y": "Kucanie z pomocą.", "variant_2_3y": "Dziecko mówi z opiekunką.", "song": "Mikołaj na dachu – wysoko, wysoko, / komin wąski – nisko, głęboko! / Kładzie prezent – cichutko, cii, / i do sań wraca – pa, pa, wy!", "song_author": "własna (KMK/Malachim)", "safety": "Powolne kucanie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('28828296-2c2d-5b39-83d0-fd4852b2231b','Powitania i integracja','Dzwoneczek wita',false,false,'2026-11-30','{"id": "2026-11-30-powitania-i-integracja", "day": "2026-11-30", "weekday": null, "option": 15, "title": "Dzwoneczek wita", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Wita się w grupie i słucha imion.", "materials": "jeden duży dzwonek z atestem (u opiekunki)", "steps": ["Siadamy w kole.", "Opiekunka dzwoni przy dziecku i śpiewa imię.", "Dziecko odpowiada „jestem!” lub macha.", "Kolejne dzieci.", "Na koniec wszyscy „dzyń!”."], "easier": "Dziecko macha.", "harder": "Dziecko mówi „jestem” i dzwoni samo.", "variant_1y": "Dziecko macha.", "variant_2_3y": "Dziecko mówi „jestem” i dzwoni samo.", "song": "Dzyń, dzyń, dzwoneczek, / kto przyszedł dziś, kto jest? / (imię) – jesteś? Pomachaj nam – / dzień dobry, dzień dobry – dzyń, dzyń, bam!", "song_author": "własna (KMK/Malachim)", "safety": "Dzwonek duży, z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7843ebe9-fd55-5b53-a903-e9e1e5539dd0','Świadomość ciała','Mikołaj ma brodę i brzuch',false,false,'2026-11-30','{"id": "2026-11-30-swiadomosc-ciala", "day": "2026-11-30", "weekday": null, "option": 16, "title": "Mikołaj ma brodę i brzuch", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Nazywa części ciała w zabawie.", "materials": "obrazek Mikołaja", "steps": ["Pokaż obrazek.", "Gdzie broda Mikołaja? A twoja broda?", "Duży brzuch – my klepiemy brzuszek.", "Czapka – głowa.", "Buty – stopy."], "easier": "Dziecko pokazuje z pomocą.", "harder": "Dziecko nazywa części.", "variant_1y": "Dziecko pokazuje z pomocą.", "variant_2_3y": "Dziecko nazywa części.", "song": "Mikołaj ma brodę – a ja mam bródkę, / Mikołaj ma brzuch – a ja mam brzuszek, / Mikołaj ma czapkę na głowie – / a ja? Głowa jest moja – każdy powie!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ea2ec1c3-881c-5d06-8fc1-7f0330ee7237','Pamięć/uwaga/naśladowanie','W której paczce jest miś?',false,false,'2026-11-30','{"id": "2026-11-30-pamiec-uwaga-nasladowanie", "day": "2026-11-30", "weekday": null, "option": 17, "title": "W której paczce jest miś?", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy uwagę i pamięć.", "materials": "3 pudełka różnego koloru, mały pluszak (większy niż rolka)", "steps": ["Chowamy misia do pudełka.", "Zamykamy.", "Pytamy: w którym?", "Dziecko otwiera.", "Zamiana ról."], "easier": "2 pudełka.", "harder": "3 pudełka, przestawiane.", "variant_1y": "2 pudełka.", "variant_2_3y": "3 pudełka, przestawiane.", "song": "Paczka czerwona, zielona, niebieska, / w której miś? Patrz, gdzie ścieżka! / Otwórz, zajrzyj – tu? A tu? / Mamy misia – hop i już!", "song_author": "własna (KMK/Malachim)", "safety": "Pudełka bez zszywek.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4c70638c-8f3d-5443-9a36-f0b36a8abb6b','Zabawy poznawcze','Co się zmieści w paczce?',false,false,'2026-11-30','{"id": "2026-11-30-zabawy-poznawcze", "day": "2026-11-30", "weekday": null, "option": 18, "title": "Co się zmieści w paczce?", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Poznaje pojęcia: zmieści się – nie zmieści się.", "materials": "pudełka różnej wielkości, piłka, miś, klocek", "steps": ["Bierzemy małe pudełko i dużego misia.", "Próbujemy włożyć – nie wchodzi!", "Bierzemy większe – wchodzi.", "Wkładamy pudełko w pudełko.", "Pakujemy prezenty."], "easier": "Wkładanie do dużego pudła.", "harder": "Dziecko dobiera pudełko do przedmiotu.", "variant_1y": "Wkładanie do dużego pudła.", "variant_2_3y": "Dziecko dobiera pudełko do przedmiotu.", "song": "Wchodzi? Nie wchodzi! Za duży miś! / Weź większe pudło – pasuje dziś! / Pudełko w pudełku, paczka w paczce – / prezenty gotowe na Mikołajki!", "song_author": "własna (KMK/Malachim)", "safety": "Pudełka kartonowe bez zszywek.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2a936a20-1c6e-5223-8c8a-fde0505aae90','Zabawy na dworze','Sanie Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-zabawy-na-dworze", "day": "2026-11-30", "weekday": null, "option": 19, "title": "Sanie Mikołaja", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Ciągnie ładunek, współpracuje.", "materials": "sanki lub karton z uchwytem (gruby sznur krótki), pluszaki", "steps": ["Ładujemy pluszaki na sanki.", "Dzieci w parach ciągną.", "Jedziemy do „domku” (ławka).", "Rozdajemy pluszaki.", "Wracamy pustymi saniami."], "easier": "Dziecko ciągnie z opiekunką.", "harder": "Dziecko ciągnie samo i rozdaje.", "variant_1y": "Dziecko ciągnie z opiekunką.", "variant_2_3y": "Dziecko ciągnie samo i rozdaje.", "song": "Ciągnij, ciągnij, saneczki, / wiozą paczki dla dzieci! / Raz i dwa – do ławki już, / prezent tu i prezent tu!", "song_author": "własna (KMK/Malachim)", "safety": "Sznurek krótki, ciągniemy tylko w ręku; nie owijamy wokół rąk ani szyi; dzieci nie siedzą na sankach ciągniętych przez dzieci.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d11ffb6c-11c3-50f0-9b87-66e4f9c16b55','Higiena','Ząbki dla Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-higiena", "day": "2026-11-30", "weekday": null, "option": 20, "title": "Ząbki dla Mikołaja", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Utrwala mycie zębów.", "materials": "szczoteczki dzieci, duży model zębów lub miś ze szczoteczką", "steps": ["Mikołaj lubi czyste ząbki!", "Myjemy ząbki misiowi szczoteczką.", "Pokazujemy ruchy: góra – dół, kółka.", "Dzieci myją swoje (w łazience).", "Uśmiech do lusterka."], "easier": "Opiekunka myje, dziecko trzyma szczoteczkę.", "harder": "Dziecko myje samo, opiekunka poprawia.", "variant_1y": "Opiekunka myje, dziecko trzyma szczoteczkę.", "variant_2_3y": "Dziecko myje samo, opiekunka poprawia.", "song": "Szczoteczka idzie: góra – dół, / kółko, kółko – myj na pół! / Ząbki czyste, buzia lśni – / Mikołaj uśmiecha się do mnie i ty!", "song_author": "własna (KMK/Malachim)", "safety": "Nie chodzimy ze szczoteczką w buzi; pasta z fluorem w ilości ziarenka ryżu.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0481a6c4-5d01-5163-b78a-1324e6868d8e','Czytanie dziecku','Mikołaj zgubił dzwoneczek (opowiadanie)',false,false,'2026-11-30','{"id": "2026-11-30-czytanie-dziecku", "day": "2026-11-30", "weekday": null, "option": 21, "title": "Mikołaj zgubił dzwoneczek (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii i uczestniczy w niej.", "materials": "obrazki: Mikołaj, renifer, dzwonek, zając; dzwonek z atestem", "steps": ["Opowiadaj: „Mikołaj zgubił dzwonek z sań. Zając go szukał w śniegu, wiewiórka na drzewie. A dzwonek dzwonił: dzyń! – i renifer go znalazł”.", "Pokazuj obrazki.", "Na „dzyń” dzieci dzwonią w powietrzu.", "Pytamy: kto znalazł?", "Dzwonimy „dziękuję”."], "easier": "Dziecko słucha i patrzy.", "harder": "Dziecko odpowiada na pytania.", "variant_1y": "Dziecko słucha i patrzy.", "variant_2_3y": "Dziecko odpowiada na pytania.", "song": "Mikołaju, dzwonek gdzie? / Zając szuka – nie ma, nie! / Dzyń, dzyń – słychać tam! / Renifer znalazł – dziękujemy wam!", "song_author": "własna (KMK/Malachim)", "safety": "Dzwonek u opiekunki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('cf7bf379-bb71-52e3-8b38-e5a7554178d2','Klocki/budowanie','Komin dla Mikołaja',false,false,'2026-11-30','{"id": "2026-11-30-klocki-budowanie", "day": "2026-11-30", "weekday": null, "option": 22, "title": "Komin dla Mikołaja", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje wysoką budowlę.", "materials": "duże klocki (kartonowe „cegły”)", "steps": ["Budujemy dom z klocków.", "Na dachu stawiamy komin.", "Mikołaj (figurka duża) schodzi kominem.", "Burzymy i budujemy znowu.", "Liczymy klocki."], "easier": "Dziecko stawia 2 klocki.", "harder": "Dziecko buduje dom z kominem.", "variant_1y": "Dziecko stawia 2 klocki.", "variant_2_3y": "Dziecko buduje dom z kominem.", "song": "Cegła, cegła, komin rośnie, / Mikołaj zejdzie nim radośnie! / Bęc – komin spadł? Nie szkodzi nic, / budujemy znowu – hyc!", "song_author": "własna (KMK/Malachim)", "safety": "Klocki lekkie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6e9817f8-d76f-5b57-99f7-22be6d1ca90c','Wyciszenie','Mikołaj śpi w saniach',false,false,'2026-11-30','{"id": "2026-11-30-wyciszenie", "day": "2026-11-30", "weekday": null, "option": 23, "title": "Mikołaj śpi w saniach", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza po świętowaniu.", "materials": "koc, spokojna muzyka", "steps": ["Mikołaj zmęczony – kładzie się w saniach (na kocu).", "Dzieci kładą się obok.", "Oddychamy wolno.", "Opiekunka cicho dzwoni (lub nuci).", "Leżymy w ciszy."], "easier": "Dziecko leży przy opiekunce.", "harder": "Dziecko samo leży cicho.", "variant_1y": "Dziecko leży przy opiekunce.", "variant_2_3y": "Dziecko samo leży cicho.", "song": "Cichutko, cichutko, Mikołaj śpi, / renifery też śpią, i my. / Dzyń… dzyń… coraz ciszej, / śnieżek pada, nikt nie słyszy.", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5b48afec-43cf-559d-bfd6-d0d1c930f7b2','Empatia','Prezent dla kolegi',false,false,'2026-11-30','{"id": "2026-11-30-empatia", "day": "2026-11-30", "weekday": null, "option": 24, "title": "Prezent dla kolegi", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy dawania i radości innych.", "materials": "kartki, kredki jumbo, koperty duże", "steps": ["Każde dziecko rysuje „prezent” dla kolegi.", "Wkładamy do koperty.", "Losujemy, komu dajemy.", "Dziecko daje i mówi „proszę”.", "Kolega mówi „dziękuję” i cieszy się."], "easier": "Opiekunka pomaga dać rysunek.", "harder": "Dziecko samo wybiera, komu daje.", "variant_1y": "Opiekunka pomaga dać rysunek.", "variant_2_3y": "Dziecko samo wybiera, komu daje.", "song": "Mam prezent – nie dla mnie, / dla ciebie, kolego, właśnie! / Proszę bardzo – dziękuję – / razem radość czujemy!", "song_author": "własna (KMK/Malachim)", "safety": "Koperty bez zszywek.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f446aae2-6634-558e-98e3-05ee0f638687','Rodzina i dom','Kto w domu czeka na Mikołaja?',false,false,'2026-11-30','{"id": "2026-11-30-rodzina-i-dom", "day": "2026-11-30", "weekday": null, "option": 25, "title": "Kto w domu czeka na Mikołaja?", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Opowiada o domowych zwyczajach.", "materials": "zdjęcia rodzin, obrazek buta i choinki", "steps": ["Pytamy: kto u ciebie w domu czeka na Mikołaja?", "Pokazujemy zdjęcia rodzin.", "Gdzie stawiasz but – przy oknie? pod łóżkiem?", "Kto się cieszy najbardziej?", "Rysujemy razem uśmiech dla rodziny."], "easier": "Dziecko pokazuje rodzinę na zdjęciu.", "harder": "Dziecko opowiada o swoim zwyczaju.", "variant_1y": "Dziecko pokazuje rodzinę na zdjęciu.", "variant_2_3y": "Dziecko opowiada o swoim zwyczaju.", "song": "W moim domu – mama, tata, / brat i siostra, babcia, dziadek. / Wszyscy czekamy, cicho, sza – / Mikołaj przyjdzie i do mnie, i do was!", "song_author": "własna (KMK/Malachim)", "safety": "Uważaj: nie każde dziecko obchodzi Mikołajki – mówimy o różnych zwyczajach bez oceny.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fd2b7c46-c2c0-5e7c-a0cd-8097ca0880f3','Pory roku i święta','Mikołajki w żłobku',false,false,'2026-11-30','{"id": "2026-11-30-pory-roku-i-swieta", "day": "2026-11-30", "weekday": null, "option": 26, "title": "Mikołajki w żłobku", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Przeżywa święto w grupie.", "materials": "worek, małe pakunki (np. kartki, naklejki duże – nie do buzi), czapka Mikołaja", "steps": ["Słychać dzwonek – ktoś przyszedł!", "Opiekunka w czapce Mikołaja (lub worek „zostawiony”).", "Śpiewamy naszą piosenkę.", "Każde dziecko dostaje paczuszkę.", "Mówimy „dziękuję, Mikołaju”."], "easier": "Dziecko na kolanach opiekunki – część dzieci boi się przebranych osób.", "harder": "Dziecko mówi „dziękuję”.", "variant_1y": "Dziecko na kolanach opiekunki – część dzieci boi się przebranych osób.", "variant_2_3y": "Dziecko mówi „dziękuję”.", "song": "Dzyń, dzyń, kto tam puka? / To Mikołaj dzieci szuka! / Worek pełny, broda biała – / dziękujemy – grupa cała!", "song_author": "własna (KMK/Malachim)", "safety": "Prezenty bezpieczne 0–3 (bez drobnych części, bez słodyczy z orzechami); osoba przebrana nie zbliża się do dziecka, które się boi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3468a1b8-3273-5829-a6ad-4a1ca42abacd','Kolory/kształty/wielkości','Czerwone i zielone paczki',false,false,'2026-11-30','{"id": "2026-11-30-kolory-ksztalty-wielkosci", "day": "2026-11-30", "weekday": null, "option": 27, "title": "Czerwone i zielone paczki", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Sortuje wg koloru i wielkości.", "materials": "pudełka owinięte czerwonym i zielonym papierem, duże i małe", "steps": ["Rozkładamy paczki.", "Szukamy czerwonych.", "Szukamy zielonych.", "Duże do worka, małe do koszyka.", "Liczymy razem."], "easier": "Dziecko wybiera 1 kolor.", "harder": "Dziecko sortuje wg 2 cech.", "variant_1y": "Dziecko wybiera 1 kolor.", "variant_2_3y": "Dziecko sortuje wg 2 cech.", "song": "Czerwona paczka – tutaj, / zielona paczka – tam! / Duża do worka, mała do koszyka – / Mikołaj pakuje i nic nie znika!", "song_author": "własna (KMK/Malachim)", "safety": "Papier dobrze przyklejony, bez wstążek.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Mikołaj idzie!", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('30908ba7-79eb-5d4a-9f31-fb72467e6b43','Ruch','Płatki śniegu tańczą',false,false,'2026-12-07','{"id": "2026-12-07-ruch", "day": "2026-12-07", "weekday": null, "option": 1, "title": "Płatki śniegu tańczą", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy wirowanie, opadanie i równowagę.", "materials": "białe chusty", "steps": ["Każde dziecko dostaje białą chustę – płatek.", "Płatki lecą: chodzimy na palcach, machamy chustą.", "Wiatr – kręcimy się powoli raz.", "Płatki opadają – kucamy i kładziemy chustę na ziemi."], "easier": "Dziecko „leci” na rękach opiekunki.", "harder": "Dziecko kręci się raz i kuca na sygnał.", "variant_1y": "Dziecko „leci” na rękach opiekunki.", "variant_2_3y": "Dziecko kręci się raz i kuca na sygnał.", "song": "Leci płatek, leci, kręci, / tańczy w górze, tańczy w dół. / Wiatr zawieje – hop, obrót, / cicho leży śnieżny stół.", "song_author": "własna (KMK/Malachim)", "safety": "Tylko 1 obrót (zawroty głowy); chusty krótkie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('82edf348-e7a6-5a65-a7bd-d65b3a716953','Muzyka','Skrzypi śnieg',false,false,'2026-12-07','{"id": "2026-12-07-muzyka", "day": "2026-12-07", "weekday": null, "option": 2, "title": "Skrzypi śnieg", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Rozwija słuch i rytm przez dźwięki zimy.", "materials": "worek strunowy z mąką ziemniaczaną zaklejony taśmą (skrzypi jak śnieg), bębenek", "steps": ["Ściskamy worek – skrzyp, skrzyp jak śnieg.", "Idziemy do rytmu bębenka: skrzyp, skrzyp.", "Szybko – biegniemy po śniegu, wolno – brniemy.", "Cisza – zamarzamy jak sopel."], "easier": "Dziecko ściska worek z opiekunką.", "harder": "Dziecko zmienia tempo na sygnał.", "variant_1y": "Dziecko ściska worek z opiekunką.", "variant_2_3y": "Dziecko zmienia tempo na sygnał.", "song": "Skrzyp, skrzyp – idę ja, / śnieg pod butem śpiewa: ha! / Szybko, wolno, raz i dwa – / sopel stoi – stop, i ja!", "song_author": "własna (KMK/Malachim)", "safety": "Worek podwójny, zaklejony; sprawdzaj szczelność (pył nie do oczu/buzi).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('aca9643c-9ef2-5ebf-b614-9ed0a780b9c4','Sensoryka','Śnieg na tacy',false,false,'2026-12-07','{"id": "2026-12-07-sensoryka", "day": "2026-12-07", "weekday": null, "option": 3, "title": "Śnieg na tacy", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Poznaje śnieg dotykiem: zimny, mokry, topnieje.", "materials": "śnieg w dużej tacy (lub sztuczny: odżywka + soda – tylko dla 2–3 l.), rękawiczki, łopatki duże", "steps": ["Przynosimy śnieg na tacy do sali.", "Dotykamy w rękawiczkach, potem krótko gołą ręką.", "Robimy kulkę, odcisk dłoni.", "Obserwujemy, jak topnieje; wycieramy ręce."], "easier": "Dotyk w rękawiczce, krótko.", "harder": "Lepienie kulki i odcisków.", "variant_1y": "Dotyk w rękawiczce, krótko.", "variant_2_3y": "Lepienie kulki i odcisków.", "song": "Biały śnieg, zimny śnieg, / ręka mówi: brr, brr, hej! / Ugniatam kulkę – raz i dwa, / w cieple znika – woda ma!", "song_author": "własna (KMK/Malachim)", "safety": "Nie jemy śniegu; krótki kontakt gołą skórą; sztuczny śnieg nie dla 1-latków (do buzi).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6780fb0c-5cc4-558c-9a0d-6c01408a7d81','Emocje','Bałwanek smutny i wesoły',false,false,'2026-12-07','{"id": "2026-12-07-emocje", "day": "2026-12-07", "weekday": null, "option": 4, "title": "Bałwanek smutny i wesoły", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Rozpoznaje emocje i ich przyczynę.", "materials": "2 duże obrazki bałwanka: smutny i wesoły", "steps": ["Bałwanek smutny – świeci słońce, topnieje.", "Bałwanek wesoły – pada śnieg.", "Dzieci robią miny bałwanka.", "Pytamy: co cię cieszy zimą?"], "easier": "Dziecko naśladuje minę.", "harder": "Dziecko mówi, dlaczego bałwanek jest smutny.", "variant_1y": "Dziecko naśladuje minę.", "variant_2_3y": "Dziecko mówi, dlaczego bałwanek jest smutny.", "song": "Bałwanek płacze – słonko grzeje, / bałwanek się śmieje – śnieg z nieba leje! / Pokaż minę – smutno, wesoło – / bawimy się z bałwankiem w koło!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a262222a-f719-5cd7-a386-7831e5bb1759','Zmysły','Ciepłe – zimne',false,false,'2026-12-07','{"id": "2026-12-07-zmysly", "day": "2026-12-07", "weekday": null, "option": 5, "title": "Ciepłe – zimne", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozróżnia temperatury.", "materials": "termofor z letnią wodą w pokrowcu, chłodny metalowy kubek, rękawiczka", "steps": ["Dotykamy termoforu – ciepło.", "Kubka z lodówki – zimno.", "Rękawiczki – ciepła, chroni.", "Sortujemy obrazki: zima – zimno, kocyk – ciepło."], "easier": "Dziecko dotyka z opiekunką.", "harder": "Dziecko sortuje obrazki.", "variant_1y": "Dziecko dotyka z opiekunką.", "variant_2_3y": "Dziecko sortuje obrazki.", "song": "Ciepło, ciepło – jak w kocyku, / zimno, zimno – jak w śniegu! / Dotknij rączką, powiedz mi: / ciepło czy zimno – brr czy mmm?", "song_author": "własna (KMK/Malachim)", "safety": "Termofor letni (nie gorący), w pokrowcu; sprawdź dłonią dorosłego.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f07b42c5-f719-5566-87d9-3517708b5a19','Zwierzęta','Kto śpi zimą?',false,false,'2026-12-07','{"id": "2026-12-07-zwierzeta", "day": "2026-12-07", "weekday": null, "option": 6, "title": "Kto śpi zimą?", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje zwierzęta zimujące.", "materials": "obrazki: jeż, niedźwiedź, wiewiórka, sikorka", "steps": ["Jeż i niedźwiedź śpią – zwijamy się w kulkę.", "Wiewiórka szuka orzechów – skaczemy.", "Sikorka lata – machamy.", "Opiekunka pokazuje obrazek, dzieci ruch."], "easier": "Dziecko naśladuje 1–2 zwierzęta.", "harder": "Dziecko mówi, kto śpi zimą.", "variant_1y": "Dziecko naśladuje 1–2 zwierzęta.", "variant_2_3y": "Dziecko mówi, kto śpi zimą.", "song": "Jeż śpi w liściach – cicho, sza, / miś w gawrze – chrapie: chrrr. / Wiewiórka skacze – hop, hop, hop, / sikorka lata – fru i stop!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a73a1da0-f1a0-54bb-947e-cf0e6ffaaf92','Pogoda','Pada śnieg!',false,false,'2026-12-07','{"id": "2026-12-07-pogoda", "day": "2026-12-07", "weekday": null, "option": 7, "title": "Pada śnieg!", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Obserwuje opady śniegu i nazywa pogodę.", "materials": "okno, obrazki pogody, papierowe płatki (duże)", "steps": ["Patrzymy przez okno: pada śnieg? jest biało?", "Wybieramy obrazek pogody dnia.", "Opiekunka sypie z góry duże papierowe płatki.", "Dzieci łapią płatki."], "easier": "Dziecko łapie płatki.", "harder": "Dziecko mówi „pada śnieg”.", "variant_1y": "Dziecko łapie płatki.", "variant_2_3y": "Dziecko mówi „pada śnieg”.", "song": "Pada, pada białe nic, / na dachu, na drzewie – wszędzie śnieg! / Łap płatek – hop, w rączkę – / zimowe dzieci na zimowej łączce!", "song_author": "własna (KMK/Malachim)", "safety": "Płatki duże, sprzątamy po zabawie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('29545697-120c-5ca2-8a17-f7d368363d70','Przyroda','Drzewo zimą',false,false,'2026-12-07','{"id": "2026-12-07-przyroda", "day": "2026-12-07", "weekday": null, "option": 8, "title": "Drzewo zimą", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Obserwuje drzewa bez liści i ze śniegiem.", "materials": "ciepłe ubranie", "steps": ["Wychodzimy do drzewa.", "Patrzymy: gdzie liście? Nie ma!", "Delikatnie strząsamy śnieg z niskiej gałązki.", "Porównujemy: świerk ma igły zimą."], "easier": "Dziecko patrzy z wózka lub na rękach.", "harder": "Dziecko porównuje dwa drzewa.", "variant_1y": "Dziecko patrzy z wózka lub na rękach.", "variant_2_3y": "Dziecko porównuje dwa drzewa.", "song": "Drzewko gołe, drzewko śpi, / śnieżna czapka na nim lśni. / Świerk zielony – igły ma, / zima drzewom: lu, li, la!", "song_author": "własna (KMK/Malachim)", "safety": "Nie stoimy pod gałęziami z dużą ilością śniegu; uważaj na sople – omijamy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d77d3691-0640-5d1f-a0d8-35ade1f7b9af','Eksperymenty','Woda zamienia się w lód',false,false,'2026-12-07','{"id": "2026-12-07-eksperymenty", "day": "2026-12-07", "weekday": null, "option": 9, "title": "Woda zamienia się w lód", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje zamarzanie i topnienie.", "materials": "foremka z wodą wystawiona dzień wcześniej na mróz lub do zamrażarki", "steps": ["Pokazujemy foremkę z wodą wczoraj.", "Dziś – lód! Twardy.", "Stawiamy na kaloryferze na tacy.", "Sprawdzamy po zajęciach – woda!"], "easier": "Dziecko dotyka lodu krótko.", "harder": "Dziecko mówi, co się stało.", "variant_1y": "Dziecko dotyka lodu krótko.", "variant_2_3y": "Dziecko mówi, co się stało.", "song": "Woda chlup – na mróz ją dam, / rano lód – stuk, twardy sam! / Ciepło przyjdzie – kap, kap, kap, / lód znów wodą – tak to tak!", "song_author": "własna (KMK/Malachim)", "safety": "Lód duży, nie do buzi; taca pod lodem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fee0b810-f951-5b3b-a092-3e045f0d17a0','Plastyka','Gwiazdki na granatowym niebie',false,false,'2026-12-07','{"id": "2026-12-07-plastyka", "day": "2026-12-07", "weekday": null, "option": 10, "title": "Gwiazdki na granatowym niebie", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Stempluje i odbija kształty.", "materials": "granatowy karton, biała farba, stemple z gąbki w kształcie gwiazdki (duże)", "steps": ["Pokaż ciemne niebo.", "Dziecko stempluje białe gwiazdki.", "Palcem dodaje kropki – płatki.", "Suszymy i wieszamy."], "easier": "Stemplowanie z pomocą.", "harder": "Samodzielne stemplowanie i kropki.", "variant_1y": "Stemplowanie z pomocą.", "variant_2_3y": "Samodzielne stemplowanie i kropki.", "song": "Ciemne niebo, białe gwiazdki, / stuk, stuk – świecą jak latarki! / Kropka, kropka – płatek śniegu, / niebo pełne jest w zimowym biegu!", "song_author": "własna (KMK/Malachim)", "safety": "Farba z atestem; fartuch.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('54725e66-b87a-5355-9eae-f48c90b88e1b','Samoobsługa','Sam zakładam rękawiczki',false,false,'2026-12-07','{"id": "2026-12-07-samoobsluga", "day": "2026-12-07", "weekday": null, "option": 11, "title": "Sam zakładam rękawiczki", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy wkładanie dłoni do rękawiczki-jednopalczatki.", "materials": "rękawiczki jednopalczaste dzieci", "steps": ["Kładziemy rękawiczkę na stole, kciukiem do góry.", "Wsuwamy rączkę – kciuk do domku kciuka.", "Naciągamy drugą ręką.", "Klaszczemy w rękawiczkach."], "easier": "Opiekunka trzyma, dziecko wsuwa rączkę.", "harder": "Dziecko zakłada obie samo.", "variant_1y": "Opiekunka trzyma, dziecko wsuwa rączkę.", "variant_2_3y": "Dziecko zakłada obie samo.", "song": "Kciuk do swojego domku, / palce razem w środku. / Ciągnę, ciągnę – już jest! / Klap, klap – ciepło, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Rękawiczki na sznurku przez rękawy – NIE; tylko klipsy do rękawa lub bez.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('067f1fa6-b353-589d-9a44-977b6051aa1b','Język/logorytmika','Wiatr i zamieć',false,false,'2026-12-07','{"id": "2026-12-07-jezyk-logorytmika", "day": "2026-12-07", "weekday": null, "option": 12, "title": "Wiatr i zamieć", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy długi wydech i głoski szumiące.", "materials": "papierowe płatki śniegu na nitce (u opiekunki)", "steps": ["Wiatr słaby: fff – płatek się kołysze.", "Zamieć: szszsz – długo.", "Mróz: brrr – drżą wargi.", "Mówimy w kolejności i szybciej."], "easier": "Dziecko dmucha na płatek.", "harder": "Dziecko utrzymuje „szszsz” do 3.", "variant_1y": "Dziecko dmucha na płatek.", "variant_2_3y": "Dziecko utrzymuje „szszsz” do 3.", "song": "Fff – wiatr szepcze cicho, / szszsz – zamieć sypie lichą, / brrr – mróz szczypie nos – / zimowy mamy dziś głos!", "song_author": "własna (KMK/Malachim)", "safety": "Płatek na nitce trzyma opiekunka.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6aa20faa-c9f2-5815-b224-0706fca28342','Zabawy paluszkowe i masażyki','Śnieżek na plecach',false,false,'2026-12-07','{"id": "2026-12-07-zabawy-paluszkowe-i-masazyki", "day": "2026-12-07", "weekday": null, "option": 13, "title": "Śnieżek na plecach", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Masażyk wyciszający.", "materials": "brak", "steps": ["Pada śnieżek – stukamy palcami po plecach.", "Lepimy kulę – kółka dłonią.", "Toczymy kulę – dłoń w dół pleców.", "Bałwan gotowy – przytulamy."], "easier": "Lekko, na kolanach.", "harder": "Dziecko robi masażyk koledze.", "variant_1y": "Lekko, na kolanach.", "variant_2_3y": "Dziecko robi masażyk koledze.", "song": "Pada śnieżek – puk, puk, puk, / lepię kulę – kółko w krąg, / toczę, toczę – w dół, w dół, / bałwan stoi – przytul, cmok!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą dziecka.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('28e277a7-3452-566e-ab42-e5e3bd8faa05','Zabawy słowno-ruchowe i rymowanki','Lepimy bałwana',false,false,'2026-12-07','{"id": "2026-12-07-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-12-07", "weekday": null, "option": 14, "title": "Lepimy bałwana", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Wykonuje ruchy do słów.", "materials": "brak", "steps": ["Toczymy kulę – kręcimy rękami przed sobą.", "Duża kula – szerokie ręce.", "Mała głowa – małe kółko.", "Nos-marchewka – palec do nosa.", "Bałwan stoi – nieruchomo!"], "easier": "Dziecko naśladuje.", "harder": "Dziecko mówi z opiekunką.", "variant_1y": "Dziecko naśladuje.", "variant_2_3y": "Dziecko mówi z opiekunką.", "song": "Toczę kulę, toczę wielką, / druga mniejsza, trzecia – główka. / Nos marchewka, oczy dwa – / bałwan stoi – ha, ha, ha!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('371719e7-2424-5e84-80a3-1973a0f9c70b','Powitania i integracja','Śnieżna kula wędruje',false,false,'2026-12-07','{"id": "2026-12-07-powitania-i-integracja", "day": "2026-12-07", "weekday": null, "option": 15, "title": "Śnieżna kula wędruje", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Przekazuje przedmiot i wita się imieniem.", "materials": "duża miękka piłka biała", "steps": ["Siadamy w kole.", "Toczymy „śnieżkę” do dziecka.", "Mówimy: „Dzień dobry, (imię)!”.", "Dziecko toczy dalej."], "easier": "Opiekunka toczy z dzieckiem.", "harder": "Dziecko samo toczy i mówi imię.", "variant_1y": "Opiekunka toczy z dzieckiem.", "variant_2_3y": "Dziecko samo toczy i mówi imię.", "song": "Toczy się śnieżka, toczy po sali, / do kogo przyjdzie? Kto dziś nas wita? / (imię) – złap ją, przywitaj się, / i podaj dalej – hej, hej, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Piłka miękka, duża.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fbf154fd-0ff1-557c-baa8-207dbe1c4af6','Świadomość ciała','Co marznie zimą?',false,false,'2026-12-07','{"id": "2026-12-07-swiadomosc-ciala", "day": "2026-12-07", "weekday": null, "option": 16, "title": "Co marznie zimą?", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Nazywa części ciała, które chronimy.", "materials": "lalka, czapka, szalik, rękawiczki", "steps": ["Pytamy: co marznie? Uszy, nos, ręce, nogi.", "Pokazujemy na sobie.", "Ubieramy lalkę.", "Chuchamy w dłonie – ciepło."], "easier": "Pokazywanie na lalce.", "harder": "Nazywanie części i ubrań.", "variant_1y": "Pokazywanie na lalce.", "variant_2_3y": "Nazywanie części i ubrań.", "song": "Marzną uszy – czapka na nie, / marznie nosek – szalik dla niego, / marzną rączki – chuchu, chuchu, / ciepło w każdym paluszku!", "song_author": "własna (KMK/Malachim)", "safety": "Szalik tylko lalce.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b5ba0a3a-db82-537c-b162-4effd7d8c136','Pamięć/uwaga/naśladowanie','Zamrożone figury',false,false,'2026-12-07','{"id": "2026-12-07-pamiec-uwaga-nasladowanie", "day": "2026-12-07", "weekday": null, "option": 17, "title": "Zamrożone figury", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy kontrolę ruchu i uwagę.", "materials": "muzyka", "steps": ["Muzyka gra – tańczymy.", "Muzyka stop – „zamarzamy” jak sopel.", "Opiekunka „rozmraża” dotykiem.", "Powtarzamy."], "easier": "Dziecko zatrzymuje się z opiekunką.", "harder": "Dziecko stoi nieruchomo do 3.", "variant_1y": "Dziecko zatrzymuje się z opiekunką.", "variant_2_3y": "Dziecko stoi nieruchomo do 3.", "song": "Tańczę, tańczę, kiedy gra, / cisza – lód i stoję ja! / Dotknij mnie – i znów się ruszę, / bo mam ciepłą, dobrą duszę!", "song_author": "własna (KMK/Malachim)", "safety": "Taniec bez biegania.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0324fd8f-6a0d-5bc8-8ebb-3ea4c7da504f','Zabawy poznawcze','Duża i mała gwiazdka',false,false,'2026-12-07','{"id": "2026-12-07-zabawy-poznawcze", "day": "2026-12-07", "weekday": null, "option": 18, "title": "Duża i mała gwiazdka", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Porównuje i dopasowuje kształty.", "materials": "gwiazdki z kartonu: duże i małe, kontury na kartce", "steps": ["Pokaż kontury gwiazdek.", "Dziecko kładzie gwiazdkę na kontur.", "Duża na dużą, mała na małą.", "Liczymy razem."], "easier": "2 gwiazdki na kontur.", "harder": "4–6 gwiazdek.", "variant_1y": "2 gwiazdki na kontur.", "variant_2_3y": "4–6 gwiazdek.", "song": "Duża gwiazdka – tu jest dom, / mała gwiazdka – tu jej tron. / Połóż, połóż – pasuje? Tak! / Gwiazdki świecą – to jest znak!", "song_author": "własna (KMK/Malachim)", "safety": "Karton gruby.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('07d18957-4275-549e-9c64-7e78ec06a846','Zabawy na dworze','Ślady na śniegu',false,false,'2026-12-07','{"id": "2026-12-07-zabawy-na-dworze", "day": "2026-12-07", "weekday": null, "option": 19, "title": "Ślady na śniegu", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Bada ślady na śniegu.", "materials": "ciepłe ubranie, kalosze/śniegowce", "steps": ["Idziemy po świeżym śniegu.", "Patrzymy na swoje ślady.", "Robimy ślady małe (tip-top) i duże (tup).", "Szukamy śladów ptaków."], "easier": "Dziecko idzie za rękę.", "harder": "Dziecko porównuje ślady.", "variant_1y": "Dziecko idzie za rękę.", "variant_2_3y": "Dziecko porównuje ślady.", "song": "Tup, tup – mój ślad, / tip, tip – malutki brat! / Ptaszek też tu był – patrz, / ślady wszędzie – na śniegu – raz!", "song_author": "własna (KMK/Malachim)", "safety": "Nie jemy śniegu; krótko przy mrozie; sprawdzamy, czy dzieci nie mają mokrych rąk.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4b79235f-1762-5e56-9eb3-d6f6a48f0362','Higiena','Kremik na mróz',false,false,'2026-12-07','{"id": "2026-12-07-higiena", "day": "2026-12-07", "weekday": null, "option": 20, "title": "Kremik na mróz", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Uczy dbania o skórę zimą.", "materials": "krem ochronny na mróz (od rodziców, za zgodą)", "steps": ["Przed wyjściem pokazujemy krem.", "Opiekunka nakłada kropkę na policzek.", "Dziecko rozsmarowuje.", "Mówimy: krem chroni przed mrozem."], "easier": "Opiekunka smaruje, dziecko pokazuje.", "harder": "Dziecko rozsmarowuje samo.", "variant_1y": "Opiekunka smaruje, dziecko pokazuje.", "variant_2_3y": "Dziecko rozsmarowuje samo.", "song": "Kropka na nosek, kropka na policzek, / rozsmarowuję – mróz mi nie straszny! / Mróz nie szczypie, mróz nie gryzie – / buzia gładka, buzia blisko!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko krem dziecka od rodziców (alergie); nie do oczu.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('8156168c-c69f-55e2-9b09-6f895e49a5f8','Czytanie dziecku','Płatek, który szukał przyjaciela (opowiadanie)',false,false,'2026-12-07','{"id": "2026-12-07-czytanie-dziecku", "day": "2026-12-07", "weekday": null, "option": 21, "title": "Płatek, który szukał przyjaciela (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii o przyjaźni.", "materials": "duży papierowy płatek, obrazki: kot, drzewo, dziecko", "steps": ["Opowiadaj: „Płatek spadł na kota – kot otrząsnął się. Na drzewo – wiatr go zdmuchnął. Na rękawiczkę Zosi – Zosia powiedziała: będziesz moim przyjacielem”.", "Pokazuj obrazki.", "Dzieci mówią „fru!” gdy płatek leci.", "Pytamy: kto jest twoim przyjacielem?"], "easier": "Dziecko słucha z płatkiem w ręce.", "harder": "Dziecko odpowiada na pytania.", "variant_1y": "Dziecko słucha z płatkiem w ręce.", "variant_2_3y": "Dziecko odpowiada na pytania.", "song": "Leci płatek, szuka, gdzie, / kot go strząsnął – nie, nie, nie! / Na rękawiczce Zosi siadł – / masz przyjaciela – to jest skarb!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('46cdeede-5ba3-598b-b1f0-a75cd05cf3ab','Klocki/budowanie','Igloo z klocków',false,false,'2026-12-07','{"id": "2026-12-07-klocki-budowanie", "day": "2026-12-07", "weekday": null, "option": 22, "title": "Igloo z klocków", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje kształt okrągły.", "materials": "duże białe klocki lub kartony", "steps": ["Pokaż obrazek igloo.", "Układamy klocki w krąg.", "Budujemy wyżej.", "Wsadzamy do środka pluszowego pingwina."], "easier": "Dziecko kładzie klocki w krąg z pomocą.", "harder": "Dziecko buduje samo.", "variant_1y": "Dziecko kładzie klocki w krąg z pomocą.", "variant_2_3y": "Dziecko buduje samo.", "song": "Klocek biały, klocek w krąg, / igloo rośnie, rośnie wokół! / Pingwin wchodzi – ciepło mu, / dziękuje dzieciom: tu, tu, tu!", "song_author": "własna (KMK/Malachim)", "safety": "Klocki lekkie; niskie ściany.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('17efcb3e-fc6b-5f5d-a0bf-79cd403d947a','Wyciszenie','Śnieżna cisza',false,false,'2026-12-07','{"id": "2026-12-07-wyciszenie", "day": "2026-12-07", "weekday": null, "option": 23, "title": "Śnieżna cisza", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza przez ciszę i oddech.", "materials": "biała chusta, spokojna muzyka", "steps": ["Leżymy na kocu.", "Opiekunka powoli opuszcza białą chustę nad dziećmi – śnieg pada.", "Oddychamy wolno.", "Leżymy w ciszy jak śnieg."], "easier": "Dziecko przy opiekunce.", "harder": "Dziecko leży samo.", "variant_1y": "Dziecko przy opiekunce.", "variant_2_3y": "Dziecko leży samo.", "song": "Cicho pada śnieg na ziemię, / cicho śpi las, cicho drzemię. / Wdech i wydech – biało, sza, / zimowa cisza – ty i ja.", "song_author": "własna (KMK/Malachim)", "safety": "Chusta nie na twarz.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5c0fd926-3f2e-5ae0-8aa3-189f6c674d34','Empatia','Ptaszkowi zimno',false,false,'2026-12-07','{"id": "2026-12-07-empatia", "day": "2026-12-07", "weekday": null, "option": 24, "title": "Ptaszkowi zimno", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy troski o zwierzęta.", "materials": "obrazek ptaka, kocyk, pacynka ptaka", "steps": ["Pacynka-ptaszek drży.", "Pytamy: jak pomóc?", "Dzieci okrywają go kocykiem.", "Mówimy: dorośli sypią ziarno do karmnika."], "easier": "Dziecko głaszcze pacynkę.", "harder": "Dziecko mówi, jak pomóc.", "variant_1y": "Dziecko głaszcze pacynkę.", "variant_2_3y": "Dziecko mówi, jak pomóc.", "song": "Ptaszku, ptaszku, zimno ci? / Okryjemy cię – my, my! / Ziarnko w karmnik sypnie pani – / ptaszki będą nakarmione z nami!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5a408362-ab28-5c90-8ca0-66f902fde48d','Rodzina i dom','Zimą w moim domu',false,false,'2026-12-07','{"id": "2026-12-07-rodzina-i-dom", "day": "2026-12-07", "weekday": null, "option": 25, "title": "Zimą w moim domu", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Rozmawia o domowej zimie.", "materials": "obrazki: kaloryfer, herbata, koc, sanki", "steps": ["Pokaż obrazki.", "Pytamy: co robisz w domu, gdy zimno?", "Dzieci wskazują.", "Udajemy picie ciepłej herbatki (puste kubki)."], "easier": "Dziecko wskazuje obrazek.", "harder": "Dziecko opowiada o swoim domu.", "variant_1y": "Dziecko wskazuje obrazek.", "variant_2_3y": "Dziecko opowiada o swoim domu.", "song": "Za oknem mróz, a w domu ciepło, / mama herbatkę robi bez kłopotu. / Kocyk, sanki, tata, ja – / zima w domu – lu, li, la!", "song_author": "własna (KMK/Malachim)", "safety": "Puste plastikowe kubki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ac5590a7-212c-59c1-acac-2d40caa904be','Pory roku i święta','Witaj, zimo!',false,false,'2026-12-07','{"id": "2026-12-07-pory-roku-i-swieta", "day": "2026-12-07", "weekday": null, "option": 26, "title": "Witaj, zimo!", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Poznaje cechy zimy.", "materials": "obrazki pór roku, biała chusta", "steps": ["Pokazujemy obrazki: jesień, zima.", "Co jest zimą? śnieg, mróz, sanki.", "Wybieramy obrazki zimowe.", "Tańczymy z białą chustą."], "easier": "Dziecko wskazuje śnieg.", "harder": "Dziecko odróżnia zimę od jesieni.", "variant_1y": "Dziecko wskazuje śnieg.", "variant_2_3y": "Dziecko odróżnia zimę od jesieni.", "song": "Przyszła zima, biała pani, / śnieżkiem sypie razem z nami. / Witaj, zimo – my się cieszymy, / na sanki z tobą biegniemy!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('483404aa-5fea-587f-9535-e132fcecddf2','Kolory/kształty/wielkości','Biało i niebiesko',false,false,'2026-12-07','{"id": "2026-12-07-kolory-ksztalty-wielkosci", "day": "2026-12-07", "weekday": null, "option": 27, "title": "Biało i niebiesko", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Sortuje kolory zimy.", "materials": "białe i niebieskie duże przedmioty, 2 kosze", "steps": ["Pokaż kolory zimy: biały, niebieski.", "Dziecko bierze przedmiot.", "Wkłada do kosza w kolorze.", "Szukamy białego w sali."], "easier": "1 kolor z pomocą.", "harder": "2 kolory samodzielnie.", "variant_1y": "1 kolor z pomocą.", "variant_2_3y": "2 kolory samodzielnie.", "song": "Biały jak śnieg – do białego, / niebieski jak lód – do niebieskiego! / Sortujemy raz i dwa – / zimowe kolory każdy zna!", "song_author": "własna (KMK/Malachim)", "safety": "Przedmioty duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zima, śnieg i gwiazdki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('094544bd-08ec-5abf-98d8-4c78dc2ad0a6','Ruch','Rośnie choinka',false,false,'2026-12-14','{"id": "2026-12-14-ruch", "day": "2026-12-14", "weekday": null, "option": 1, "title": "Rośnie choinka", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy przysiad i wspięcie na palce.", "materials": "brak", "steps": ["Kucamy – mała choinka (nasionko).", "Powoli wstajemy – rośniemy.", "Na palcach, ręce w górę – duża choinka.", "Wiatr – kołyszemy się.", "Siadamy."], "easier": "Wstawanie z kucania za rękę.", "harder": "Na palcach do 3.", "variant_1y": "Wstawanie z kucania za rękę.", "variant_2_3y": "Na palcach do 3.", "song": "Mała choinka w ziemi śpi, / rośnie, rośnie – wyżej ty! / Duża, duża, aż do nieba, / kołysze się – tak trzeba!", "song_author": "własna (KMK/Malachim)", "safety": "Przy ścianie lub za rękę – równowaga.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ddd8a090-6f0d-5d08-a548-b9ae045b783f','Muzyka','Światełka grają',false,false,'2026-12-14','{"id": "2026-12-14-muzyka", "day": "2026-12-14", "weekday": null, "option": 2, "title": "Światełka grają", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Reaguje na sygnał wzrokowy muzyką.", "materials": "latarka LED, grzechotki (zaklejone butelki)", "steps": ["Opiekunka zapala latarkę – gramy.", "Gasi – cisza.", "Miga szybko – gramy szybko.", "Zamiana: dziecko trzyma latarkę."], "easier": "Granie z opiekunką.", "harder": "Dziecko steruje latarką.", "variant_1y": "Granie z opiekunką.", "variant_2_3y": "Dziecko steruje latarką.", "song": "Pstryk – światełko, gramy już, / pstryk – ciemno, cicho, stój! / Miga, miga – szybko gram, / świąteczna orkiestra – tam, tam, tam!", "song_author": "własna (KMK/Malachim)", "safety": "Latarka nie w oczy; baterie zabezpieczone śrubką.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('bf219a5e-7376-554a-94f2-f170cb84552a','Sensoryka','Choinkowe pudełko',false,false,'2026-12-14','{"id": "2026-12-14-sensoryka", "day": "2026-12-14", "weekday": null, "option": 3, "title": "Choinkowe pudełko", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Poznaje faktury świąteczne.", "materials": "pudełko: gałązka świerku (u opiekunki), plastikowa duża bombka nietłukąca, filcowa gwiazda, dzwonek z atestem", "steps": ["Wyjmujemy po kolei.", "Gałązka – kłuje (dotyk z opiekunką).", "Bombka – gładka, zimna.", "Gwiazda – miękka. Dzwonek – dzwoni."], "easier": "Dotyk 2 rzeczy.", "harder": "Nazywanie cech.", "variant_1y": "Dotyk 2 rzeczy.", "variant_2_3y": "Nazywanie cech.", "song": "Kłuje gałązka – kłu, kłu, kłu, / bombka gładka – ślizga się tu, / gwiazdka miękka, dzwonek: dzyń – / choinkowy skarb jest twój!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko bombki plastikowe duże (> 5 cm), bez zawieszek metalowych; żadnych szklanych ozdób.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('baf5530d-e905-57d2-b7a4-9c8f7ab471c2','Emocje','Czekam i się cieszę',false,false,'2026-12-14','{"id": "2026-12-14-emocje", "day": "2026-12-14", "weekday": null, "option": 4, "title": "Czekam i się cieszę", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Nazywa radość oczekiwania i cierpliwość.", "materials": "kalendarz adwentowy z kartonu (okienka z obrazkami)", "steps": ["Otwieramy dziś jedno okienko.", "Co tam? Obrazek.", "Mówimy: czekamy na święta – to radość.", "Ćwiczymy czekanie: liczymy do 3 i otwieramy."], "easier": "Dziecko otwiera okienko z pomocą.", "harder": "Dziecko czeka na swoją kolej i mówi „cieszę się”.", "variant_1y": "Dziecko otwiera okienko z pomocą.", "variant_2_3y": "Dziecko czeka na swoją kolej i mówi „cieszę się”.", "song": "Czekam, czekam – raz, dwa, trzy, / okienko otwieram ja i ty! / Radość w brzuszku – hop, hop, hop, / święta blisko – czekaj, stop!", "song_author": "własna (KMK/Malachim)", "safety": "Kalendarz bez słodyczy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('667cc8e3-9f60-5952-bb84-b47b364c7e8d','Zmysły','Pachnie świętami',false,false,'2026-12-14','{"id": "2026-12-14-zmysly", "day": "2026-12-14", "weekday": null, "option": 5, "title": "Pachnie świętami", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozpoznaje zapachy świąteczne.", "materials": "słoiczki z dziurkami: skórka pomarańczy, cynamon, gałązka świerku, goździki", "steps": ["Wąchamy po kolei.", "Nazywamy zapach.", "Lubię / nie lubię – miny.", "Dopasowujemy do obrazka."], "easier": "2 zapachy.", "harder": "Dopasowanie do obrazka.", "variant_1y": "2 zapachy.", "variant_2_3y": "Dopasowanie do obrazka.", "song": "Pomarańcza – mmm, słodko, / cynamon – ach, jak przytulnie, / świerk – pachnie lasem, / święta pachną nam za czasem!", "song_author": "własna (KMK/Malachim)", "safety": "Słoiki zakręcone; goździki i cynamon nie do ręki (zadławienie); bez olejków.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('bff1b365-c960-50d2-8b06-7a1cf59a71da','Zwierzęta','Leśne zwierzęta przy choince',false,false,'2026-12-14','{"id": "2026-12-14-zwierzeta", "day": "2026-12-14", "weekday": null, "option": 6, "title": "Leśne zwierzęta przy choince", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje zwierzęta lasu zimą.", "materials": "obrazki: sarna, zając, lis, wiewiórka", "steps": ["Opowiadamy: w lesie stoi choinka.", "Przychodzi sarna – skaczemy delikatnie.", "Zając – kicamy.", "Lis – skradamy się. Wiewiórka – wspinamy (na palcach)."], "easier": "Naśladowanie 2 zwierząt.", "harder": "Rozpoznanie po ruchu.", "variant_1y": "Naśladowanie 2 zwierząt.", "variant_2_3y": "Rozpoznanie po ruchu.", "song": "Do choinki w lesie idzie / sarenka, zając, lis i wiewiórka. / Hop, kic, skrad, wspin – / zwierzęta mają święta – dzyń!", "song_author": "własna (KMK/Malachim)", "safety": "Kicanie na macie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('02f35c1f-ebdd-53a8-9ccf-e97119d27a4a','Pogoda','Szron na gałązkach',false,false,'2026-12-14','{"id": "2026-12-14-pogoda", "day": "2026-12-14", "weekday": null, "option": 7, "title": "Szron na gałązkach", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Obserwuje szron i mróz.", "materials": "zdjęcie szronu, gałązka z dworu (rano)", "steps": ["Rano przynosimy gałązkę ze szronem.", "Oglądamy przez lupę (dużą).", "Dotykamy – zimne, białe igiełki.", "Patrzymy, jak w sali znika."], "easier": "Patrzenie i krótki dotyk.", "harder": "Obserwacja przez lupę i mówienie.", "variant_1y": "Patrzenie i krótki dotyk.", "variant_2_3y": "Obserwacja przez lupę i mówienie.", "song": "Biały szron na gałązce – / mróz malował w nocy w ciszy. / W cieple znika – kap i już, / szronie, szronie, wróć tu znów!", "song_author": "własna (KMK/Malachim)", "safety": "Lupa duża plastikowa; gałązka bez kolców.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5ccc3f7a-def0-5a52-8214-6e6925c69a66','Przyroda','Świerk i sosna',false,false,'2026-12-14','{"id": "2026-12-14-przyroda", "day": "2026-12-14", "weekday": null, "option": 8, "title": "Świerk i sosna", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Poznaje dwa drzewa iglaste.", "materials": "gałązki świerku i sosny (u opiekunki), szyszki duże (tylko do oglądania)", "steps": ["Pokaż świerk: krótkie igły.", "Sosna: długie igły.", "Dotykamy delikatnie.", "Wąchamy."], "easier": "Dziecko dotyka z opiekunką.", "harder": "Dziecko porównuje długość igieł.", "variant_1y": "Dziecko dotyka z opiekunką.", "variant_2_3y": "Dziecko porównuje długość igieł.", "song": "Świerk ma igły krótkie, kłujące, / sosna długie, miękkie, pachnące. / Obie zielone zimą i latem – / choinki rosną za naszym światem!", "song_author": "własna (KMK/Malachim)", "safety": "Szyszki i igły nie do buzi; gałązki trzyma dorosły; sprzątamy igły.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f9761b5a-f262-5581-9080-31ceddbef2c0','Eksperymenty','Co świeci?',false,false,'2026-12-14','{"id": "2026-12-14-eksperymenty", "day": "2026-12-14", "weekday": null, "option": 9, "title": "Co świeci?", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Odkrywa, co odbija i przepuszcza światło.", "materials": "latarka LED, folia aluminiowa (duży arkusz przyklejony do kartonu), kolorowa folia w ramce, karton", "steps": ["Świecimy na folię – błyszczy.", "Na kolorową – kolorowe światło na ścianie.", "Na karton – nic nie przechodzi.", "Dziecko świeci samo."], "easier": "Dziecko patrzy na kolory.", "harder": "Dziecko przewiduje i świeci samo.", "variant_1y": "Dziecko patrzy na kolory.", "variant_2_3y": "Dziecko przewiduje i świeci samo.", "song": "Świecę, świecę – co się stanie? / Folia błyszczy jak na zawołanie! / Kolor tańczy na ścianie – / karton chowa światło – ach, to takie zadanie!", "song_author": "własna (KMK/Malachim)", "safety": "Folie przyklejone w ramkach (bez kawałków); latarka nie w oczy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('cccc2736-d659-5876-9aae-ee1faf513b7c','Plastyka','Choinka z dłoni',false,false,'2026-12-14','{"id": "2026-12-14-plastyka", "day": "2026-12-14", "weekday": null, "option": 10, "title": "Choinka z dłoni", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Tworzy choinkę z odbić dłoni.", "materials": "duży karton, zielona farba, gąbki, kolorowe kropki z farby", "steps": ["Opiekunka maluje pień.", "Dzieci odbijają zielone dłonie – gałęzie.", "Palcami dodajemy kolorowe bombki.", "Gwiazdka na czubek – żółta dłoń."], "easier": "Jedno odbicie z pomocą.", "harder": "Kilka odbić i bombki.", "variant_1y": "Jedno odbicie z pomocą.", "variant_2_3y": "Kilka odbić i bombki.", "song": "Rączka zielona – plask, gałązka, / jeszcze jedna – rośnie choinka! / Kropka bombka, kropka światło – / nasza choinka świeci jasno!", "song_author": "własna (KMK/Malachim)", "safety": "Farby z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('365a2df7-76a0-51af-a09c-51c474dbf4eb','Samoobsługa','Ubieramy choinkę',false,false,'2026-12-14','{"id": "2026-12-14-samoobsluga", "day": "2026-12-14", "weekday": null, "option": 11, "title": "Ubieramy choinkę", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy chwyt i zawieszanie.", "materials": "choinka niska z materiału (na ścianie, z rzepami), ozdoby z filcu z rzepem", "steps": ["Pokaż choinkę na ścianie.", "Dziecko wybiera ozdobę.", "Przykleja na rzep.", "Zdejmujemy i układamy w pudełku."], "easier": "Przyklejanie z pomocą.", "harder": "Samodzielne ubieranie i sprzątanie.", "variant_1y": "Przyklejanie z pomocą.", "variant_2_3y": "Samodzielne ubieranie i sprzątanie.", "song": "Bombkę biorę – przyklejam, / gwiazdkę daję – ozdabiam! / Choinka piękna – patrz, / teraz sprzątam – raz, dwa, raz!", "song_author": "własna (KMK/Malachim)", "safety": "Ozdoby duże z filcu, rzepy przyszyte.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d3b47010-ac9c-5e22-bbaf-d96002723b4e','Język/logorytmika','Dzyń, bim, bam',false,false,'2026-12-14','{"id": "2026-12-14-jezyk-logorytmika", "day": "2026-12-14", "weekday": null, "option": 12, "title": "Dzyń, bim, bam", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy sylaby i rytm.", "materials": "dzwonek z atestem, bębenek", "steps": ["Dzwonek mały: dzyń.", "Dzwon duży: bim-bam.", "Bębenek: bum.", "Mówimy sylaby w rytm."], "easier": "Powtarzanie 1 sylaby.", "harder": "Sekwencja 3.", "variant_1y": "Powtarzanie 1 sylaby.", "variant_2_3y": "Sekwencja 3.", "song": "Dzyń, dzyń – dzwoneczek, / bim-bam – dzwon na wieży, / bum, bum – bębenek bije, / świąteczna piosenka żyje!", "song_author": "własna (KMK/Malachim)", "safety": "Instrumenty z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4ce3918f-888a-53a1-b4f2-c453edafcc0c','Zabawy paluszkowe i masażyki','Bombki na paluszkach',false,false,'2026-12-14','{"id": "2026-12-14-zabawy-paluszkowe-i-masazyki", "day": "2026-12-14", "weekday": null, "option": 13, "title": "Bombki na paluszkach", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Zabawa paluszkowa z liczeniem.", "materials": "brak", "steps": ["Pokazujemy palce – gałązki choinki.", "Każdy palec dostaje „bombkę” (dotyk).", "Na kciuk – gwiazdka.", "Choinka miga – poruszamy palcami."], "easier": "Opiekunka dotyka palców.", "harder": "Dziecko liczy.", "variant_1y": "Opiekunka dotyka palców.", "variant_2_3y": "Dziecko liczy.", "song": "Raz – bombka czerwona, / dwa – bombka zielona, / trzy – złota, cztery – srebrna, / pięć – gwiazdka na czubku pewna!", "song_author": "własna (KMK/Malachim)", "safety": "Delikatnie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('14ceb1dd-1f66-5b60-902f-c0f009d9ec45','Zabawy słowno-ruchowe i rymowanki','Choinka się kołysze',false,false,'2026-12-14','{"id": "2026-12-14-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-12-14", "weekday": null, "option": 14, "title": "Choinka się kołysze", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Ruch do rymowanki.", "materials": "brak", "steps": ["Stoimy jak choinki – ręce skośnie w dół.", "Wiatr – kołyszemy.", "Bombki – kręcimy dłońmi.", "Światełka – miganie palcami."], "easier": "Naśladowanie.", "harder": "Mówienie razem.", "variant_1y": "Naśladowanie.", "variant_2_3y": "Mówienie razem.", "song": "Choinka stoi, wiatr nią buja, / bombki się kręcą – hula, hula! / Światełka migają – mig, mig, mig, / i choinka cicho śpi – cyk!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b5419cdf-7ce6-544f-9562-8707a87b3e50','Powitania i integracja','Światełko powitania',false,false,'2026-12-14','{"id": "2026-12-14-powitania-i-integracja", "day": "2026-12-14", "weekday": null, "option": 15, "title": "Światełko powitania", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Wita się w grupie.", "materials": "lampka LED na baterie (bez płomienia)", "steps": ["Siadamy w kole.", "Lampka wędruje do dziecka.", "Mówimy imię i „świecisz dziś”.", "Dziecko podaje dalej."], "easier": "Opiekunka podaje.", "harder": "Dziecko podaje dalej samo.", "variant_1y": "Opiekunka podaje.", "variant_2_3y": "Dziecko podaje dalej samo.", "song": "Światełko wędruje, wędruje po kole, / do kogo przyjdzie, ten świeci na stole! / (imię) – świeć nam, uśmiechnij się, / dzień dobry, światełko, kochamy cię!", "song_author": "własna (KMK/Malachim)", "safety": "Lampka LED z zabezpieczoną baterią (śrubka); bez świeczek.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c55cf9a4-2f5e-5264-9373-92bda1d773c7','Świadomość ciała','Jestem choinką',false,false,'2026-12-14','{"id": "2026-12-14-swiadomosc-ciala", "day": "2026-12-14", "weekday": null, "option": 16, "title": "Jestem choinką", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Poznaje ciało przez „ozdabianie”.", "materials": "kamizelka z filcu z rzepami, duże ozdoby z filcu na rzep", "steps": ["Dziecko zakłada kamizelkę z rzepami.", "Przyklejamy ozdoby: na brzuszek, ramię, plecy.", "Nazywamy, gdzie ozdoba.", "Zdejmujemy po kolei."], "easier": "Opiekunka przykleja i nazywa.", "harder": "Dziecko przykleja i nazywa.", "variant_1y": "Opiekunka przykleja i nazywa.", "variant_2_3y": "Dziecko przykleja i nazywa.", "song": "Bombka na brzuszku, gwiazdka na głowie, / łańcuch na rączce – kto to? Powie! / Jestem choinką – ozdób mnie, / błyszczę, błyszczę – hej, hej, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Bez naklejek (do buzi) – tylko duże elementy na rzep.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ef1e7aee-941f-5825-81cb-bb6b9230d57b','Pamięć/uwaga/naśladowanie','Która bombka zniknęła?',false,false,'2026-12-14','{"id": "2026-12-14-pamiec-uwaga-nasladowanie", "day": "2026-12-14", "weekday": null, "option": 17, "title": "Która bombka zniknęła?", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy pamięć wzrokową.", "materials": "3–4 duże plastikowe bombki różnych kolorów", "steps": ["Kładziemy bombki.", "Nazywamy kolory.", "Zasłaniamy oczy, chowamy jedną.", "Pytamy: której brak?"], "easier": "2 bombki.", "harder": "4 bombki.", "variant_1y": "2 bombki.", "variant_2_3y": "4 bombki.", "song": "Czerwona, zielona, złota była – / jedna się bombka gdzieś ukryła! / Otwórz oczka, szukaj, wiesz? / Której nie ma? Powiedz też!", "song_author": "własna (KMK/Malachim)", "safety": "Bombki plastikowe duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('df44624a-0432-5791-b042-5d873523295c','Zabawy poznawcze','Od najmniejszej do największej',false,false,'2026-12-14','{"id": "2026-12-14-zabawy-poznawcze", "day": "2026-12-14", "weekday": null, "option": 18, "title": "Od najmniejszej do największej", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Porządkuje wielkości.", "materials": "3 choinki z kartonu różnej wielkości", "steps": ["Pokaż choinki.", "Która największa? najmniejsza?", "Ustawiamy w rząd.", "Mówimy: mała, większa, największa."], "easier": "Wskazanie dużej i małej.", "harder": "Ułożenie 3.", "variant_1y": "Wskazanie dużej i małej.", "variant_2_3y": "Ułożenie 3.", "song": "Mała choinka, średnia choinka, / duża choinka – to jest rodzinka! / Ustaw w rządek – raz, dwa, trzy – / od małej do dużej – brawo, ty!", "song_author": "własna (KMK/Malachim)", "safety": "Karton gruby.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('10488d8d-4587-527a-9da9-ba9a3220f091','Zabawy na dworze','Szukamy choinek',false,false,'2026-12-14','{"id": "2026-12-14-zabawy-na-dworze", "day": "2026-12-14", "weekday": null, "option": 19, "title": "Szukamy choinek", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Obserwuje świąteczną okolicę.", "materials": "ciepłe ubranie", "steps": ["Spacer wokół żłobka.", "Szukamy choinek i lampek w oknach.", "Liczymy.", "Machamy „wesołych świąt”."], "easier": "Wskazywanie z wózka.", "harder": "Liczenie z opiekunką.", "variant_1y": "Wskazywanie z wózka.", "variant_2_3y": "Liczenie z opiekunką.", "song": "Idę, idę, patrzę w okna – / tam choinka, tam światełko! / Raz, dwa, trzy – liczymy, / wesołych świąt życzymy!", "song_author": "własna (KMK/Malachim)", "safety": "Za rękę przy ulicy; krótko na mrozie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('65f867c5-b9ca-5218-9ac8-8eda9a7f157f','Higiena','Myjemy ręce po kleju i farbie',false,false,'2026-12-14','{"id": "2026-12-14-higiena", "day": "2026-12-14", "weekday": null, "option": 20, "title": "Myjemy ręce po kleju i farbie", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Utrwala mycie po pracach plastycznych.", "materials": "umywalka, mydło, szczoteczka do paznokci miękka", "steps": ["Pokazujemy brudne ręce po farbie.", "Mydło, pianka.", "Szczoteczka miękka po paznokciach.", "Spłukujemy, wycieramy."], "easier": "Z opiekunką.", "harder": "Samodzielnie.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Samodzielnie.", "song": "Zielone ręce? Szu, szu, szu! / Mydełko pieni – plum, plum, plum! / Szczoteczka paznokcie czyści – / rączki znowu są czyste!", "song_author": "własna (KMK/Malachim)", "safety": "Letnia woda, mokra podłoga.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6553154b-8978-538c-a473-791ab990566a','Czytanie dziecku','Choinka, która była za mała (opowiadanie)',false,false,'2026-12-14','{"id": "2026-12-14-czytanie-dziecku", "day": "2026-12-14", "weekday": null, "option": 21, "title": "Choinka, która była za mała (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii o akceptacji siebie.", "materials": "obrazek małej choinki, filcowa gwiazdka", "steps": ["Opowiadaj: „Mała choinka myślała, że nikt jej nie chce. Przyszły dzieci: jesteś taka jak my – mała! Postawiły ją w żłobku i ubrały”.", "Pokazuj obrazek.", "Dzieci przypinają gwiazdkę.", "Pytamy: czy mały może być ważny?"], "easier": "Słuchanie.", "harder": "Odpowiedź na pytanie.", "variant_1y": "Słuchanie.", "variant_2_3y": "Odpowiedź na pytanie.", "song": "Mała choinka – smutno jej, / aż przyszły dzieci: chodź do nas, hej! / Jesteś mała, jak i my – / najpiękniejsza jesteś ty!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('99380bf2-747b-5744-8130-de5bdf90a0d1','Klocki/budowanie','Choinka z klocków',false,false,'2026-12-14','{"id": "2026-12-14-klocki-budowanie", "day": "2026-12-14", "weekday": null, "option": 22, "title": "Choinka z klocków", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje kształt trójkąta (piramida).", "materials": "duże klocki", "steps": ["Na dole 3 klocki.", "Wyżej 2.", "Na górze 1.", "Gwiazdka z filcu na czubek."], "easier": "Dziecko podaje klocki.", "harder": "Dziecko buduje samo.", "variant_1y": "Dziecko podaje klocki.", "variant_2_3y": "Dziecko buduje samo.", "song": "Trzy na dole, dwa wyżej, / jeden na czubku – coraz bliżej! / Gwiazdka świeci – hop na szczyt, / klocków choinka – to nasz hit!", "song_author": "własna (KMK/Malachim)", "safety": "Klocki lekkie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('43f6fc02-be33-5ba8-b126-3a560022ee8e','Wyciszenie','Lampki migają wolno',false,false,'2026-12-14','{"id": "2026-12-14-wyciszenie", "day": "2026-12-14", "weekday": null, "option": 23, "title": "Lampki migają wolno", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Uspokaja oddech przy świetle.", "materials": "lampki LED na baterie w zamkniętym słoju plastikowym", "steps": ["Przyciemniamy salę (nie całkiem).", "Patrzymy na lampki.", "Wdech – światło, wydech – spokój.", "Leżymy chwilę."], "easier": "Przy opiekunce.", "harder": "Samodzielnie.", "variant_1y": "Przy opiekunce.", "variant_2_3y": "Samodzielnie.", "song": "Mig… mig… – światełko śpi, / wdech i wydech – ja i ty. / Cicho, cicho, ciepło tak, / świąteczny spokój – to nasz znak.", "song_author": "własna (KMK/Malachim)", "safety": "Lampki w zamkniętym pojemniku, baterie niedostępne.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fca822de-482c-57e1-a9d8-e9ee0d5ea098','Empatia','Ozdoba dla kolegi',false,false,'2026-12-14','{"id": "2026-12-14-empatia", "day": "2026-12-14", "weekday": null, "option": 24, "title": "Ozdoba dla kolegi", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy dawania.", "materials": "ozdoby z filcu", "steps": ["Każde dziecko wybiera ozdobę.", "Daje koledze: „proszę”.", "Kolega: „dziękuję”.", "Razem wieszamy na choince z filcu."], "easier": "Z pomocą.", "harder": "Samodzielnie.", "variant_1y": "Z pomocą.", "variant_2_3y": "Samodzielnie.", "song": "Dla ciebie bombka – proszę, weź, / dziękuję bardzo – miło też! / Razem wieszamy – ty i ja, / przyjaźń na choince błyszczy i gra!", "song_author": "własna (KMK/Malachim)", "safety": "Ozdoby duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5835fc5c-f933-5268-8e50-236f6d473717','Rodzina i dom','Kto ubiera choinkę w domu?',false,false,'2026-12-14','{"id": "2026-12-14-rodzina-i-dom", "day": "2026-12-14", "weekday": null, "option": 25, "title": "Kto ubiera choinkę w domu?", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Rozmawia o rodzinnych zwyczajach.", "materials": "zdjęcia rodzin (za zgodą), obrazek choinki", "steps": ["Pytamy: kto u ciebie ubiera choinkę?", "Mama, tata, babcia?", "Dzieci pokazują na zdjęciach.", "Udajemy ubieranie razem."], "easier": "Pokazywanie.", "harder": "Opowiadanie.", "variant_1y": "Pokazywanie.", "variant_2_3y": "Opowiadanie.", "song": "Mama wiesza bombki, / tata lampki świeci, / a ja gwiazdkę daję – / na rękach u taty, najwyżej!", "song_author": "własna (KMK/Malachim)", "safety": "Nie każda rodzina ma choinkę – bez oceniania.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c1bb4f56-9d4e-5f0b-abf8-b131cea118a3','Pory roku i święta','Adwent – czekamy na święta',false,false,'2026-12-14','{"id": "2026-12-14-pory-roku-i-swieta", "day": "2026-12-14", "weekday": null, "option": 26, "title": "Adwent – czekamy na święta", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Poznaje czas oczekiwania.", "materials": "kalendarz adwentowy z kartonu", "steps": ["Liczymy okienka do świąt.", "Mówimy: święta niedługo.", "Co będzie w święta? choinka, rodzina.", "Śpiewamy rymowankę."], "easier": "Patrzenie.", "harder": "Liczenie.", "variant_1y": "Patrzenie.", "variant_2_3y": "Liczenie.", "song": "Okienko jedno, okienko drugie, / dni do świąt już nie są długie! / Czekamy razem – ty i ja, / święta przyjdą – la, la, la!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('163b822c-5ea5-53bb-a6f5-4889855f55dd','Kolory/kształty/wielkości','Koło, trójkąt, gwiazdka',false,false,'2026-12-14','{"id": "2026-12-14-kolory-ksztalty-wielkosci", "day": "2026-12-14", "weekday": null, "option": 27, "title": "Koło, trójkąt, gwiazdka", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Rozpoznaje kształty.", "materials": "kształty z kartonu: koło (bombka), trójkąt (choinka), gwiazda", "steps": ["Pokaż kształty.", "Nazywamy.", "Dopasowujemy do konturów.", "Szukamy kształtów w sali."], "easier": "1 kształt.", "harder": "3 kształty.", "variant_1y": "1 kształt.", "variant_2_3y": "3 kształty.", "song": "Koło – bombka, okrągła, / trójkąt – choinka zielona, / gwiazdka – świeci na czubku – / kształty mamy w dobrym rządku!", "song_author": "własna (KMK/Malachim)", "safety": "Karton gruby.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Choinka i światełka", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e8698c6a-3653-508b-9177-9f85cf81e5e7','Ruch','Niesiemy prezenty',false,false,'2026-12-21','{"id": "2026-12-21-ruch", "day": "2026-12-21", "weekday": null, "option": 1, "title": "Niesiemy prezenty", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy chodzenie z przedmiotem i równowagę.", "materials": "pudełka kartonowe lekkie", "steps": ["Każde dziecko bierze paczkę.", "Niesiemy ostrożnie do choinki.", "Przechodzimy nad „zaspą” (poduszką).", "Kładziemy pod choinką."], "easier": "Niesienie z opiekunką.", "harder": "Przejście po linii z paczką.", "variant_1y": "Niesienie z opiekunką.", "variant_2_3y": "Przejście po linii z paczką.", "song": "Niosę paczkę – ostrożnie, wolno, / przez zaspę – hop – i dalej spokojnie. / Pod choinkę kładę – bęc, / prezent czeka – hej, hej, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Pudełka lekkie; poduszka płaska.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('54e73242-e82a-5cdd-9bb5-9205a07016bc','Muzyka','Kolęda dla misia',false,false,'2026-12-21','{"id": "2026-12-21-muzyka", "day": "2026-12-21", "weekday": null, "option": 2, "title": "Kolęda dla misia", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Śpiewa kołysankową piosenkę świąteczną (własną).", "materials": "miś, dzwonek z atestem", "steps": ["Kołyszemy misia.", "Śpiewamy cicho naszą piosenkę.", "Na „dzyń” – dzwonek.", "Kończymy szeptem."], "easier": "Kołysanie z opiekunką.", "harder": "Śpiew razem.", "variant_1y": "Kołysanie z opiekunką.", "variant_2_3y": "Śpiew razem.", "song": "Śpij, maleńki, gwiazdka lśni, / cicho w stajni, cicho my. / Dzyń, dzwoneczek, lulu, la – / święta noc już nadchodzi.", "song_author": "własna (KMK/Malachim)", "safety": "Dzwonek z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e2b3ab99-2e7d-571d-ae28-d1f56765e74f','Sensoryka','Papier prezentowy szeleści',false,false,'2026-12-21','{"id": "2026-12-21-sensoryka", "day": "2026-12-21", "weekday": null, "option": 3, "title": "Papier prezentowy szeleści", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Doświadcza dźwięku i dotyku papieru.", "materials": "duże arkusze papieru pakowego", "steps": ["Gnieciemy papier – szelest.", "Rozprostowujemy.", "Owijamy pluszaka.", "Rozpakowujemy."], "easier": "Gniecenie i szelest.", "harder": "Owijanie.", "variant_1y": "Gniecenie i szelest.", "variant_2_3y": "Owijanie.", "song": "Szur, szur – papier szeleści, / gniotę kulę – w rączce się mieści! / Owijam misia – raz, dwa, trzy, / rozpakuj, rozpakuj – kto to? Ty!", "song_author": "własna (KMK/Malachim)", "safety": "Papier duży, bez taśmy; kawałki zbieramy (nie do buzi).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f28bf4b0-fff6-5ea5-9172-5dd9b07c6c71','Emocje','Radość z bycia razem',false,false,'2026-12-21','{"id": "2026-12-21-emocje", "day": "2026-12-21", "weekday": null, "option": 4, "title": "Radość z bycia razem", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Nazywa radość i bliskość.", "materials": "koc", "steps": ["Siadamy razem na kocu.", "Mówimy: święta to czas bycia razem.", "Przytulamy się (kto chce).", "Mówimy: z kim się cieszę?"], "easier": "Przytulenie z opiekunką.", "harder": "Nazwanie bliskiej osoby.", "variant_1y": "Przytulenie z opiekunką.", "variant_2_3y": "Nazwanie bliskiej osoby.", "song": "Razem, razem – ja i ty, / ciepło, blisko, radość, my! / Święta to przytulić się, / i powiedzieć: kocham cię.", "song_author": "własna (KMK/Malachim)", "safety": "Dotyk tylko za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2a6a2b5f-0712-5dfd-99c7-5a81fef8e381','Zmysły','Co dzwoni, co szeleści?',false,false,'2026-12-21','{"id": "2026-12-21-zmysly", "day": "2026-12-21", "weekday": null, "option": 5, "title": "Co dzwoni, co szeleści?", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozpoznaje świąteczne dźwięki.", "materials": "dzwonek, papier, pozytywka, grzechotka", "steps": ["Opiekunka chowa za parawanem.", "Robi dźwięk.", "Dzieci zgadują.", "Pokazujemy."], "easier": "2 dźwięki.", "harder": "4 dźwięki.", "variant_1y": "2 dźwięki.", "variant_2_3y": "4 dźwięki.", "song": "Dzyń – dzwonek, szur – papier, / gra pozytywka – ta, ta, ta! / Uszko słucha, oczko śpi – / co to było? Powiedz mi!", "song_author": "własna (KMK/Malachim)", "safety": "Instrumenty z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('484f04ba-2aa3-5204-8dcf-bb064f804674','Zwierzęta','Zwierzęta w stajence',false,false,'2026-12-21','{"id": "2026-12-21-zwierzeta", "day": "2026-12-21", "weekday": null, "option": 6, "title": "Zwierzęta w stajence", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje zwierzęta gospodarskie z opowieści świątecznej.", "materials": "obrazki: osioł, owca, krowa", "steps": ["Pokazujemy zwierzęta.", "Naśladujemy głosy: i-a, bee, muu.", "Zwierzęta szepczą cicho – noc.", "Kładziemy się jak owieczki."], "easier": "Naśladowanie 1 głosu.", "harder": "3 głosy.", "variant_1y": "Naśladowanie 1 głosu.", "variant_2_3y": "3 głosy.", "song": "Osiołek: i-a, owieczka: bee, / krówka: muu – cicho, sza, cii! / W stajence ciepło, w stajence spokój – / zwierzęta śpią obok.", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('cfd913e7-c171-58b2-a082-1f770d365a3d','Pogoda','Gwiazdka na niebie',false,false,'2026-12-21','{"id": "2026-12-21-pogoda", "day": "2026-12-21", "weekday": null, "option": 7, "title": "Gwiazdka na niebie", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Obserwuje niebo zimowym popołudniem.", "materials": "okno, obrazek pierwszej gwiazdki", "steps": ["Zimą szybko robi się ciemno.", "Patrzymy w okno po 15:00.", "Szukamy gwiazdki lub księżyca.", "Mówimy: w Wigilię szukamy pierwszej gwiazdki."], "easier": "Patrzenie z opiekunką.", "harder": "Wskazanie gwiazdki.", "variant_1y": "Patrzenie z opiekunką.", "variant_2_3y": "Wskazanie gwiazdki.", "song": "Szybko ciemno, szybko noc, / gwiazdka świeci – co za moc! / Pierwsza gwiazdka – patrz, tam lśni, / wesołych świąt – ja i ty!", "song_author": "własna (KMK/Malachim)", "safety": "Przy zamkniętym oknie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c18a5b9b-04e2-5b68-a3d5-ef05484ca154','Przyroda','Siano i słoma',false,false,'2026-12-21','{"id": "2026-12-21-przyroda", "day": "2026-12-21", "weekday": null, "option": 8, "title": "Siano i słoma", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Poznaje naturalne materiały.", "materials": "garść siana w przezroczystym woreczku zamkniętym i na tacy", "steps": ["Pokaż siano – pachnie łąką.", "Dotykamy na tacy.", "Pod obrus wkłada się siano – zwyczaj.", "Sprzątamy."], "easier": "Wąchanie przez woreczek.", "harder": "Dotyk na tacy.", "variant_1y": "Wąchanie przez woreczek.", "variant_2_3y": "Dotyk na tacy.", "song": "Siano pachnie latem, łąką, / pod obrusem leży cicho. / Szur, szur – suche, kłujące – / wspomnienie lata pachnące!", "song_author": "własna (KMK/Malachim)", "safety": "Alergie (pyłki) – sprawdź; siano nie do buzi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3302732f-0d05-531d-8f18-dce750d2b4eb','Eksperymenty','Pierniczki – kolor ciasta',false,false,'2026-12-21','{"id": "2026-12-21-eksperymenty", "day": "2026-12-21", "weekday": null, "option": 9, "title": "Pierniczki – kolor ciasta", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje mieszanie składników (bez jedzenia).", "materials": "miska, mąka (trochę), woda, łyżka, foremki duże", "steps": ["Mąka – sucha, biała.", "Dodajemy wodę – klei się.", "Ugniatamy masę.", "Wycinamy foremką kształt (do zabawy)."], "easier": "Ugniatanie gotowej masy.", "harder": "Mieszanie i wycinanie.", "variant_1y": "Ugniatanie gotowej masy.", "variant_2_3y": "Mieszanie i wycinanie.", "song": "Mąka sypie się jak śnieg, / woda – chlup! – i ciasto: hej! / Ugniatam, wałkuję – raz, dwa, trzy, / foremka – gwiazdka dla mnie i ty!", "song_author": "własna (KMK/Malachim)", "safety": "Masa niejadalna – nie zjadamy surowej mąki; alergia na gluten – rękawiczki/inna masa.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('98c8a7fb-5775-5216-95df-46cad6e3fd22','Plastyka','Kartka świąteczna dla rodziny',false,false,'2026-12-21','{"id": "2026-12-21-plastyka", "day": "2026-12-21", "weekday": null, "option": 10, "title": "Kartka świąteczna dla rodziny", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Robi pracę dla bliskich.", "materials": "karton A5 złożony, farba, stempel-gwiazdka, wycięta choinka", "steps": ["Dziecko przykleja choinkę (klej u opiekunki).", "Stempluje gwiazdki.", "Odbija paluszek – bombki.", "Opiekunka pisze życzenia od dziecka."], "easier": "Odbicie palca z pomocą.", "harder": "Samodzielne stemplowanie.", "variant_1y": "Odbicie palca z pomocą.", "variant_2_3y": "Samodzielne stemplowanie.", "song": "Kartka dla mamy, kartka dla taty, / gwiazdki i bombki – pięknie bogaty! / Odbijam palec – kropka, kropka, / wesołych świąt dla całego domku!", "song_author": "własna (KMK/Malachim)", "safety": "Farby z atestem; klej u opiekunki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b804109d-8344-5f0f-afbd-4370a74ee733','Samoobsługa','Nakrywamy do stołu',false,false,'2026-12-21','{"id": "2026-12-21-samoobsluga", "day": "2026-12-21", "weekday": null, "option": 11, "title": "Nakrywamy do stołu", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy rozkładanie talerzyków.", "materials": "plastikowe talerzyki, kubki, serwetki", "steps": ["Dziecko kładzie talerzyk przed krzesłem.", "Kubek obok.", "Serwetka.", "Dodatkowe nakrycie dla gościa – zwyczaj."], "easier": "Kładzenie talerzyka.", "harder": "Całe nakrycie.", "variant_1y": "Kładzenie talerzyka.", "variant_2_3y": "Całe nakrycie.", "song": "Talerzyk tu, kubeczek tam, / serwetkę kładę – sam, sam, sam! / Jedno miejsce dla gościa – / niech przyjdzie każdy, kto tu chciał!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko plastikowe naczynia.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f4f07937-addf-5d8d-a46a-d142d1b6fc3b','Język/logorytmika','Życzenia',false,false,'2026-12-21','{"id": "2026-12-21-jezyk-logorytmika", "day": "2026-12-21", "weekday": null, "option": 12, "title": "Życzenia", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy proste zwroty i sylabizowanie.", "materials": "brak", "steps": ["Mówimy „we-so-łych świąt” sylabami z klaskaniem.", "„Smacz-ne-go”.", "„Ko-cham cię”.", "Mówimy do misia."], "easier": "Klaskanie sylab.", "harder": "Mówienie sylab.", "variant_1y": "Klaskanie sylab.", "variant_2_3y": "Mówienie sylab.", "song": "We-so-łych świąt – klap, klap, klap, / smacz-ne-go – mniam, mniam, mniam, / ko-cham cię – przytul mnie, / święta są – hej, hej, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('962e1604-e674-59c0-9a24-5862908bff16','Zabawy paluszkowe i masażyki','Pieczemy pierniczki',false,false,'2026-12-21','{"id": "2026-12-21-zabawy-paluszkowe-i-masazyki", "day": "2026-12-21", "weekday": null, "option": 13, "title": "Pieczemy pierniczki", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Masażyk na plecach.", "materials": "brak", "steps": ["Sypiemy mąkę – stukamy palcami.", "Wałkujemy – dłonie w dół i w górę.", "Wycinamy – rysujemy gwiazdkę.", "Do pieca – ciepła dłoń na plecach."], "easier": "Lekko.", "harder": "Dziecko robi koledze.", "variant_1y": "Lekko.", "variant_2_3y": "Dziecko robi koledze.", "song": "Sypię mąkę – puk, puk, puk, / wałkuję – szur, szur, szur, / wycinam gwiazdkę – raz, dwa, trzy, / do pieca – ciepło – mniam, ty!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('16b5be0b-0932-5802-897a-5549c3b7dfab','Zabawy słowno-ruchowe i rymowanki','Do babci na święta',false,false,'2026-12-21','{"id": "2026-12-21-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-12-21", "weekday": null, "option": 14, "title": "Do babci na święta", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Ruch do rymowanki – podróż.", "materials": "brak", "steps": ["Jedziemy autem – kierownica.", "Saniami – hop, hop.", "Pieszo – tup.", "Puk, puk – drzwi – przytulamy się."], "easier": "Naśladowanie.", "harder": "Mówienie.", "variant_1y": "Naśladowanie.", "variant_2_3y": "Mówienie.", "song": "Brum, brum – autem jadę, / hop, hop – saniami, / tup, tup – pieszo idę, / puk, puk – babciu, jestem z wami!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fddc7fbc-989b-5238-8d22-5362ca93dfed','Powitania i integracja','Opłatek – dzielimy się',false,false,'2026-12-21','{"id": "2026-12-21-powitania-i-integracja", "day": "2026-12-21", "weekday": null, "option": 15, "title": "Opłatek – dzielimy się", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Poznaje zwyczaj dzielenia się (symbolicznie).", "materials": "papierowy „opłatek” (biała kartka)", "steps": ["Siadamy w kole.", "Każde dziecko łamie kawałek papierowego opłatka sąsiadowi.", "Mówimy „wesołych świąt”.", "Uśmiech."], "easier": "Opiekunka prowadzi.", "harder": "Dziecko mówi życzenie.", "variant_1y": "Opiekunka prowadzi.", "variant_2_3y": "Dziecko mówi życzenie.", "song": "Dzielę się z tobą – proszę, weź, / wesołych świąt – i zdrowia też! / Razem, razem w koło, w koło – / w żłobku święta, jest wesoło!", "song_author": "własna (KMK/Malachim)", "safety": "Papier, nie prawdziwy opłatek (do buzi / dławienie u 1-latków); jeśli prawdziwy – tylko za zgodą rodziców, mały kawałek, przy stole.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3e442e12-41ce-5787-a7e3-b9bcba5e2e8b','Świadomość ciała','Przytulasy',false,false,'2026-12-21','{"id": "2026-12-21-swiadomosc-ciala", "day": "2026-12-21", "weekday": null, "option": 16, "title": "Przytulasy", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Czuje ciało przez różne uściski.", "materials": "brak", "steps": ["Przytulamy siebie – „sam”.", "Misia.", "Opiekunkę.", "Mówimy, co czuję: ciepło."], "easier": "Przytulenie z opiekunką.", "harder": "Nazwanie uczucia.", "variant_1y": "Przytulenie z opiekunką.", "variant_2_3y": "Nazwanie uczucia.", "song": "Przytulam siebie – mocno, mocno, / przytulam misia – miękko, miękko, / przytulam panią – ciepło, ciepło – / kocham cię, ciało moje!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3292819f-d1d4-5b7d-979f-17984e602a6b','Pamięć/uwaga/naśladowanie','Co jest pod choinką?',false,false,'2026-12-21','{"id": "2026-12-21-pamiec-uwaga-nasladowanie", "day": "2026-12-21", "weekday": null, "option": 17, "title": "Co jest pod choinką?", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy pamięć.", "materials": "3 przedmioty pod chustą", "steps": ["Pokazujemy 3 przedmioty.", "Przykrywamy chustą.", "Pytamy: co tam jest?", "Odkrywamy."], "easier": "1–2 przedmioty.", "harder": "3 przedmioty.", "variant_1y": "1–2 przedmioty.", "variant_2_3y": "3 przedmioty.", "song": "Pod choinką – co tam jest? / Miś, piłka i dzwonek – hej! / Chusta w dół – pamiętasz? Tak! / Brawo, brawo – to jest znak!", "song_author": "własna (KMK/Malachim)", "safety": "Przedmioty duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('11ee1a77-e692-51fc-bbe3-51f49f8724e5','Zabawy poznawcze','Paczka dla każdego',false,false,'2026-12-21','{"id": "2026-12-21-zabawy-poznawcze", "day": "2026-12-21", "weekday": null, "option": 18, "title": "Paczka dla każdego", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Przyporządkowanie 1:1.", "materials": "pluszaki (5), paczki (5)", "steps": ["Ustawiamy pluszaki.", "Każdy dostaje 1 paczkę.", "Sprawdzamy: wystarczy?", "Dodajemy/zabieramy."], "easier": "2 pluszaki.", "harder": "5 pluszaków.", "variant_1y": "2 pluszaki.", "variant_2_3y": "5 pluszaków.", "song": "Jeden miś – jedna paczka, / jeden zając – jedna paczka! / Każdy ma – nikt nie płacze, / sprawiedliwe święta takie!", "song_author": "własna (KMK/Malachim)", "safety": "Brak szczególnych.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('36fe6a02-81dc-5d87-88e4-82a095a01a61','Zabawy na dworze','Spacer po świątecznym podwórku',false,false,'2026-12-21','{"id": "2026-12-21-zabawy-na-dworze", "day": "2026-12-21", "weekday": null, "option": 19, "title": "Spacer po świątecznym podwórku", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Obserwuje dekoracje.", "materials": "ciepłe ubranie", "steps": ["Spacer.", "Szukamy lampek, wieńców.", "Słuchamy dzwonów (jeśli są).", "Machamy sąsiadom."], "easier": "W wózku.", "harder": "Pieszo za rękę.", "variant_1y": "W wózku.", "variant_2_3y": "Pieszo za rękę.", "song": "Lampki świecą, wieniec wisi, / dzwony biją – bim, bam, bisi! / Spacerujemy – tup, tup, tup – / święta wszędzie – hop, hop, hop!", "song_author": "własna (KMK/Malachim)", "safety": "Krótko przy mrozie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('8e4a1317-6763-52fc-aa23-e0c25fa6ffcd','Higiena','Myjemy ręce przed wieczerzą',false,false,'2026-12-21','{"id": "2026-12-21-higiena", "day": "2026-12-21", "weekday": null, "option": 20, "title": "Myjemy ręce przed wieczerzą", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Utrwala mycie przed jedzeniem.", "materials": "umywalka, mydło", "steps": ["Mówimy: przed jedzeniem myjemy ręce.", "Myjemy z rymowanką.", "Wycieramy.", "Siadamy do stołu."], "easier": "Z opiekunką.", "harder": "Sam.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Sam.", "song": "Przed kolacją – rączki myj, / szu, szu, szu – mydełko bij! / Czyste rączki, czysty stół – / smacznego, smacznego, hop!", "song_author": "własna (KMK/Malachim)", "safety": "Letnia woda.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a4ea91ec-8e11-5b2c-b52f-1eb535d320ae','Czytanie dziecku','Gwiazdka zgubiła drogę (opowiadanie)',false,false,'2026-12-21','{"id": "2026-12-21-czytanie-dziecku", "day": "2026-12-21", "weekday": null, "option": 21, "title": "Gwiazdka zgubiła drogę (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii o pomocy.", "materials": "obrazek gwiazdki, latarka", "steps": ["Opowiadaj: „Mała gwiazdka spadła na śnieg. Zając, sowa i dzieci pomogli jej wrócić na niebo – podnieśli ją wysoko”.", "Świecimy latarką na sufit – gwiazdka wróciła.", "Dzieci pomagają „podnieść”.", "Pytamy: kto pomógł?"], "easier": "Słuchanie.", "harder": "Odpowiedź.", "variant_1y": "Słuchanie.", "variant_2_3y": "Odpowiedź.", "song": "Gwiazdka spadła – ojej, ojej, / kto pomoże? Zając, sowa – hej! / I dzieci – raz, dwa, trzy – / gwiazdka świeci, dziękuje ty!", "song_author": "własna (KMK/Malachim)", "safety": "Latarka nie w oczy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('7e5cc4df-5cf8-5835-9c9a-4365c6989f9d','Klocki/budowanie','Stajenka z klocków',false,false,'2026-12-21','{"id": "2026-12-21-klocki-budowanie", "day": "2026-12-21", "weekday": null, "option": 22, "title": "Stajenka z klocków", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje schronienie.", "materials": "duże klocki, figurki zwierząt duże", "steps": ["Budujemy ściany.", "Dach z tektury.", "Wprowadzamy zwierzęta.", "Mówimy: ciepło im."], "easier": "Wprowadzanie zwierząt.", "harder": "Budowanie.", "variant_1y": "Wprowadzanie zwierząt.", "variant_2_3y": "Budowanie.", "song": "Ściana, ściana, dach na górę – / stajenka gotowa – nie ma chmur! / Owca, osioł, krowa wchodzą, / ciepło im – już się nie trwożą.", "song_author": "własna (KMK/Malachim)", "safety": "Figurki duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fb01c5a7-fa1d-55ce-af28-41ab73949a04','Wyciszenie','Kołysanka gwiazdkowa',false,false,'2026-12-21','{"id": "2026-12-21-wyciszenie", "day": "2026-12-21", "weekday": null, "option": 23, "title": "Kołysanka gwiazdkowa", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza.", "materials": "koc, lampka LED", "steps": ["Leżymy.", "Lampka świeci cicho.", "Śpiewamy kołysankę.", "Cisza."], "easier": "Przy opiekunce.", "harder": "Samodzielnie.", "variant_1y": "Przy opiekunce.", "variant_2_3y": "Samodzielnie.", "song": "Gwiazdka świeci nad domem, / śpij, maleńki, śpij spokojnie. / Lulu, lulu, święta noc – / dobranoc, dobranoc.", "song_author": "własna (KMK/Malachim)", "safety": "Lampka LED zabezpieczona.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('4e471a6c-56d4-55d4-9214-e006dd9a4010','Empatia','Prezent nie musi być kupiony',false,false,'2026-12-21','{"id": "2026-12-21-empatia", "day": "2026-12-21", "weekday": null, "option": 24, "title": "Prezent nie musi być kupiony", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy dawania uśmiechu i przytulenia.", "materials": "brak", "steps": ["Pytamy: co możemy dać bez pieniędzy?", "Uśmiech – dajemy sąsiadowi.", "Przytulenie (za zgodą).", "Pomoc – podajemy coś."], "easier": "Uśmiech do opiekunki.", "harder": "Dziecko proponuje.", "variant_1y": "Uśmiech do opiekunki.", "variant_2_3y": "Dziecko proponuje.", "song": "Daję uśmiech – nic nie kosztuje, / daję przytulasa – serce czuje! / Pomogę ci – proszę, weź – / najpiękniejszy prezent też!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c19ac44d-0ddd-5733-860a-dd01479c516a','Rodzina i dom','Święta w moim domu',false,false,'2026-12-21','{"id": "2026-12-21-rodzina-i-dom", "day": "2026-12-21", "weekday": null, "option": 25, "title": "Święta w moim domu", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Opowiada o rodzinnych świętach.", "materials": "zdjęcia (za zgodą)", "steps": ["Pytamy: z kim spędzasz święta?", "Co jecie? (pierogi, barszcz…).", "Pokazujemy na zdjęciach.", "Rysujemy stół."], "easier": "Pokazywanie.", "harder": "Opowiadanie.", "variant_1y": "Pokazywanie.", "variant_2_3y": "Opowiadanie.", "song": "W moim domu przy stole – / mama, tata, babcia, ja! / Pierogi, barszczyk, choinka – / święta – szczęśliwa rodzinka!", "song_author": "własna (KMK/Malachim)", "safety": "Różne tradycje (i brak świąt) – szanujemy.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ea00793c-fbdb-5263-8b7e-f2098f8f0aaf','Pory roku i święta','Boże Narodzenie w żłobku',false,false,'2026-12-21','{"id": "2026-12-21-pory-roku-i-swieta", "day": "2026-12-21", "weekday": null, "option": 26, "title": "Boże Narodzenie w żłobku", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Przeżywa święta w grupie.", "materials": "choinka (zabezpieczona), lampki (poza zasięgiem), wspólny stół", "steps": ["Siadamy przy stole.", "Śpiewamy naszą kolędę.", "Dzielimy się papierowym opłatkiem.", "Składamy życzenia i bijemy brawo."], "easier": "Udział z opiekunką.", "harder": "Mówienie życzeń.", "variant_1y": "Udział z opiekunką.", "variant_2_3y": "Mówienie życzeń.", "song": "Święta, święta – w żłobku też, / choinka świeci – dzyń, dzyń, hej! / Życzymy zdrowia, radości, / i dużo, dużo miłości!", "song_author": "własna (KMK/Malachim)", "safety": "Choinka przymocowana; lampki i kable poza zasięgiem; bez szklanych bombek i lamety; jedzenie dopasowane do diety i alergii.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('596aaa67-19f1-5778-a966-8273a192f24a','Kolory/kształty/wielkości','Złoto i srebro',false,false,'2026-12-21','{"id": "2026-12-21-kolory-ksztalty-wielkosci", "day": "2026-12-21", "weekday": null, "option": 27, "title": "Złoto i srebro", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Poznaje kolory błyszczące.", "materials": "złote i srebrne duże elementy (karton z folią przyklejoną)", "steps": ["Pokaż złoty i srebrny.", "Sortujemy.", "Porównujemy duże/małe.", "Wieszamy na filcowej choince."], "easier": "1 kolor.", "harder": "2 kolory i wielkość.", "variant_1y": "1 kolor.", "variant_2_3y": "2 kolory i wielkość.", "song": "Złoty błyszczy jak słoneczko, / srebrny jak księżyc – maleńko! / Duże tu, a małe tam – / błyszczącą choinkę mam!", "song_author": "własna (KMK/Malachim)", "safety": "Folia przyklejona na stałe.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Boże Narodzenie – święta w domu", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0496329e-2fd5-5605-b534-5bdea26d3739','Ruch','Zegar tyka',false,false,'2026-12-28','{"id": "2026-12-28-ruch", "day": "2026-12-28", "weekday": null, "option": 1, "title": "Zegar tyka", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy ruch rytmiczny wahadłowy.", "materials": "bębenek", "steps": ["Stajemy – jesteśmy zegarem.", "Tik-tak – kołyszemy się na boki.", "Szybki zegar – szybciej.", "Bije północ – skaczemy 1 raz w górę: „Nowy Rok!”."], "easier": "Kołysanie na rękach.", "harder": "Zmiana tempa samodzielnie.", "variant_1y": "Kołysanie na rękach.", "variant_2_3y": "Zmiana tempa samodzielnie.", "song": "Tik-tak, tik-tak – zegar chodzi, / szybko, wolno – czas przechodzi. / Bim-bam – północ bije już – / hop! Nowy Rok – hura, hurra – już!", "song_author": "własna (KMK/Malachim)", "safety": "Skok na macie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('407827af-0a76-54f7-b807-287a7e2ee4bc','Muzyka','Orkiestra noworoczna',false,false,'2026-12-28','{"id": "2026-12-28-muzyka", "day": "2026-12-28", "weekday": null, "option": 2, "title": "Orkiestra noworoczna", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Gra na instrumentach zamiast fajerwerków.", "materials": "bębenki, grzechotki, tamburyny z atestem", "steps": ["Każde dziecko dostaje instrument.", "„Fajerwerk” – wszyscy grają głośno krótko.", "Cisza.", "Grają po kolei."], "easier": "Granie z opiekunką.", "harder": "Granie solo.", "variant_1y": "Granie z opiekunką.", "variant_2_3y": "Granie solo.", "song": "Bum! – to fajerwerk z bębna, / szur! – grzechotka zamiast ognia. / Gramy, gramy – cicho, stop – / Nowy Rok – hop, hop, hop!", "song_author": "własna (KMK/Malachim)", "safety": "Bez prawdziwych petard i zimnych ogni; instrumenty z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f6bd11f7-f977-5ac8-9867-b19921a433e5','Sensoryka','Konfetti w butelce',false,false,'2026-12-28','{"id": "2026-12-28-sensoryka", "day": "2026-12-28", "weekday": null, "option": 3, "title": "Konfetti w butelce", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Obserwuje ruch kolorowych elementów.", "materials": "butelka plastikowa z wodą, gliceryną i dużym brokatem/cekinami – zaklejona", "steps": ["Potrząsamy butelką.", "Patrzymy, jak wiruje.", "Opadanie – cisza.", "Toczymy po podłodze."], "easier": "Patrzenie i toczenie.", "harder": "Samodzielne potrząsanie i liczenie.", "variant_1y": "Patrzenie i toczenie.", "variant_2_3y": "Samodzielne potrząsanie i liczenie.", "song": "Potrząśnij – wiruje, kręci się, / błyszczy, tańczy – hej, hej, hej! / Cicho opada – raz, dwa, trzy – / noworoczne gwiazdki śpią.", "song_author": "własna (KMK/Malachim)", "safety": "Korek przyklejony klejem na gorąco + taśma; prawdziwe konfetti nie (do buzi).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d849eb78-d0f5-5722-adda-ebe1d0a949a4','Emocje','Głośno mnie przestrasza',false,false,'2026-12-28','{"id": "2026-12-28-emocje", "day": "2026-12-28", "weekday": null, "option": 4, "title": "Głośno mnie przestrasza", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Rozmawia o strachu przed hukiem.", "materials": "nagranie cichego fajerwerku, koc", "steps": ["Pytamy: czy słyszałeś huk w nocy?", "Pokazujemy minę strachu.", "Co pomaga? Zatkać uszy, przytulić się.", "Ćwiczymy zatykanie uszu i przytulenie."], "easier": "Przytulenie.", "harder": "Mówienie, co pomaga.", "variant_1y": "Przytulenie.", "variant_2_3y": "Mówienie, co pomaga.", "song": "Bum! – się boję, serce bije, / zatkam uszy, misia przytulę. / Mama blisko – już nie straszno, / huk minął – jest już jasno!", "song_author": "własna (KMK/Malachim)", "safety": "Nie odtwarzamy głośnych huków.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('cf3dbe44-1849-5424-9d6c-09e0a06a539f','Zmysły','Głośno – cicho',false,false,'2026-12-28','{"id": "2026-12-28-zmysly", "day": "2026-12-28", "weekday": null, "option": 5, "title": "Głośno – cicho", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozróżnia natężenie dźwięku.", "materials": "bębenek", "steps": ["Gramy głośno – ręce wysoko.", "Cicho – ręce nisko.", "Dzieci pokazują.", "Zamiana ról."], "easier": "Z pomocą.", "harder": "Samodzielnie.", "variant_1y": "Z pomocą.", "variant_2_3y": "Samodzielnie.", "song": "Głośno, głośno – bum, bum, bum, / cicho, cicho – tum, tum, tum. / Ręce w górę – głośno gra, / ręce w dół – cichutko, sza!", "song_author": "własna (KMK/Malachim)", "safety": "Głośność umiarkowana.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6720145e-bd23-547c-9f04-448e92606a77','Zwierzęta','Zwierzęta boją się huku',false,false,'2026-12-28','{"id": "2026-12-28-zwierzeta", "day": "2026-12-28", "weekday": null, "option": 6, "title": "Zwierzęta boją się huku", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Uczy empatii wobec zwierząt.", "materials": "obrazki: pies, kot, ptak", "steps": ["Psy i koty boją się fajerwerków.", "Naśladujemy psa chowającego się pod kocem.", "Głaszczemy pluszowego psa.", "Mówimy: cicho, nie bój się."], "easier": "Głaskanie pluszaka.", "harder": "Mówienie zdania.", "variant_1y": "Głaskanie pluszaka.", "variant_2_3y": "Mówienie zdania.", "song": "Piesek się boi – schował się, / kotek drży – miau, miau, nie, nie! / Pogłaszczemy – cicho, sza, / nie bój się, jestem ja!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c23413c1-554f-55e4-9436-3f973adc7c0f','Pogoda','Styczniowy mróz',false,false,'2026-12-28','{"id": "2026-12-28-pogoda", "day": "2026-12-28", "weekday": null, "option": 7, "title": "Styczniowy mróz", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Obserwuje mróz i lód.", "materials": "termometr duży (obrazkowy), lód w misce", "steps": ["Patrzymy na termometr: zimno.", "Dotykamy lodu.", "Ubieramy się na dwór.", "Chuchamy – para."], "easier": "Dotyk lodu.", "harder": "Mówienie „mróz”.", "variant_1y": "Dotyk lodu.", "variant_2_3y": "Mówienie „mróz”.", "song": "Styczeń mrozem szczypie w nos, / chuch, chuch – para, biały głos! / Termometr nisko – brr, brr, brr, / kurtka, czapka – idziemy, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Krótki kontakt z lodem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('69b62fcf-ce54-5619-a3d4-5e12c96791ac','Przyroda','Nowy kalendarz – pory roku',false,false,'2026-12-28','{"id": "2026-12-28-przyroda", "day": "2026-12-28", "weekday": null, "option": 8, "title": "Nowy kalendarz – pory roku", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Poznaje cztery pory roku.", "materials": "4 duże obrazki pór roku", "steps": ["Pokazujemy 4 obrazki.", "Teraz jest zima – wskazujemy.", "Potem wiosna – kwiatki.", "Lato – słońce, jesień – liście."], "easier": "Wskazanie zimy.", "harder": "Nazwanie 4.", "variant_1y": "Wskazanie zimy.", "variant_2_3y": "Nazwanie 4.", "song": "Zima – śnieg, wiosna – kwiat, / lato – słońce, jesień – liść! / Kręci się rok jak kółeczko – / znowu zima – hop, piosenko!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('60ce4fbd-e290-5fa0-8201-c39118f343f1','Eksperymenty','Balonik na butelce',false,false,'2026-12-28','{"id": "2026-12-28-eksperymenty", "day": "2026-12-28", "weekday": null, "option": 9, "title": "Balonik na butelce", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje powietrze.", "materials": "butelka, ocet, soda – TYLKO opiekunka; balon (u opiekunki)", "steps": ["Opiekunka wsypuje sodę do balonu, ocet do butelki.", "Zakłada balon na szyjkę.", "Soda wpada – balon rośnie!", "Dzieci obserwują z odległości."], "easier": "Patrzenie z kolan.", "harder": "Przewidywanie.", "variant_1y": "Patrzenie z kolan.", "variant_2_3y": "Przewidywanie.", "song": "Szyp, szyp – soda sypie się, / ocet syczy – psss, hej, hej! / Balon rośnie – większy, wielki – / dmuch bez dmuchania – co za cud!", "song_author": "własna (KMK/Malachim)", "safety": "Balony to zagrożenie zadławienia – tylko w rękach dorosłego, pęknięte kawałki zbierać natychmiast; ocet z dala od oczu.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6ca250ee-bf48-52b6-983a-4ab9df72913a','Plastyka','Fajerwerki z farby',false,false,'2026-12-28','{"id": "2026-12-28-plastyka", "day": "2026-12-28", "weekday": null, "option": 10, "title": "Fajerwerki z farby", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Tworzy obraz rozbryzgów bez huku.", "materials": "czarny karton, farby, rolki po papierze nacięte na końcu (stemple)", "steps": ["Maczamy naciętą rolkę w farbie.", "Stemplujemy – wybuch kolorów.", "Różne kolory.", "Suszymy."], "easier": "Stemplowanie z pomocą.", "harder": "Samodzielnie wielokolorowo.", "variant_1y": "Stemplowanie z pomocą.", "variant_2_3y": "Samodzielnie wielokolorowo.", "song": "Stuk – fajerwerk czerwony, / stuk – niebieski, zielony! / Bez huku, bez bum – / kolorowy nowy rok tu!", "song_author": "własna (KMK/Malachim)", "safety": "Farby z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('577fc8c9-d4c9-5d6a-911e-af26e30b5f38','Samoobsługa','Sprzątamy po zabawie',false,false,'2026-12-28','{"id": "2026-12-28-samoobsluga", "day": "2026-12-28", "weekday": null, "option": 11, "title": "Sprzątamy po zabawie", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Odkłada zabawki na miejsce.", "materials": "kosze z obrazkami zabawek", "steps": ["Po zabawie mówimy: sprzątamy.", "Każdy zbiera 3 zabawki.", "Wkłada do kosza z obrazkiem.", "Brawo."], "easier": "1 zabawka z pomocą.", "harder": "Sortowanie wg obrazka.", "variant_1y": "1 zabawka z pomocą.", "variant_2_3y": "Sortowanie wg obrazka.", "song": "Klocek do klocków, miś do misiów, / piłka do piłek – w sali jest czysto! / Sprzątam, sprzątam – raz, dwa, trzy – / porządek w nowym roku – ty!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('71371689-1e71-5f38-bb16-23a02556af05','Język/logorytmika','Ti-ki ta-ki',false,false,'2026-12-28','{"id": "2026-12-28-jezyk-logorytmika", "day": "2026-12-28", "weekday": null, "option": 12, "title": "Ti-ki ta-ki", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy sylaby zegara.", "materials": "brak", "steps": ["Mówimy tik-tak.", "Ti-ki ta-ki szybciej.", "Bim-bam powoli.", "Łączymy z ruchem głowy."], "easier": "Tik-tak.", "harder": "Ti-ki ta-ki.", "variant_1y": "Tik-tak.", "variant_2_3y": "Ti-ki ta-ki.", "song": "Tik-tak, tik-tak, / ti-ki ta-ki, ti-ki tak, / bim-bam, bim-bam – / zegar mówi: Nowy Rok – tam!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e20ca0f2-1a16-569b-bfc2-55af09c72790','Zabawy paluszkowe i masażyki','Zegar na plecach',false,false,'2026-12-28','{"id": "2026-12-28-zabawy-paluszkowe-i-masazyki", "day": "2026-12-28", "weekday": null, "option": 13, "title": "Zegar na plecach", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Masażyk z rymowanką.", "materials": "brak", "steps": ["Wskazówki – palec chodzi kółkiem.", "Tik-tak – stukamy.", "Bije godzina – lekkie klepnięcia.", "Budzik – łaskotki."], "easier": "Lekko.", "harder": "Koledze.", "variant_1y": "Lekko.", "variant_2_3y": "Koledze.", "song": "Wskazówka chodzi w kółeczko, / tik-tak – stuka paluszkiem, / bim, bam – bije godzina, / dzyń! – budzik – łaskotki zaczyna!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b81851fb-88d0-5414-81c5-4acc9185314e','Zabawy słowno-ruchowe i rymowanki','Raz, dwa, trzy – Nowy Rok!',false,false,'2026-12-28','{"id": "2026-12-28-zabawy-slowno-ruchowe-i-rymowanki", "day": "2026-12-28", "weekday": null, "option": 14, "title": "Raz, dwa, trzy – Nowy Rok!", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Odlicza i skacze.", "materials": "brak", "steps": ["Kucamy.", "Odliczamy: 3, 2, 1.", "Wyskakujemy w górę: „Nowy Rok!”.", "Machamy rękami."], "easier": "Z opiekunką.", "harder": "Samodzielnie odlicza.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Samodzielnie odlicza.", "song": "Trzy – kucamy, / dwa – czekamy, / jeden – gotowi – / Nowy Rok! Hop – witamy!", "song_author": "własna (KMK/Malachim)", "safety": "Skok na macie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f9dc5bc6-8140-572a-96b6-7fe6860805db','Powitania i integracja','Witamy Nowy Rok',false,false,'2026-12-28','{"id": "2026-12-28-powitania-i-integracja", "day": "2026-12-28", "weekday": null, "option": 15, "title": "Witamy Nowy Rok", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Wita się i życzy.", "materials": "brak", "steps": ["Siadamy w kole.", "Każdemu mówimy: szczęśliwego nowego roku.", "Podajemy dłoń/piątkę.", "Klaszczemy."], "easier": "Piątka z opiekunką.", "harder": "Mówi życzenie.", "variant_1y": "Piątka z opiekunką.", "variant_2_3y": "Mówi życzenie.", "song": "Szczęśliwego nowego roku, / zdrowia, radości na każdym kroku! / (imię) – piątka, raz, dwa, trzy, / witaj w nowym roku – ty!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fbac3aec-0919-5c2a-942d-8f8bd3ed0d7f','Świadomość ciała','Rosnę!',false,false,'2026-12-28','{"id": "2026-12-28-swiadomosc-ciala", "day": "2026-12-28", "weekday": null, "option": 16, "title": "Rosnę!", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Porównuje wzrost.", "materials": "miarka na ścianie, kreska z września", "steps": ["Mierzymy wzrost.", "Porównujemy z kreską z września.", "Mówimy: urosłeś!", "Pokazujemy, co urosło: nogi, ręce."], "easier": "Mierzenie.", "harder": "Porównanie.", "variant_1y": "Mierzenie.", "variant_2_3y": "Porównanie.", "song": "We wrześniu kreska tu była, / teraz wyżej – co za siła! / Rosnę, rosnę – ręce, nogi – / już duży jestem – patrz na mnie!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('9b4f5cfd-734f-553e-ab14-552f5ae0a75a','Pamięć/uwaga/naśladowanie','Powtórz rytm',false,false,'2026-12-28','{"id": "2026-12-28-pamiec-uwaga-nasladowanie", "day": "2026-12-28", "weekday": null, "option": 17, "title": "Powtórz rytm", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy pamięć słuchową.", "materials": "bębenek", "steps": ["Opiekunka gra 2 uderzenia.", "Dzieci klaszczą 2 razy.", "Potem 3.", "Szybko – wolno."], "easier": "1–2 uderzenia.", "harder": "3–4 uderzenia.", "variant_1y": "1–2 uderzenia.", "variant_2_3y": "3–4 uderzenia.", "song": "Bum, bum – klap, klap, / bum, bum, bum – klap, klap, klap! / Słucham, pamiętam, powtarzam – / rytm w moich rączkach się nie zatarł!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3acb629c-f9e5-5010-a113-70bd0f0a072c','Zabawy poznawcze','Dzień i noc',false,false,'2026-12-28','{"id": "2026-12-28-zabawy-poznawcze", "day": "2026-12-28", "weekday": null, "option": 18, "title": "Dzień i noc", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Odróżnia dzień od nocy.", "materials": "obrazki: słońce, księżyc, czynności", "steps": ["Pokaż słońce i księżyc.", "Co robimy w dzień? bawimy się.", "W nocy? śpimy.", "Sortujemy obrazki."], "easier": "Wskazanie.", "harder": "Sortowanie.", "variant_1y": "Wskazanie.", "variant_2_3y": "Sortowanie.", "song": "Słonko świeci – dzień, wstaję, / księżyc świeci – noc, zasypiam. / Bawię się w dzień, śpię w nocy – / tak mija rok, tak mija czas!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('325d2679-f6cd-5e37-95b9-72b41867fa93','Zabawy na dworze','Mroźny spacer',false,false,'2026-12-28','{"id": "2026-12-28-zabawy-na-dworze", "day": "2026-12-28", "weekday": null, "option": 19, "title": "Mroźny spacer", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Ruch na mrozie.", "materials": "ciepłe ubranie", "steps": ["Spacer.", "Chuchamy – para.", "Tupiemy, by było ciepło.", "Szukamy lodu (oglądamy, nie wchodzimy)."], "easier": "W wózku.", "harder": "Pieszo.", "variant_1y": "W wózku.", "variant_2_3y": "Pieszo.", "song": "Chuch – para z buzi, / tup, tup – ciepło w nóżki! / Lód na kałuży – patrz, nie wchodź – / spacerujemy w nowy rok!", "song_author": "własna (KMK/Malachim)", "safety": "Omijamy lód; krótko przy mrozie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('58f3f0c7-a492-59d7-ae9b-9cd09f62a2dd','Higiena','Zdrowo w nowym roku – picie wody',false,false,'2026-12-28','{"id": "2026-12-28-higiena", "day": "2026-12-28", "weekday": null, "option": 20, "title": "Zdrowo w nowym roku – picie wody", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Uczy picia wody.", "materials": "kubki z wodą", "steps": ["Pytamy: co pijemy, gdy chce się pić?", "Woda!", "Pijemy z kubka.", "Odstawiamy."], "easier": "Z pomocą.", "harder": "Sam.", "variant_1y": "Z pomocą.", "variant_2_3y": "Sam.", "song": "Gul, gul, gul – woda w kubeczku, / piję, piję – zdrowo w brzuszku! / Odstawiam kubek – stuk, / zdrowy rok – gul, gul, gul!", "song_author": "własna (KMK/Malachim)", "safety": "Kubki niekapki / plastikowe.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c358702a-ee22-5a18-8e32-4b3756eff578','Czytanie dziecku','Stary rok i Nowy Rok (opowiadanie)',false,false,'2026-12-28','{"id": "2026-12-28-czytanie-dziecku", "day": "2026-12-28", "weekday": null, "option": 21, "title": "Stary rok i Nowy Rok (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii o zmianie.", "materials": "2 pacynki: dziadek-Stary Rok, dziecko-Nowy Rok", "steps": ["Stary Rok mówi: zmęczyłem się, idę spać.", "Przychodzi mały Nowy Rok: będę z wami!", "Dzieci machają Staremu Rokowi.", "Witają Nowy."], "easier": "Machanie.", "harder": "Opowiedzenie.", "variant_1y": "Machanie.", "variant_2_3y": "Opowiedzenie.", "song": "Stary Roku, pa, pa, pa, / dziękujemy, śpij już sam. / Nowy Roku – witaj, hej, / bądź wesoły, cieszymy się!", "song_author": "własna (KMK/Malachim)", "safety": "Pacynki bez drobnych elementów.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('38ace3ef-99c6-5a8f-9e33-74fc15bc4e0a','Klocki/budowanie','Wieża zegarowa',false,false,'2026-12-28','{"id": "2026-12-28-klocki-budowanie", "day": "2026-12-28", "weekday": null, "option": 22, "title": "Wieża zegarowa", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje wysoką wieżę.", "materials": "duże klocki, papierowy zegar", "steps": ["Budujemy wieżę.", "Na górę zegar.", "Bije północ – burzymy.", "Odbudowujemy."], "easier": "Burzenie.", "harder": "Budowanie.", "variant_1y": "Burzenie.", "variant_2_3y": "Budowanie.", "song": "Klocek, klocek – rośnie wieża, / zegar na górze – tik-tak, sprawdza! / Bim-bam – północ – bęc! / Odbudujemy – hej!", "song_author": "własna (KMK/Malachim)", "safety": "Klocki lekkie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3e14a1c8-1923-5bb8-9b2a-39b6d1c20eac','Wyciszenie','Po zabawie – sen',false,false,'2026-12-28','{"id": "2026-12-28-wyciszenie", "day": "2026-12-28", "weekday": null, "option": 23, "title": "Po zabawie – sen", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza po hałasie.", "materials": "koc", "steps": ["Leżymy.", "Oddychamy wolno.", "Liczymy wolno do 5.", "Cisza."], "easier": "Przy opiekunce.", "harder": "Samodzielnie.", "variant_1y": "Przy opiekunce.", "variant_2_3y": "Samodzielnie.", "song": "Głośno było – teraz cicho, / leżę, leżę, oddech wolny. / Raz… dwa… trzy… / nowy rok śpi – ja i ty.", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('102f2b19-f52f-53d6-b15b-9b7856122630','Empatia','Postanowienie: pomagam',false,false,'2026-12-28','{"id": "2026-12-28-empatia", "day": "2026-12-28", "weekday": null, "option": 24, "title": "Postanowienie: pomagam", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy prostego pomagania.", "materials": "brak", "steps": ["Mówimy: w nowym roku pomagamy.", "Pokazujemy, jak pomóc: podać, przytulić, posprzątać.", "Każde dziecko pomaga raz.", "Dziękujemy."], "easier": "Pomoc z opiekunką.", "harder": "Samodzielna pomoc.", "variant_1y": "Pomoc z opiekunką.", "variant_2_3y": "Samodzielna pomoc.", "song": "W nowym roku – pomagam ja, / podam, przytulę – raz i dwa! / Posprzątam klocki – proszę bardzo, / dobrzy ludzie się nie starzą!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('545ab28a-4e33-5673-a1f0-5d99a6a72a6e','Rodzina i dom','Jak witaliśmy Nowy Rok w domu?',false,false,'2026-12-28','{"id": "2026-12-28-rodzina-i-dom", "day": "2026-12-28", "weekday": null, "option": 25, "title": "Jak witaliśmy Nowy Rok w domu?", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Opowiada o domu.", "materials": "brak", "steps": ["Pytamy: co robiłeś w nowy rok?", "Spałeś? Słyszałeś huk?", "Kto był z tobą?", "Rysujemy razem."], "easier": "Słuchanie.", "harder": "Opowiadanie.", "variant_1y": "Słuchanie.", "variant_2_3y": "Opowiadanie.", "song": "W moim domu w nowy rok – / mama, tata, ja i kot! / Spałem? Nie spałem? – kto to wie, / szczęśliwi razem – hej, hej, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('57f65f6c-0abb-506f-90a2-4573753b3ceb','Pory roku i święta','Trzech Króli – korony',false,false,'2026-12-28','{"id": "2026-12-28-pory-roku-i-swieta", "day": "2026-12-28", "weekday": null, "option": 26, "title": "Trzech Króli – korony", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Poznaje święto 6 stycznia.", "materials": "korony z kartonu", "steps": ["Mówimy: przyszli królowie z darami.", "Zakładamy korony.", "Idziemy w orszaku po sali.", "Śpiewamy."], "easier": "Korona z pomocą.", "harder": "Orszak samodzielnie.", "variant_1y": "Korona z pomocą.", "variant_2_3y": "Orszak samodzielnie.", "song": "Idą królowie w koronach, / niosą dary – patrz, z daleka! / Tup, tup – orszak idzie, / złota gwiazda prowadzi!", "song_author": "własna (KMK/Malachim)", "safety": "Korony z kartonu bez gumki ciasnej; bez brokatu sypkiego.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ce2e9153-a1a6-5e83-b9a7-af4f35c10691','Kolory/kształty/wielkości','Kolorowy kalendarz',false,false,'2026-12-28','{"id": "2026-12-28-kolory-ksztalty-wielkosci", "day": "2026-12-28", "weekday": null, "option": 27, "title": "Kolorowy kalendarz", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Poznaje cyfry 1–3 i kolory.", "materials": "duże cyfry z kartonu w kolorach", "steps": ["Pokazujemy 1, 2, 3.", "Każda cyfra ma kolor.", "Kładziemy tyle klocków.", "Nazywamy kolor."], "easier": "1 cyfra.", "harder": "3 cyfry.", "variant_1y": "1 cyfra.", "variant_2_3y": "3 cyfry.", "song": "Jeden – czerwony, / dwa – niebieskie, / trzy – zielone, / liczymy, kolorujemy – nowy rok wesoły!", "song_author": "własna (KMK/Malachim)", "safety": "Karton.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Nowy Rok – dzwonki i dźwięki", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('dfbad7dd-3f14-5a7c-8fb6-4bb360ab0b1f','Ruch','Jazda na sankach',false,false,'2027-01-04','{"id": "2027-01-04-ruch", "day": "2027-01-04", "weekday": null, "option": 1, "title": "Jazda na sankach", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy równowagę siedząc i ciągnięcie.", "materials": "koc lub duży karton, miękka mata", "steps": ["Dziecko siada na kocu – sanki.", "Opiekunka powoli ciągnie po macie.", "Zakręt – przechylamy się.", "Stop – wysiadamy."], "easier": "Opiekunka ciągnie bardzo wolno, dziecko trzymane.", "harder": "Dziecko ciągnie misia na kocu.", "variant_1y": "Opiekunka ciągnie bardzo wolno, dziecko trzymane.", "variant_2_3y": "Dziecko ciągnie misia na kocu.", "song": "Jadę, jadę na saneczkach, / zakręt – w lewo, ojej, mamusiu! / W prawo, prosto – szu, szu, szu – / stop! Wysiadam – jestem tu!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko po miękkiej macie, wolno; z dala od mebli.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a718fc79-6fd3-55f4-8f4f-e66a681f82cf','Muzyka','Piosenka bałwanka',false,false,'2027-01-04','{"id": "2027-01-04-muzyka", "day": "2027-01-04", "weekday": null, "option": 2, "title": "Piosenka bałwanka", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Śpiewa i pokazuje.", "materials": "brak", "steps": ["Uczymy piosenki.", "Pokazujemy: brzuch, głowa, nos.", "Śpiewamy szybciej.", "Bałwanek topnieje – kładziemy się."], "easier": "Pokazywanie.", "harder": "Śpiewanie.", "variant_1y": "Pokazywanie.", "variant_2_3y": "Śpiewanie.", "song": "Stoi bałwan, gruby brzuch, / głowa okrągła, z marchewki nos, ruch! / Słonko grzeje – kap, kap, kap – / bałwan leży – plask!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d2e1adfd-ee9d-58d9-ac24-b423d5e0558d','Sensoryka','Kulki śnieżne z waty',false,false,'2027-01-04','{"id": "2027-01-04-sensoryka", "day": "2027-01-04", "weekday": null, "option": 3, "title": "Kulki śnieżne z waty", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Doświadcza miękkich kul.", "materials": "duże kule z pianki lub zwinięte białe skarpety (miękkie śnieżki)", "steps": ["Rzucamy miękkie śnieżki do kosza.", "Ściskamy.", "Toczymy.", "Bitwa delikatna – w nogi."], "easier": "Ściskanie, toczenie.", "harder": "Rzut do kosza.", "variant_1y": "Ściskanie, toczenie.", "variant_2_3y": "Rzut do kosza.", "song": "Miękka śnieżka – ściśnij ją, / rzuć do kosza – bęc, hop, hop! / Nie w buzię, nie w oczy – w nóżki, / zimowe mamy zabawki!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko miękkie duże kule; nie celujemy w głowę; wata luzem nie (do buzi).", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('30163701-8ffd-585b-a35e-d7ae21e6daf7','Emocje','Zimowa złość',false,false,'2027-01-04','{"id": "2027-01-04-emocje", "day": "2027-01-04", "weekday": null, "option": 4, "title": "Zimowa złość", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Uczy radzenia sobie ze złością.", "materials": "brak", "steps": ["Opowiadamy: Kubie spadła czapka w śnieg – złość!", "Pokazujemy złą minę.", "Co robimy? Tupnięcie, głęboki oddech.", "Uśmiech."], "easier": "Oddech z opiekunką.", "harder": "Nazywa złość.", "variant_1y": "Oddech z opiekunką.", "variant_2_3y": "Nazywa złość.", "song": "Grrr – jestem zły, tupię: tup, / głęboki wdech – fff – i już! / Złość odleciała jak płatek śniegu, / wracam do zabawy w biegu!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a227de7e-49dc-58ed-94d7-6a5a9ad5c52c','Zmysły','Lód, śnieg, woda',false,false,'2027-01-04','{"id": "2027-01-04-zmysly", "day": "2027-01-04", "weekday": null, "option": 5, "title": "Lód, śnieg, woda", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Porównuje stany wody.", "materials": "lód, śnieg, woda w 3 miskach", "steps": ["Dotykamy lodu – twardy.", "Śniegu – sypki.", "Wody – mokra.", "Mówimy różnice."], "easier": "Dotyk krótki.", "harder": "Nazywanie.", "variant_1y": "Dotyk krótki.", "variant_2_3y": "Nazywanie.", "song": "Lód – twardy, stuk, stuk, / śnieg – sypki, szur, szur, / woda – mokra, chlup, chlup – / wszystko to jest woda – hop!", "song_author": "własna (KMK/Malachim)", "safety": "Krótko; nie do buzi; ręcznik.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2c1d69a1-c916-5a9a-a6f1-74fce39040d4','Zwierzęta','Pingwiny na lodzie',false,false,'2027-01-04','{"id": "2027-01-04-zwierzeta", "day": "2027-01-04", "weekday": null, "option": 6, "title": "Pingwiny na lodzie", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Naśladuje chód pingwina.", "materials": "brak", "steps": ["Pokazujemy pingwina.", "Chodzimy małymi kroczkami, ręce przy ciele.", "Ślizgamy się na brzuchu (mata).", "Pingwiny stoją razem – ciepło."], "easier": "Drepanie za rękę.", "harder": "Ślizganie na macie.", "variant_1y": "Drepanie za rękę.", "variant_2_3y": "Ślizganie na macie.", "song": "Drepcze pingwin – drep, drep, drep, / ślizga się na brzuszku – hep! / Pingwiny razem stoją w krąg – / ciepło nam jest, wszyscy w krąg!", "song_author": "własna (KMK/Malachim)", "safety": "Mata miękka.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2352dced-7909-5ae9-b5d4-595872b466b4','Pogoda','Śnieżyca',false,false,'2027-01-04','{"id": "2027-01-04-pogoda", "day": "2027-01-04", "weekday": null, "option": 7, "title": "Śnieżyca", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Poznaje silny śnieg i wiatr.", "materials": "białe chusty, wachlarz z kartonu", "steps": ["Opiekunka macha wachlarzem – wiatr.", "Dzieci rzucają chusty – śnieg.", "Śnieżyca – wszyscy się kręcą (raz).", "Cisza – leżymy."], "easier": "Patrzenie.", "harder": "Udział.", "variant_1y": "Patrzenie.", "variant_2_3y": "Udział.", "song": "Wieje, wieje, sypie, sypie – / śnieżyca tańczy, nic nie widzi! / Kręci się, kręci – raz i stop, / spokój – śnieg leży – hop!", "song_author": "własna (KMK/Malachim)", "safety": "Jeden obrót.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('3e48e22f-1824-5516-865f-b37e5249957d','Przyroda','Ślady zwierząt na śniegu',false,false,'2027-01-04','{"id": "2027-01-04-przyroda", "day": "2027-01-04", "weekday": null, "option": 8, "title": "Ślady zwierząt na śniegu", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Rozpoznaje tropy.", "materials": "obrazki tropów: ptak, pies, zając", "steps": ["Pokazujemy tropy.", "Dopasowujemy do zwierząt.", "Na dworze szukamy śladów.", "Robimy swoje ślady."], "easier": "Wskazanie.", "harder": "Dopasowanie.", "variant_1y": "Wskazanie.", "variant_2_3y": "Dopasowanie.", "song": "Kto tu chodził? Ptak – trzy palce, / pies – łapki, zając – skoki! / A ja? Bucik – tup, tup, tup – / moje ślady obok – hop!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('86950b0b-14d6-5153-9ef0-26e35bb52a02','Eksperymenty','Kolorowy lód',false,false,'2027-01-04','{"id": "2027-01-04-eksperymenty", "day": "2027-01-04", "weekday": null, "option": 9, "title": "Kolorowy lód", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje barwienie i topnienie.", "materials": "lód z barwnikiem (przygotowany wcześniej, duże bryły), taca", "steps": ["Pokazujemy kolorowe bryły lodu.", "Kładziemy na tacy.", "Topnieje – kolorowa woda.", "Mieszamy kolory."], "easier": "Patrzenie.", "harder": "Nazywanie kolorów.", "variant_1y": "Patrzenie.", "variant_2_3y": "Nazywanie kolorów.", "song": "Lód czerwony, lód niebieski, / topi się – kap, kap – na tacy! / Kolory się mieszają – fiolet! / Zimowa magia – oj, co to jest?", "song_author": "własna (KMK/Malachim)", "safety": "Duże bryły; barwnik spożywczy; nie lizać.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5a066127-5c37-56c6-be98-6bc4732b640a','Plastyka','Bałwanek z kółek',false,false,'2027-01-04','{"id": "2027-01-04-plastyka", "day": "2027-01-04", "weekday": null, "option": 10, "title": "Bałwanek z kółek", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Nakleja koła.", "materials": "koła z białego papieru (3 wielkości), niebieski karton, klej w sztyfcie u opiekunki", "steps": ["Duże koło na dół.", "Średnie na środek.", "Małe – głowa.", "Dorysowujemy oczy, nos."], "easier": "Przyklejanie z pomocą.", "harder": "Układanie w kolejności.", "variant_1y": "Przyklejanie z pomocą.", "variant_2_3y": "Układanie w kolejności.", "song": "Duże koło – brzuch bałwana, / średnie – piersi, małe – głowa! / Oczka, nosek, uśmiech – już, / bałwanek gotowy – tu!", "song_author": "własna (KMK/Malachim)", "safety": "Klej u opiekunki.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f9ff5df7-fae8-5990-856f-1c9ba49dc34b','Samoobsługa','Sam rozpinam kurtkę',false,false,'2027-01-04','{"id": "2027-01-04-samoobsluga", "day": "2027-01-04", "weekday": null, "option": 11, "title": "Sam rozpinam kurtkę", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy rozpinanie zamka.", "materials": "kurtki dzieci", "steps": ["Po spacerze stoimy przy szafce.", "Łapiemy suwak.", "Ciągniemy w dół.", "Zdejmujemy kurtkę i wieszamy."], "easier": "Opiekunka rozpoczyna.", "harder": "Dziecko samo.", "variant_1y": "Opiekunka rozpoczyna.", "variant_2_3y": "Dziecko samo.", "song": "Suwak w dół – zzzip, zzzip, / kurtka otwarta – hop, ciach! / Rączki z rękawów – raz i dwa, / na haczyk – kurtka ma!", "song_author": "własna (KMK/Malachim)", "safety": "Uwaga na brodę przy zamku.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('40652d9c-63ed-5dcf-9c43-fb7254999f31','Język/logorytmika','Sanki jadą',false,false,'2027-01-04','{"id": "2027-01-04-jezyk-logorytmika", "day": "2027-01-04", "weekday": null, "option": 12, "title": "Sanki jadą", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy głoski s, sz.", "materials": "brak", "steps": ["Sanki: sss.", "Śnieg: szszsz.", "Zjazd z górki: łiii.", "Hamowanie: stop."], "easier": "Łiii i stop.", "harder": "Sss i szszsz.", "variant_1y": "Łiii i stop.", "variant_2_3y": "Sss i szszsz.", "song": "Sss – sanki suną, / szszsz – śnieg szumi, / łiii – z górki w dół, / stop! – wysiadam już!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2b18275d-8a61-5f44-b7db-8b98e647c057','Zabawy paluszkowe i masażyki','Bałwanek na brzuszku',false,false,'2027-01-04','{"id": "2027-01-04-zabawy-paluszkowe-i-masazyki", "day": "2027-01-04", "weekday": null, "option": 13, "title": "Bałwanek na brzuszku", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Masażyk.", "materials": "brak", "steps": ["Rysujemy duże koło na brzuszku.", "Mniejsze.", "Kropki – oczy.", "Przytulamy."], "easier": "Lekko.", "harder": "Na misiu.", "variant_1y": "Lekko.", "variant_2_3y": "Na misiu.", "song": "Kółko duże, kółko małe, / dwa oczka – kropka, kropka, / nosek – pyk, / bałwanek się śmieje – hyc!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f8d93519-50ee-50d1-bef7-59c115c02bf1','Zabawy słowno-ruchowe i rymowanki','Zjeżdżamy z górki',false,false,'2027-01-04','{"id": "2027-01-04-zabawy-slowno-ruchowe-i-rymowanki", "day": "2027-01-04", "weekday": null, "option": 14, "title": "Zjeżdżamy z górki", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Ruch wznoszenia i opadania.", "materials": "brak", "steps": ["Wchodzimy na górkę – kroki w miejscu wysoko.", "Siadamy na sankach.", "Zjazd – łiii – ręce w górę.", "Na dole – śmiech."], "easier": "Naśladowanie.", "harder": "Mówienie.", "variant_1y": "Naśladowanie.", "variant_2_3y": "Mówienie.", "song": "Na górkę – tup, tup, tup, / siadam na sanki – hop! / Łiii – w dół, w dół, / ha, ha, ha – i od nowa już!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('50086e6a-e2d5-5e6a-9d95-0b38762fa6bc','Powitania i integracja','Ciepłe powitanie',false,false,'2027-01-04','{"id": "2027-01-04-powitania-i-integracja", "day": "2027-01-04", "weekday": null, "option": 15, "title": "Ciepłe powitanie", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Wita się gestem ogrzewania.", "materials": "brak", "steps": ["Siadamy w kole.", "Pocieramy dłonie – ciepło.", "Dajemy ciepłe dłonie sąsiadowi.", "Mówimy dzień dobry."], "easier": "Z opiekunką.", "harder": "Samodzielnie.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Samodzielnie.", "song": "Pocieram rączki – ciepło, ciepło, / daję tobie – dzień dobry, kolego! / Ciepłe rączki, ciepły dzień – / zimą razem – hej, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e3580e76-208c-557e-8975-e4e35d8210d1','Świadomość ciała','Zamarznięty – roztopiony',false,false,'2027-01-04','{"id": "2027-01-04-swiadomosc-ciala", "day": "2027-01-04", "weekday": null, "option": 16, "title": "Zamarznięty – roztopiony", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Napina i rozluźnia ciało.", "materials": "brak", "steps": ["Zamarzamy – sztywni jak lód.", "Słońce – rozluźniamy się powoli.", "Topniejemy na podłogę.", "Powtarzamy."], "easier": "Z opiekunką.", "harder": "Samodzielnie.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Samodzielnie.", "song": "Zamarzam – sztywny jak lód, / słonko grzeje – miękki już! / Topię się, topię – plask na dół, / kałużą jestem – i już!", "song_author": "własna (KMK/Malachim)", "safety": "Powolne opadanie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('9a7dd669-e2b6-5f7b-8ce0-555e0919eddb','Pamięć/uwaga/naśladowanie','Ubierz bałwanka jak ja',false,false,'2027-01-04','{"id": "2027-01-04-pamiec-uwaga-nasladowanie", "day": "2027-01-04", "weekday": null, "option": 17, "title": "Ubierz bałwanka jak ja", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Naśladuje układ.", "materials": "2 bałwanki z filcu, szaliki, czapki filcowe", "steps": ["Opiekunka ubiera swojego bałwanka.", "Dziecko patrzy.", "Ubiera swojego tak samo.", "Porównujemy."], "easier": "1 element.", "harder": "3 elementy.", "variant_1y": "1 element.", "variant_2_3y": "3 elementy.", "song": "Czapka czerwona, szalik zielony – / patrz, zapamiętaj, ubierz swojego! / Taki sam? Tak! Brawo, ty – / bliźniaki bałwanki: raz, dwa, trzy!", "song_author": "własna (KMK/Malachim)", "safety": "Filc duży.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('ec65925a-4dc3-5d6f-a5d3-4983909854fe','Zabawy poznawcze','Co jest zimowe?',false,false,'2027-01-04','{"id": "2027-01-04-zabawy-poznawcze", "day": "2027-01-04", "weekday": null, "option": 18, "title": "Co jest zimowe?", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Klasyfikuje rzeczy wg pory roku.", "materials": "obrazki: sanki, czapka, kąpielówki, lody, bałwan", "steps": ["Pokaż obrazki.", "Pytamy: zimą czy latem?", "Sortujemy.", "Śmiejemy się z kąpielówek zimą."], "easier": "Wskazanie zimowych.", "harder": "Sortowanie.", "variant_1y": "Wskazanie zimowych.", "variant_2_3y": "Sortowanie.", "song": "Sanki – zimą, czapka – zimą, / kąpielówki? Latem, ha! / Bałwanek – zimą, lody – latem – / sortujemy z całym światem!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c9a0013e-8cf5-510b-bd6f-b6d712038400','Zabawy na dworze','Lepimy bałwana',false,false,'2027-01-04','{"id": "2027-01-04-zabawy-na-dworze", "day": "2027-01-04", "weekday": null, "option": 19, "title": "Lepimy bałwana", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Współpracuje przy budowie.", "materials": "ciepłe, nieprzemakalne rękawiczki, marchewka (pokaz), kamyki duże – tylko do bałwana", "steps": ["Toczymy kulę ze śniegu.", "Druga mniejsza.", "Głowa.", "Ozdabiamy (dorosły nakłada oczy)."], "easier": "Pomaganie przy toczeniu.", "harder": "Toczenie samodzielne.", "variant_1y": "Pomaganie przy toczeniu.", "variant_2_3y": "Toczenie samodzielne.", "song": "Toczymy kulę – ciężka, wielka, / druga mniejsza, głowa – na górze / oczy, nos – bałwan stoi, / nikt się zimy nie boi!", "song_author": "własna (KMK/Malachim)", "safety": "Rękawiczki nieprzemakalne; krótko; nie jemy śniegu; drobne ozdoby tylko w ręku dorosłego.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0961ee8b-0427-5aa5-8379-2d61c9d4dc3f','Higiena','Suche ubranie po spacerze',false,false,'2027-01-04','{"id": "2027-01-04-higiena", "day": "2027-01-04", "weekday": null, "option": 20, "title": "Suche ubranie po spacerze", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Uczy przebierania mokrych rzeczy.", "materials": "zapasowe ubrania", "steps": ["Sprawdzamy: mokre rękawiczki? skarpetki?", "Zdejmujemy.", "Zakładamy suche.", "Mokre na kaloryfer."], "easier": "Opiekunka przebiera.", "harder": "Dziecko pomaga.", "variant_1y": "Opiekunka przebiera.", "variant_2_3y": "Dziecko pomaga.", "song": "Mokra skarpeta – fe, zimno, / sucha skarpeta – ach, ciepło! / Przebieram się – raz i dwa, / na kaloryfer – mokre schną!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('72789e4c-b4c0-5694-a682-22b1d190f87a','Czytanie dziecku','Bałwanek, który chciał się ogrzać (opowiadanie)',false,false,'2027-01-04','{"id": "2027-01-04-czytanie-dziecku", "day": "2027-01-04", "weekday": null, "option": 21, "title": "Bałwanek, który chciał się ogrzać (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii z humorem.", "materials": "obrazki", "steps": ["Opowiadaj: „Bałwanek zmarzł i chciał wejść do domu. Dzieci powiedziały: zostań na dworze, bo się roztopisz! Dały mu szalik”.", "Pokazuj obrazki.", "Pytamy: czemu nie może wejść?", "Dajemy szalik bałwankowi z filcu."], "easier": "Słuchanie.", "harder": "Odpowiedź.", "variant_1y": "Słuchanie.", "variant_2_3y": "Odpowiedź.", "song": "Bałwanku, nie wchodź – roztopisz się! / Damy ci szalik – ciepło ci? Hej! / Zostań na dworze, w śniegu, w mrozie – / będziemy się bawić przy twoim nosie!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('059756a4-2ee6-50f0-b11b-de56db5744e1','Klocki/budowanie','Górka dla sanek',false,false,'2027-01-04','{"id": "2027-01-04-klocki-budowanie", "day": "2027-01-04", "weekday": null, "option": 22, "title": "Górka dla sanek", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje pochylnię.", "materials": "duże klocki, deska z tektury, autka/sanki zabawkowe", "steps": ["Budujemy podwyższenie.", "Kładziemy tekturę skośnie.", "Zjeżdżamy autkiem.", "Wyżej – szybciej."], "easier": "Puszczanie autka.", "harder": "Budowanie.", "variant_1y": "Puszczanie autka.", "variant_2_3y": "Budowanie.", "song": "Klocek, klocek – górka rośnie, / sanki zjeżdżają radośnie! / Wyżej – szybciej, niżej – wolno, / zjeżdżamy razem – swobodnie!", "song_author": "własna (KMK/Malachim)", "safety": "Zabawki duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('987e9990-0a60-5465-997a-c75104399eba','Wyciszenie','Anioł w śniegu',false,false,'2027-01-04','{"id": "2027-01-04-wyciszenie", "day": "2027-01-04", "weekday": null, "option": 23, "title": "Anioł w śniegu", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza leżąc.", "materials": "mata", "steps": ["Leżymy na plecach.", "Powoli ruszamy rękami i nogami – anioł.", "Zatrzymujemy się.", "Leżymy cicho."], "easier": "Z opiekunką.", "harder": "Samodzielnie.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Samodzielnie.", "song": "Leżę w śniegu – ręce w bok, / nogi w bok – aniołek: hop. / Cicho, wolno, leżę już, / śnieżny aniołek śpi.", "song_author": "własna (KMK/Malachim)", "safety": "Odstęp między dziećmi.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('11f4ab11-d381-57cf-8728-f824dcb8c36e','Empatia','Pomagam wstać',false,false,'2027-01-04','{"id": "2027-01-04-empatia", "day": "2027-01-04", "weekday": null, "option": 24, "title": "Pomagam wstać", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy pomagania.", "materials": "brak", "steps": ["Opowiadamy: Ola przewróciła się na śniegu.", "Co robimy? Podajemy rękę.", "Ćwiczymy z misiem.", "Pytamy: czy wszystko dobrze?"], "easier": "Z misiem.", "harder": "Z kolegą.", "variant_1y": "Z misiem.", "variant_2_3y": "Z kolegą.", "song": "Bęc! – przewrócił się kolega, / podaję rękę – wstań, nie zwlekaj! / Wszystko dobrze? Tak! Hura! / Pomagamy – to jest kultura!", "song_author": "własna (KMK/Malachim)", "safety": "Delikatnie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('64ce374a-9c5e-51f8-a140-9771167b1f78','Rodzina i dom','Zimowe zabawy z rodziną',false,false,'2027-01-04','{"id": "2027-01-04-rodzina-i-dom", "day": "2027-01-04", "weekday": null, "option": 25, "title": "Zimowe zabawy z rodziną", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Opowiada o weekendzie.", "materials": "brak", "steps": ["Pytamy: czy jeździłeś na sankach z tatą/mamą?", "Kto ciągnął?", "Lepiliście bałwana?", "Pokazujemy ruchem."], "easier": "Słuchanie.", "harder": "Opowiadanie.", "variant_1y": "Słuchanie.", "variant_2_3y": "Opowiadanie.", "song": "Tata ciągnie, mama pcha, / na saneczkach jadę ja! / Bałwan z babcią, śnieżki z bratem – / zimą bawi się z całym światem!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('71a598c9-d784-5114-a58f-41b350492352','Pory roku i święta','Zima w pełni',false,false,'2027-01-04','{"id": "2027-01-04-pory-roku-i-swieta", "day": "2027-01-04", "weekday": null, "option": 26, "title": "Zima w pełni", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Utrwala cechy zimy.", "materials": "obrazki", "steps": ["Co jest zimą? śnieg, sanki, mróz.", "Pokazujemy ruchem.", "Gramy w zgadywanie.", "Śpiewamy."], "easier": "Wskazanie.", "harder": "Nazywanie.", "variant_1y": "Wskazanie.", "variant_2_3y": "Nazywanie.", "song": "Zima, zima – śnieg i lód, / sanki, bałwan, mroźny chłód! / Lubię zimę – hej, hej, hej, / bawię się z nią cały dzień!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fc1b1e2c-b895-5cfa-8b7a-6582d306592f','Kolory/kształty/wielkości','Kule małe, średnie, duże',false,false,'2027-01-04','{"id": "2027-01-04-kolory-ksztalty-wielkosci", "day": "2027-01-04", "weekday": null, "option": 27, "title": "Kule małe, średnie, duże", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Porządkuje wielkości.", "materials": "3 piłki różnej wielkości (wszystkie > 5 cm)", "steps": ["Pokazujemy piłki – kule bałwana.", "Która duża?", "Układamy bałwana: duża na dole.", "Mówimy nazwy."], "easier": "Wskazanie dużej.", "harder": "Ułożenie 3.", "variant_1y": "Wskazanie dużej.", "variant_2_3y": "Ułożenie 3.", "song": "Duża na dół, średnia w środku, / mała na górę – bałwanek w porządku! / Raz, dwa, trzy – stoi ten, / bałwan z piłek – cały dzień!", "song_author": "własna (KMK/Malachim)", "safety": "Piłki duże.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Zimowe zabawy – sanki i bałwan", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('b2cb56a9-f8d5-5d21-99a2-57fcdc776fb7','Ruch','Ptaszki fruwają',false,false,'2027-01-11','{"id": "2027-01-11-ruch", "day": "2027-01-11", "weekday": null, "option": 1, "title": "Ptaszki fruwają", "type": "ruch", "category": "Ruch", "duration_min": "10-20", "goal": "Ćwiczy bieg i przysiad.", "materials": "obręcze lub maty – gniazda", "steps": ["Dzieci-ptaszki fruwają po sali.", "„Kot!” – uciekamy do gniazd.", "„Ziarenka!” – kucamy i dziobiemy palcami podłogę.", "Odpoczynek w gnieździe."], "easier": "Bieg za rękę.", "harder": "Reakcja na hasło.", "variant_1y": "Bieg za rękę.", "variant_2_3y": "Reakcja na hasło.", "song": "Fruwa ptaszek – fru, fru, fru, / dziobie ziarnka – dziób, dziób, dziób! / Kot się skrada – do gniazdka, hop! / Bezpieczny ptaszek – stop!", "song_author": "własna (KMK/Malachim)", "safety": "Obręcze płasko, przestrzeń wolna.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('41c31dfe-23c3-5865-9875-cc9fc501476f','Muzyka','Ptasi koncert',false,false,'2027-01-11','{"id": "2027-01-11-muzyka", "day": "2027-01-11", "weekday": null, "option": 2, "title": "Ptasi koncert", "type": "muzyka", "category": "Muzyka", "duration_min": "10-20", "goal": "Rozróżnia wysokie i niskie dźwięki.", "materials": "dzwonki/cymbałki z atestem", "steps": ["Wysokie dźwięki – sikorka, ręce w górze.", "Niskie – wrona, kucamy.", "Opiekunka gra, dzieci pokazują.", "Śpiewamy „ćwir”."], "easier": "Z opiekunką.", "harder": "Samodzielnie.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Samodzielnie.", "song": "Sikorka śpiewa wysoko: ćwir, / wrona nisko: kra, kra, kra! / Góra, dół – słuchaj, ptaszku, / koncert gra na naszym placyku!", "song_author": "własna (KMK/Malachim)", "safety": "Pałeczki krótkie, z kulką.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('0f0669f9-4b17-5652-869c-778a786e6908','Sensoryka','Piórka – miękkie, lekkie',false,false,'2027-01-11','{"id": "2027-01-11-sensoryka", "day": "2027-01-11", "weekday": null, "option": 3, "title": "Piórka – miękkie, lekkie", "type": "sensoryka", "category": "Sensoryka", "duration_min": "10-20", "goal": "Doświadcza lekkości.", "materials": "duże sztuczne pióra (u opiekunki), chusta", "steps": ["Głaszczemy piórkiem dłoń.", "Dmuchamy – leci.", "Kładziemy na chuście i podrzucamy.", "Liczymy pióra."], "easier": "Głaskanie.", "harder": "Dmuchanie i łapanie.", "variant_1y": "Głaskanie.", "variant_2_3y": "Dmuchanie i łapanie.", "song": "Piórko lekkie – fru, do góry, / piórko miękkie – głaszcze dłoń. / Dmuchnij, dmuchnij – leci w chmury, / złap je, złap – w swoją dłoń!", "song_author": "własna (KMK/Malachim)", "safety": "Pióra duże, nie do buzi; zbieramy po zabawie; alergie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('49f3be91-c469-52cd-ab74-0e120a389cc6','Emocje','Ptaszek się boi – ptaszek jest bezpieczny',false,false,'2027-01-11','{"id": "2027-01-11-emocje", "day": "2027-01-11", "weekday": null, "option": 4, "title": "Ptaszek się boi – ptaszek jest bezpieczny", "type": "emocje", "category": "Emocje", "duration_min": "10-20", "goal": "Nazywa strach i ulgę.", "materials": "pacynka ptaszka", "steps": ["Ptaszek drży – kot!", "Pytamy: co czuje?", "Chowamy ptaszka w dłoniach – bezpieczny.", "Ulga – uśmiech."], "easier": "Trzymanie pacynki.", "harder": "Nazwanie uczuć.", "variant_1y": "Trzymanie pacynki.", "variant_2_3y": "Nazwanie uczuć.", "song": "Ptaszek drży – kot blisko, ach! / Schowam go w dłoniach – nie ma strach! / Już bezpieczny – ćwir, ćwir, ćwir – / uśmiech wraca – ty i my!", "song_author": "własna (KMK/Malachim)", "safety": "Pacynka bez drobnych elementów.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a4a72b85-3b8b-5866-bc84-60556b8db698','Zmysły','Kto tak śpiewa?',false,false,'2027-01-11','{"id": "2027-01-11-zmysly", "day": "2027-01-11", "weekday": null, "option": 5, "title": "Kto tak śpiewa?", "type": "zmysly", "category": "Zmysły", "duration_min": "10-20", "goal": "Rozpoznaje głosy ptaków.", "materials": "nagrania: wróbel, sikorka, wrona, gołąb; obrazki", "steps": ["Odtwarzamy głos.", "Dzieci słuchają.", "Wskazują obrazek.", "Naśladują."], "easier": "2 głosy.", "harder": "4 głosy.", "variant_1y": "2 głosy.", "variant_2_3y": "4 głosy.", "song": "Ćwir – to wróbel, pin-pin – sikorka, / kra – to wrona, gru – gołąbek! / Słuchaj uszkiem – kto to śpiewa? / Ptaki siedzą na drzewach!", "song_author": "własna (KMK/Malachim)", "safety": "Cicho.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e70429ce-fc97-5cb0-8e61-5eb7d6fd704c','Zwierzęta','Wróbel, sikorka, gil',false,false,'2027-01-11','{"id": "2027-01-11-zwierzeta", "day": "2027-01-11", "weekday": null, "option": 6, "title": "Wróbel, sikorka, gil", "type": "zwierzeta", "category": "Zwierzęta", "duration_min": "10-20", "goal": "Poznaje ptaki zimujące.", "materials": "duże zdjęcia", "steps": ["Wróbel – brązowy, skacze.", "Sikorka – żółty brzuszek.", "Gil – czerwony brzuszek.", "Naśladujemy skoki wróbla."], "easier": "Wskazanie koloru.", "harder": "Nazwanie ptaka.", "variant_1y": "Wskazanie koloru.", "variant_2_3y": "Nazwanie ptaka.", "song": "Wróbel brązowy – hop, hop, hop, / sikorka żółta – pin-pin, stop! / Gil czerwony jak jabłuszko – / zimą przylatują do nas, słoneczko!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('37ca76d5-2afc-5571-80d7-409698b3eb9c','Pogoda','Ptaki i mróz',false,false,'2027-01-11','{"id": "2027-01-11-pogoda", "day": "2027-01-11", "weekday": null, "option": 7, "title": "Ptaki i mróz", "type": "pogoda", "category": "Pogoda", "duration_min": "10-20", "goal": "Łączy pogodę z życiem ptaków.", "materials": "obrazki", "steps": ["Pytamy: czy ptakom zimno?", "Ptaki puszą piórka – przytulamy się w kulkę.", "Słońce – rozkładamy skrzydła.", "Rozmawiamy o karmniku."], "easier": "Naśladowanie.", "harder": "Mówienie.", "variant_1y": "Naśladowanie.", "variant_2_3y": "Mówienie.", "song": "Mróz – ptaszek puszy piórka, / kulka z niego, mała kulka! / Słonko wyszło – rozpostrze skrzydła, / i poleci do karmnika!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('98eda533-7374-5b30-9987-74fbcf12defe','Przyroda','Karmnik za oknem',false,false,'2027-01-11','{"id": "2027-01-11-przyroda", "day": "2027-01-11", "weekday": null, "option": 8, "title": "Karmnik za oknem", "type": "przyroda", "category": "Przyroda", "duration_min": "10-20", "goal": "Obserwuje ptaki przy karmniku.", "materials": "karmnik przy oknie (napełnia dorosły), lornetka-zabawka z rolek", "steps": ["Siadamy przy oknie cicho.", "Patrzymy przez „lornetki”.", "Liczymy ptaki.", "Nazywamy kolory."], "easier": "Patrzenie na rękach.", "harder": "Liczenie.", "variant_1y": "Patrzenie na rękach.", "variant_2_3y": "Liczenie.", "song": "Cicho, cicho – ptaszek je, / przez lornetkę patrzę – hej! / Jeden, dwa – sikorki dwie, / smacznego, ptaszki – mniam, mniam, hej!", "song_author": "własna (KMK/Malachim)", "safety": "Ziarno, słonina i orzechy tylko u dorosłych (zadławienie, alergia); okno zamknięte.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e05ccea0-7720-5eaf-ad17-efec3ba606cd','Eksperymenty','Czy ptak tonie? Piórko i woda',false,false,'2027-01-11','{"id": "2027-01-11-eksperymenty", "day": "2027-01-11", "weekday": null, "option": 9, "title": "Czy ptak tonie? Piórko i woda", "type": "eksperymenty", "category": "Eksperymenty", "duration_min": "10-20", "goal": "Obserwuje, że pióro nie nasiąka.", "materials": "miska z wodą, duże pióro, chusteczka papierowa", "steps": ["Kładziemy chusteczkę na wodę – nasiąka.", "Pióro – pływa, woda spływa.", "Mówimy: piórka chronią ptaka.", "Wycieramy."], "easier": "Patrzenie.", "harder": "Przewidywanie.", "variant_1y": "Patrzenie.", "variant_2_3y": "Przewidywanie.", "song": "Chusteczka – mokra, tonie – plum, / piórko – pływa, suche – hm! / Ptaszek w deszczu suchy jest – / piórka chronią go – o, cześć!", "song_author": "własna (KMK/Malachim)", "safety": "Mała ilość wody; nadzór.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a63db6d7-7421-5432-9c10-b39be81e532f','Plastyka','Ptaszek z dłoni',false,false,'2027-01-11','{"id": "2027-01-11-plastyka", "day": "2027-01-11", "weekday": null, "option": 10, "title": "Ptaszek z dłoni", "type": "plastyka", "category": "Plastyka", "duration_min": "10-20", "goal": "Odbija dłoń jako ptaka.", "materials": "farby, kartka", "steps": ["Malujemy dłoń (kciuk – głowa).", "Odbijamy – ptaszek.", "Dorysowujemy dziób i nóżki.", "Podpisujemy."], "easier": "Odbicie z pomocą.", "harder": "Dorysowanie samodzielne.", "variant_1y": "Odbicie z pomocą.", "variant_2_3y": "Dorysowanie samodzielne.", "song": "Kciuk to główka, palce – skrzydła, / plask! – i ptaszek z mojej ręki! / Dziób, nóżki – narysuję, / ptaszek gotów – fru, frunę!", "song_author": "własna (KMK/Malachim)", "safety": "Farby z atestem.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('1f524073-e892-5a94-b0f7-91d75b114764','Samoobsługa','Sam jem łyżką – jak ptaszek dziobem',false,false,'2027-01-11','{"id": "2027-01-11-samoobsluga", "day": "2027-01-11", "weekday": null, "option": 11, "title": "Sam jem łyżką – jak ptaszek dziobem", "type": "samoobsluga", "category": "Samoobsługa", "duration_min": "10-20", "goal": "Ćwiczy jedzenie łyżką.", "materials": "miska, łyżka, kasza/owsianka (posiłek)", "steps": ["Przy posiłku mówimy o ptaszkach.", "Nabieramy łyżką.", "Do buzi – „dziób”.", "Odkładamy łyżkę."], "easier": "Z pomocą ręki.", "harder": "Samodzielnie.", "variant_1y": "Z pomocą ręki.", "variant_2_3y": "Samodzielnie.", "song": "Ptaszek dzióbkiem – ja łyżeczką, / nabieram, niosę – mniam, troszeczkę! / Nie rozlewam – powoli, ostrożnie, / sam zjadam – bardzo pięknie!", "song_author": "własna (KMK/Malachim)", "safety": "Tylko w czasie posiłku, siedząc; konsystencja dostosowana do wieku.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('e33e5a79-c7ce-5702-bad0-52588b8c8d46','Język/logorytmika','Ćwir, kra, gru',false,false,'2027-01-11','{"id": "2027-01-11-jezyk-logorytmika", "day": "2027-01-11", "weekday": null, "option": 12, "title": "Ćwir, kra, gru", "type": "jezyk-logorytmika", "category": "Język/logorytmika", "duration_min": "10-20", "goal": "Ćwiczy wargi i głoski.", "materials": "brak", "steps": ["Ćwir – usta w dziobek.", "Kra – szeroko.", "Gru – zaokrąglone.", "Sekwencja."], "easier": "1 dźwięk.", "harder": "Sekwencja.", "variant_1y": "1 dźwięk.", "variant_2_3y": "Sekwencja.", "song": "Ćwir, ćwir – wróbelek, / kra, kra – wrona, / gru, gru – gołąbek, / a ja? La, la, la – piosenka zielona!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('543d989f-9938-5575-bd1b-6df171d41c40','Zabawy paluszkowe i masażyki','Ptaszki dziobią ziarenka',false,false,'2027-01-11','{"id": "2027-01-11-zabawy-paluszkowe-i-masazyki", "day": "2027-01-11", "weekday": null, "option": 13, "title": "Ptaszki dziobią ziarenka", "type": "zabawy-paluszkowe-i-masazyki", "category": "Zabawy paluszkowe i masażyki", "duration_min": "10-20", "goal": "Masażyk palcami.", "materials": "brak", "steps": ["Ptaszki przylatują – palce chodzą po plecach.", "Dziobią – delikatne stuknięcia.", "Machają skrzydłami – głaskanie.", "Odlatują – łaskotki."], "easier": "Lekko.", "harder": "Koledze.", "variant_1y": "Lekko.", "variant_2_3y": "Koledze.", "song": "Przylatują ptaszki – tup, tup, tup, / dziobią ziarnka – puk, puk, puk, / machają skrzydłami – szu, szu, szu, / i odlatują – fru!", "song_author": "własna (KMK/Malachim)", "safety": "Za zgodą.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('8aa5467c-36da-5e9a-93a5-ee17e802c424','Zabawy słowno-ruchowe i rymowanki','Wróbelek skacze',false,false,'2027-01-11','{"id": "2027-01-11-zabawy-slowno-ruchowe-i-rymowanki", "day": "2027-01-11", "weekday": null, "option": 14, "title": "Wróbelek skacze", "type": "zabawy-slowno-ruchowe-i-rymowanki", "category": "Zabawy słowno-ruchowe i rymowanki", "duration_min": "10-20", "goal": "Skoki obunóż.", "materials": "brak", "steps": ["Skaczemy jak wróbel.", "Zatrzymujemy się – rozglądamy.", "Dziobiemy.", "Odlatujemy."], "easier": "Skoki z pomocą.", "harder": "Samodzielnie.", "variant_1y": "Skoki z pomocą.", "variant_2_3y": "Samodzielnie.", "song": "Hop, hop – wróbelek, / rozgląda się – w prawo, w lewo, / dziob, dziob – ziarenko, / fru! – do nieba wysoko!", "song_author": "własna (KMK/Malachim)", "safety": "Na macie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('6dde5bc0-32a0-58fc-af2e-5aad776a5874','Powitania i integracja','Ptaszki się witają',false,false,'2027-01-11','{"id": "2027-01-11-powitania-i-integracja", "day": "2027-01-11", "weekday": null, "option": 15, "title": "Ptaszki się witają", "type": "powitania-i-integracja", "category": "Powitania i integracja", "duration_min": "10-20", "goal": "Wita się dźwiękiem ptaka.", "materials": "brak", "steps": ["Siadamy w kole.", "Każdy wita się „ćwir, (imię)”.", "Machamy skrzydełkami.", "Wszyscy ćwir."], "easier": "Machanie.", "harder": "Mówienie.", "variant_1y": "Machanie.", "variant_2_3y": "Mówienie.", "song": "Ćwir, ćwir – dzień dobry, ptaszku, / (imię) – witamy cię, pomachaj skrzydłem! / Ćwir, ćwir – cała gromadka, / ptasia rodzinka w komplecie, gładka!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('aadeb50d-e039-5366-b14a-83b5f8a0f04e','Świadomość ciała','Ptak ma, ja mam',false,false,'2027-01-11','{"id": "2027-01-11-swiadomosc-ciala", "day": "2027-01-11", "weekday": null, "option": 16, "title": "Ptak ma, ja mam", "type": "swiadomosc-ciala", "category": "Świadomość ciała", "duration_min": "10-20", "goal": "Porównuje części ciała ptaka i człowieka.", "materials": "obrazek ptaka", "steps": ["Ptak ma skrzydła – ja ręce.", "Dziób – ja usta.", "Pióra – ja włosy.", "Nóżki – ja nogi."], "easier": "Pokazywanie.", "harder": "Nazywanie.", "variant_1y": "Pokazywanie.", "variant_2_3y": "Nazywanie.", "song": "Ptak ma skrzydła – ja mam ręce, / ptak ma dziób – ja buzię wiercę! / Ptak ma nóżki – ja mam nogi, / razem idziemy w różne drogi!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('12358809-8665-541c-84f2-720f2164f268','Pamięć/uwaga/naśladowanie','Który ptaszek odleciał?',false,false,'2027-01-11','{"id": "2027-01-11-pamiec-uwaga-nasladowanie", "day": "2027-01-11", "weekday": null, "option": 17, "title": "Który ptaszek odleciał?", "type": "pamiec-uwaga-nasladowanie", "category": "Pamięć/uwaga/naśladowanie", "duration_min": "10-20", "goal": "Ćwiczy pamięć.", "materials": "3 pluszowe ptaszki / obrazki", "steps": ["Ustawiamy ptaszki.", "Nazywamy kolory.", "Zamykamy oczy – jeden odlatuje.", "Kogo brak?"], "easier": "2 ptaszki.", "harder": "3–4.", "variant_1y": "2 ptaszki.", "variant_2_3y": "3–4.", "song": "Trzy ptaszki na gałązce siedzą, / jeden fru – a gdzie, nie wiedzą! / Otwórz oczy – kto odleciał? / Gil czerwony? Tak – brawo, wiedziałaś!", "song_author": "własna (KMK/Malachim)", "safety": "Pluszaki bez oczek-guzików.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('60da3825-d999-584a-ac83-2341f4726149','Zabawy poznawcze','Ile ptaszków?',false,false,'2027-01-11','{"id": "2027-01-11-zabawy-poznawcze", "day": "2027-01-11", "weekday": null, "option": 18, "title": "Ile ptaszków?", "type": "zabawy-poznawcze", "category": "Zabawy poznawcze", "duration_min": "10-20", "goal": "Liczy do 3.", "materials": "obrazki ptaków, karmnik z kartonu", "steps": ["Kładziemy ptaszki do karmnika.", "Liczymy 1, 2, 3.", "Jeden odlatuje – ile zostało?", "Dodajemy."], "easier": "1–2.", "harder": "Do 3.", "variant_1y": "1–2.", "variant_2_3y": "Do 3.", "song": "Jeden ptaszek przyleciał – ćwir, / drugi ptaszek przyleciał – ćwir, / trzeci ptaszek – ćwir, ćwir, ćwir – / ile ich jest? Trzy – brawo, ty!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('fdf6a295-804f-5c82-a608-608bc46f8c76','Zabawy na dworze','Spacer do karmnika',false,false,'2027-01-11','{"id": "2027-01-11-zabawy-na-dworze", "day": "2027-01-11", "weekday": null, "option": 19, "title": "Spacer do karmnika", "type": "zabawy-na-dworze", "category": "Zabawy na dworze", "duration_min": "10-20", "goal": "Obserwuje ptaki z bliska.", "materials": "ciepłe ubranie", "steps": ["Idziemy cicho do karmnika w parku/ogrodzie.", "Obserwujemy z odległości.", "Nazywamy ptaki.", "Dorosły dosypuje ziarno."], "easier": "W wózku.", "harder": "Pieszo.", "variant_1y": "W wózku.", "variant_2_3y": "Pieszo.", "song": "Cichutko idziemy, nie tupiemy, / ptaszków przy karmniku nie płoszymy! / Sikorka, wróbel – ćwir, ćwir, ćwir – / smacznego, ptaszki – pa, pa, wy!", "song_author": "własna (KMK/Malachim)", "safety": "Dzieci nie dotykają ziarna, słoniny, odchodów; myjemy ręce po powrocie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('c547e1ee-52f1-589a-aa49-b9bfcf16eda5','Higiena','Myjemy ręce po spacerze',false,false,'2027-01-11','{"id": "2027-01-11-higiena", "day": "2027-01-11", "weekday": null, "option": 20, "title": "Myjemy ręce po spacerze", "type": "higiena", "category": "Higiena", "duration_min": "10-20", "goal": "Utrwala mycie po dworze.", "materials": "umywalka, mydło", "steps": ["Po spacerze – mycie rąk.", "Mydło, pianka.", "Spłukujemy.", "Wycieramy."], "easier": "Z opiekunką.", "harder": "Samodzielnie.", "variant_1y": "Z opiekunką.", "variant_2_3y": "Samodzielnie.", "song": "Byłem w parku, przy ptaszkach – / teraz rączki myję wszystkie! / Szu, szu – mydło, plusk – woda, / czyste rączki – to jest moda!", "song_author": "własna (KMK/Malachim)", "safety": "Letnia woda.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('d4c8ace1-b23d-5662-9ed0-d6e1fcb37a57','Czytanie dziecku','Sikorka i pusty karmnik (opowiadanie)',false,false,'2027-01-11','{"id": "2027-01-11-czytanie-dziecku", "day": "2027-01-11", "weekday": null, "option": 21, "title": "Sikorka i pusty karmnik (opowiadanie)", "type": "czytanie-dziecku", "category": "Czytanie dziecku", "duration_min": "10-20", "goal": "Słucha historii o pomocy zwierzętom.", "materials": "obrazki: karmnik pusty i pełny, sikorka", "steps": ["Opowiadaj: „Sikorka przyleciała – karmnik pusty. Smutna. Dzieci powiedziały pani – pani nasypała ziarna. Sikorka śpiewała dziękuję”.", "Pokazuj obrazki.", "Dzieci mówią „ćwir, dziękuję”.", "Pytamy: kto pomógł?"], "easier": "Słuchanie.", "harder": "Odpowiedź.", "variant_1y": "Słuchanie.", "variant_2_3y": "Odpowiedź.", "song": "Pusty karmnik – sikorce smutno, / dzieci widzą – pani, szybko! / Ziarenka są – ćwir, dziękuję, / sikorka śpiewa, dzieci całuje!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('9cdbf9c4-13c1-5c33-a4b0-cf36ad418391','Klocki/budowanie','Karmnik z klocków',false,false,'2027-01-11','{"id": "2027-01-11-klocki-budowanie", "day": "2027-01-11", "weekday": null, "option": 22, "title": "Karmnik z klocków", "type": "klocki-budowanie", "category": "Klocki/budowanie", "duration_min": "10-20", "goal": "Buduje konstrukcję z daszkiem.", "materials": "duże klocki, tektura", "steps": ["Budujemy 2 słupki.", "Daszek z tektury.", "Wkładamy ptaszki-pluszaki.", "Mówimy: smacznego."], "easier": "Wkładanie ptaszków.", "harder": "Budowanie.", "variant_1y": "Wkładanie ptaszków.", "variant_2_3y": "Budowanie.", "song": "Słupek, słupek, daszek – już, / karmnik stoi – ptaszki tu! / Ćwir, ćwir – siadają w środku, / smacznego wam, ptaszki w kącie!", "song_author": "własna (KMK/Malachim)", "safety": "Klocki lekkie.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('f1722de9-bbae-500e-ba0a-ee98c8f8933c','Wyciszenie','Ptaszki śpią',false,false,'2027-01-11','{"id": "2027-01-11-wyciszenie", "day": "2027-01-11", "weekday": null, "option": 23, "title": "Ptaszki śpią", "type": "wyciszenie", "category": "Wyciszenie", "duration_min": "10-20", "goal": "Wycisza.", "materials": "koc", "steps": ["Ptaszki zmęczone – siadają na gałązce.", "Chowają głowę pod skrzydło – przytulamy się.", "Oddychamy wolno.", "Cisza."], "easier": "Przy opiekunce.", "harder": "Samodzielnie.", "variant_1y": "Przy opiekunce.", "variant_2_3y": "Samodzielnie.", "song": "Ptaszek siada, skrzydło składa, / główkę chowa – cicho, sza. / Śpi wróbelek, śpi sikorka, / i ja śpię – do wieczorka.", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('a259bb1d-4bfe-5b56-93ff-a764a3253578','Empatia','Pomagamy ptakom zimą',false,false,'2027-01-11','{"id": "2027-01-11-empatia", "day": "2027-01-11", "weekday": null, "option": 24, "title": "Pomagamy ptakom zimą", "type": "empatia", "category": "Empatia", "duration_min": "10-20", "goal": "Uczy dbania o zwierzęta.", "materials": "obrazki: karmnik, poidełko", "steps": ["Pytamy: co potrzebuje ptak zimą?", "Jedzenie – karmnik.", "Woda – poidełko.", "Nie płoszymy."], "easier": "Wskazanie.", "harder": "Mówienie.", "variant_1y": "Wskazanie.", "variant_2_3y": "Mówienie.", "song": "Ptaszku, ptaszku – pomogę ci, / ziarenko dorosły nasypie – ćwir! / Wodę damy, cicho stoimy – / ptaszki zimą chronimy!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('cee479fb-8052-5a40-8ccc-2cb5548ebe09','Rodzina i dom','Karmnik w domu',false,false,'2027-01-11','{"id": "2027-01-11-rodzina-i-dom", "day": "2027-01-11", "weekday": null, "option": 25, "title": "Karmnik w domu", "type": "rodzina-i-dom", "category": "Rodzina i dom", "duration_min": "10-20", "goal": "Zachęca rodzinę do dokarmiania.", "materials": "obrazek karmnika, kartka do domu", "steps": ["Pytamy: czy macie karmnik?", "Kto sypie ziarno?", "Dajemy rodzicom kartkę z prośbą.", "Opowiadamy jutro."], "easier": "Słuchanie.", "harder": "Opowiadanie.", "variant_1y": "Słuchanie.", "variant_2_3y": "Opowiadanie.", "song": "Tata zawiesi karmnik na drzewie, / mama nasypie – ptaszek się cieszy! / A ja popatrzę przez okno z bliska – / ptaszki mam w domu – wszystkie, wszystkie!", "song_author": "własna (KMK/Malachim)", "safety": "Ziarno sypie dorosły.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('5c867538-2df3-5887-b9c9-9584701e7b37','Pory roku i święta','Zima – ptaki zostają i odlatują',false,false,'2027-01-11','{"id": "2027-01-11-pory-roku-i-swieta", "day": "2027-01-11", "weekday": null, "option": 26, "title": "Zima – ptaki zostają i odlatują", "type": "pory-roku-i-swieta", "category": "Pory roku i święta", "duration_min": "10-20", "goal": "Poznaje ptaki zimujące i odlatujące.", "materials": "obrazki: bocian (odlatuje), sikorka (zostaje)", "steps": ["Bocian odleciał do ciepłych krajów.", "Sikorka została.", "Pokazujemy, kto gdzie.", "Machamy bocianowi."], "easier": "Wskazanie.", "harder": "Sortowanie.", "variant_1y": "Wskazanie.", "variant_2_3y": "Sortowanie.", "song": "Bocian odleciał – pa, pa, pa, / wróci na wiosnę, wiem to ja! / Sikorka została, mróz jej nie straszny – / zima z ptakami jest bardzo ważna!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
insert into public.test_lessons(id,module,title,enabled,pinned,week_start,content) values('2d5b81a2-c961-5f3b-ae6c-d0d696b825d8','Kolory/kształty/wielkości','Kolorowe brzuszki ptaków',false,false,'2027-01-11','{"id": "2027-01-11-kolory-ksztalty-wielkosci", "day": "2027-01-11", "weekday": null, "option": 27, "title": "Kolorowe brzuszki ptaków", "type": "kolory-ksztalty-wielkosci", "category": "Kolory/kształty/wielkości", "duration_min": "10-20", "goal": "Rozpoznaje kolory.", "materials": "obrazki: gil (czerwony), sikorka (żółty), wróbel (brązowy), sroka (czarno-biała)", "steps": ["Pokazujemy brzuszki.", "Nazywamy kolory.", "Szukamy takiego koloru w sali.", "Sortujemy."], "easier": "1 kolor.", "harder": "4 kolory.", "variant_1y": "1 kolor.", "variant_2_3y": "4 kolory.", "song": "Gil – czerwony, sikorka – żółta, / wróbel – brązowy, sroka – czarno-biała! / Kolorowe ptaszki zimą – / znajdź ten kolor – sprawdź, ten jest!", "song_author": "własna (KMK/Malachim)", "safety": "Brak.", "safety_common": "Zawsze: dorosły cały czas przy dzieciach; żadnych przedmiotów mniejszych niż rolka po papierze toaletowym; sprawdź alergie.", "source": "nowy-2026", "reused_from": null, "module": "Ptaki zimą – karmnik", "age": "1-3", "group": null}'::jsonb) on conflict (id) do update set module=excluded.module,title=excluded.title,week_start=excluded.week_start,content=excluded.content;
